BEGIN;
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e85d08c1-b81b-566b-80cb-11d18b29d0c8','Snare-bottom polarity inversion','The practice of inverting the polarity of the snare-bottom microphone relative to the snare-top microphone in a two-mic snare setup. Because the two diaphragms face the drum from opposite sides, a downward stroke pushes the top mic''s diaphragm inward while pushing the bottom mic''s outward, so their outputs are largely out of polarity; flipping the bottom mic''s polarity realigns them so their low-frequency content reinforces rather than cancels when the mics are summed.','A snare is often recorded with one mic on top and one below. The two mics face each other, so they push and pull in opposite ways. Mixed together, this can make the snare sound thin. Flipping the polarity of the bottom mic fixes it, so both mics add up instead of fighting.','It exists to prevent low-frequency cancellation between the top and bottom snare mics, preserving body and punch when both are blended in the mix.','After patching a top and bottom snare mic, the engineer sums both in mono, listens or checks the waveform, and engages the polarity switch on the bottom channel to whichever position gives the fuller, punchier snare.','Phase & polarity',ARRAY['Polarity switch','Phase cancellation','Snare-wire balance','3:1 rule','Comb filtering']::text[],ARRAY['Confusing polarity inversion with time delay; flipping polarity reverses the signal but does not correct an arrival-time difference between mics.','Assuming the bottom mic always needs inversion; the correct switch position depends on the mics, cabling and drum, so it must be checked by ear each time.','UNSAFE: Unplugging or hot-patching a mic while phantom power is live can send a loud pop into monitors; mute the channel and let phantom power settle before patching to protect gear and hearing.']::text[],ARRAY['Recording a rock drum kit with dynamic mics on the top and bottom snare heads.','Checking snare polarity during a live line check at front of house.','Editing a multitrack session and toggling bottom-snare polarity to restore lost low end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e85d08c1-b81b-566b-80cb-11d18b29d0c8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Snare-bottom polarity inversion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e85d08c1-b81b-566b-80cb-11d18b29d0c8','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
