INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd4d34fff-197d-5505-80cb-59473220feb2','Snare-shell microphone','A supplementary microphone positioned at the side shell (body) of the snare drum, rather than over the batter head, to capture the resonance of the shell and a balanced blend of batter-head tone and snare-wire response. It is used to add body and midrange character and can offer better rejection of hi-hat bleed than a top-head mic.','The shell is the round wooden or metal body of the snare drum. A shell microphone points at that body instead of the top skin. It picks up the drum''s woody tone. It can also catch less noise from the nearby hi-hat.','It exists to capture the tonal character of the drum''s body and to provide an alternative or supplementary snare sound with different bleed and tone than a standard top mic.','An engineer clips or stands a small mic a few centimetres from the shell, angled at the body, and blends it under the main top mic to add weight and reduce cymbal spill.','Drum miking',ARRAY['Snare-vent microphone','Snare-wire balance','Snare-bottom polarity inversion','Bleed (spill)','Clip-on microphone']::text[],ARRAY['Placing the shell mic where it still receives strong hi-hat bleed, defeating one of its main advantages.','Expecting the shell mic alone to deliver crack and snap; it captures body, so it is usually blended with a batter-head mic.','UNSAFE: Snare drums produce very high peak SPL at close range; monitor at safe levels and use hearing protection, because prolonged exposure above 85 dBA can cause permanent hearing loss.']::text[],ARRAY['Adding body to a thin-sounding snare by blending in a mic on the shell.','Reducing hi-hat spill in a tight live-stage drum mix.','Capturing the metallic ring of a brass or bronze snare shell in the studio.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d4d34fff-197d-5505-80cb-59473220feb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Snare-shell microphone'),'[^a-z0-9]','','g'));
