SELECT '25293ec8-3f79-5ea1-8c22-eee39b51524d','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='25293ec8-3f79-5ea1-8c22-eee39b51524d' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f86e665b-12bd-5eb9-aaec-6f402dd6d505','Subkick capture','The technique of capturing the extreme low-frequency (''sub'') content of a kick drum using a large-diameter transducer—typically a loudspeaker driver wired to work in reverse as a microphone, or a dedicated large-diaphragm sub microphone—positioned in front of the batter or resonant head. Its large, low-tuned diaphragm reproduces energy below roughly 100 Hz that conventional kick mics capture weakly, and it is blended under a standard kick mic for weight.','A speaker and a microphone work in opposite ways. So a big speaker can be wired to act as a microphone. Placed in front of a kick drum, this ''subkick'' catches the deep, chest-thumping low notes that normal mics miss. Engineers blend it under a regular kick mic to add weight.','It exists to add deep sub-bass weight and thump to a kick drum that standard close mics under-capture.','The engineer places the subkick a few centimetres from the kick''s resonant head, checks its polarity against the main kick mic, and blends it in low to add sub weight.','Drum miking',ARRAY['Kick drum microphone','Proximity effect','Polarity switch','Phase cancellation','Low-frequency extension']::text[],ARRAY['Ignoring polarity between the subkick and the main kick mic, which can cancel the very low end they are meant to reinforce.','Running the subkick too loud, producing a boomy, undefined low end that masks the beater attack.','Assuming the subkick needs phantom power; a speaker-based subkick is a passive dynamic source and does not use 48 V, so route it like a dynamic mic.','UNSAFE: Working close to a loud kit exposes you to high SPL; protect your hearing, as sustained levels above 85 dBA risk permanent damage.']::text[],ARRAY['Adding sub weight to a kick drum for a modern rock mix.','Reinforcing low end on a kick that sounds thin through close mics.','Blending a subkick under a beater mic for a hip-hop drum sound.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f86e665b-12bd-5eb9-aaec-6f402dd6d505' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Subkick capture'),'[^a-z0-9]','','g'));
