INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '92624a25-2bc4-5f40-a568-dee8764e95f9','Suspended-cymbal swell capture','The technique of recording a suspended cymbal ''swell''—a roll played with mallets that crescendos from near-silence to a loud, shimmering peak—so that both the delicate onset and the full crescendo are captured cleanly. It calls for a microphone and preamp with wide dynamic range and ample headroom, placed to capture the cymbal''s full spectrum without distorting the loud peak.','A suspended cymbal can be rolled with soft mallets so it grows from almost silent to very loud. Capturing this swell means the quiet start must be heard. The loud peak must not distort. Engineers pick a mic and settings with enough headroom to handle both ends.','It exists to record the full dramatic crescendo of an orchestral cymbal swell without losing the soft opening or clipping the loud climax.','The engineer positions a condenser mic above the suspended cymbal, sets preamp gain conservatively to leave headroom for the peak, and checks that the quiet onset still reads clearly above the noise floor.','Percussion miking',ARRAY['Headroom','Dynamic range','Condenser microphone','Spot-microphone time alignment','Transient']::text[],ARRAY['Setting gain for the quiet opening, then clipping the preamp or converter when the swell peaks.','Placing the mic too close, exaggerating one part of the cymbal and catching stick or mallet noise.','UNSAFE: A cymbal swell peaks at high SPL close up; monitor at safe levels and protect your hearing during repeated takes.']::text[],ARRAY['Capturing an orchestral suspended-cymbal crescendo for a film score.','Recording a dramatic swell into a downbeat in a pop production.','Miking a percussionist''s cymbal roll in a live classical broadcast.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='92624a25-2bc4-5f40-a568-dee8764e95f9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Suspended-cymbal swell capture'),'[^a-z0-9]','','g'));
