INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1dfb31ee-3745-5600-9cb5-0fb314d74c57','Tabla dayan–bayan split','A close-miking approach for the tabla, a North Indian hand-drum pair, that captures the two drums on separate microphones: the smaller, higher-pitched, tuned dayan (played with the dominant hand) and the larger, deep-toned bayan (played with the other hand and pitch-bent by heel-of-hand pressure). Splitting them onto individual channels allows independent control of level, tone and processing for each drum.','A tabla is a pair of hand drums. The small one, the dayan, has a high, tuned pitch. The large one, the bayan, makes deep bass notes that the player bends by hand. Recording each with its own microphone lets the engineer balance and treat the two sounds separately.','It exists to give the engineer separate control over the bright, tuned dayan and the deep, pitch-bending bayan, which have very different tone and level needs.','The engineer aims one mic at the dayan and another at the bayan, using placement and directional patterns to limit each mic picking up the other drum.','Percussion miking',ARRAY['Bleed (spill)','3:1 rule','Close miking','Spot-microphone time alignment','Polar pattern']::text[],ARRAY['Placing the two mics without regard to the 3:1 rule, so heavy bleed between dayan and bayan causes phase problems.','Miking the bayan off its playing area so its characteristic hand-bent bass pitch is lost.','Treating both drums with one identical EQ, ignoring their very different frequency ranges.']::text[],ARRAY['Recording a tabla in a fusion session that needs separate control of each drum.','Isolating the bayan''s bass for independent compression.','Capturing a classical tabla accompaniment with two spot mics.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1dfb31ee-3745-5600-9cb5-0fb314d74c57' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tabla dayan–bayan split'),'[^a-z0-9]','','g'));
