INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3a10527a-48d0-5acb-b872-4b360347f6db','Tea-towel drum damping','A damping technique in which a folded cloth—traditionally a cotton tea towel—is laid over part of a drum head, most often the batter head of a snare or kick, to shorten sustain and tame ring and overtones. The added mass and light contact absorb head vibration, producing a drier, more controlled tone favoured for close-miked pop and rock recording.','A tea towel is a thin kitchen cloth. Laying one on a drum head soaks up some of the ring. The drum then sounds shorter and drier, which records more cleanly up close.','It reduces unwanted ringing and sustain at the source, so the close mic captures a tighter, more controlled sound and needs less heavy gating or EQ later.','An engineer folds a towel over the edge of the snare or across the kick batter head, adjusting how much it covers until the ring is tamed but the drum still has body.','Drum damping',ARRAY['Close miking','Kick drum microphone','Under-snare microphone','Noise gate','Overhead microphone','Resonant head']::text[],ARRAY['Covering too much of the head so the drum is fully choked, killing tone and sustain the mix actually needs.','Using the towel to hide tuning or snare-buzz problems that should be fixed by tuning or dressing the snares first.','Assuming damping fixes bleed; it lowers ring but the close mic still picks up the rest of the kit.']::text[],ARRAY['Drying out a ringy snare for a tight modern pop production.','Taming a boomy kick drum before close miking for rock tracking.','Reducing overtones on a rented kit that cannot be retuned quickly during a session.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3a10527a-48d0-5acb-b872-4b360347f6db' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tea-towel drum damping'),'[^a-z0-9]','','g'));
