SELECT '3a10527a-48d0-5acb-b872-4b360347f6db','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3a10527a-48d0-5acb-b872-4b360347f6db' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9d289974-0e10-5c48-bf7e-7a43b78e2a11','Timpani bowl-side miking','A timpani (kettledrum) placement in which the microphone is aimed toward the side or underside of the drum''s bowl rather than over the batter head, emphasising the instrument''s low-frequency resonance and pitch while de-emphasising the sharp stick attack heard directly above the head.','A timpani is a large kettle-shaped drum. Aiming the mic toward the bowl, not the top, brings out its deep, round tone. You then hear less of the hard stick hit.','It exists to capture the full low body of the timpani and its clear pitch, giving a warmer sound with less transient attack than an overhead placement.','A classical engineer angles a spot mic toward the lower bowl of each drum to reinforce weight and pitch beneath a main orchestral pair.','Percussion miking',ARRAY['Timpani head-edge miking','Timpani pair spacing','Spot microphone','Overhead microphone','Proximity effect','Polar pattern']::text[],ARRAY['Placing the mic so close to the bowl that it captures resonance boom but loses the pitch definition players expect.','Ignoring the main orchestral pair, so the spot mic sounds detached and unnaturally close in the mix.','UNSAFE: Working right beside timpani at fortissimo for long sessions without hearing protection risks noise-induced hearing loss.']::text[],ARRAY['Adding low-end weight to timpani in a film-score session under a main pair.','Spot-miking timpani in a concert hall where the overheads alone lack body.','Reinforcing timpani pitch in a large orchestral recording for clarity in the mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9d289974-0e10-5c48-bf7e-7a43b78e2a11' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timpani bowl-side miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9d289974-0e10-5c48-bf7e-7a43b78e2a11','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9d289974-0e10-5c48-bf7e-7a43b78e2a11' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0854ef11-4f67-533a-be79-15d0f4baa9d6','Timpani head-edge miking','A timpani placement in which the microphone is positioned over the head near its edge—above the normal playing spot, roughly a third of the way in from the rim—rather than at the centre, capturing a balanced blend of attack and tone because that playing area radiates the instrument''s characteristic sound.','Players strike a timpani near the edge, not the middle. Putting the mic over that spot captures the true tone. You get both the hit and the ringing note.','It targets the part of the head that produces the instrument''s musical pitch and articulation, giving a natural, well-balanced close sound.','An engineer sets a spot mic a short distance above the head near the playing area, avoiding the dead centre, which sounds dull and lacks pitch.','Percussion miking',ARRAY['Timpani bowl-side miking','Timpani pair spacing','Spot microphone','Overhead microphone','Close miking','Proximity effect']::text[],ARRAY['Aiming the mic at the centre of the head, where the fundamental is weak and the tone sounds dead and thuddy.','Placing the mic so low it sits in the mallet''s path and picks up excessive attack or gets struck.','UNSAFE: Close, prolonged exposure to timpani at full volume without hearing protection can cause permanent hearing damage.']::text[],ARRAY['Close-miking a pair of timpani for a percussion feature in a studio recording.','Capturing clear timpani articulation for a concerto where the part is exposed.','Reinforcing timpani in a live orchestral broadcast that needs defined low rolls.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0854ef11-4f67-533a-be79-15d0f4baa9d6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timpani head-edge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0854ef11-4f67-533a-be79-15d0f4baa9d6','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0854ef11-4f67-533a-be79-15d0f4baa9d6' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ef16294c-e44c-513b-a3fa-ed4e30825403','Timpani pair spacing','The practice of setting the distance and angle between microphones when covering two or more timpani, chosen so each drum is captured evenly and spacing follows guidance such as the 3:1 rule—keeping adjacent mics at least three times as far apart as each is from its drum—to minimise phase cancellation and comb filtering between channels.','Timpani often come in sets of two or more drums. Spacing the mics well keeps each drum even and clear. Good spacing also stops the mics from fighting and thinning the sound.','Proper spacing balances loudness across the drums and avoids comb-filtering, so the group sounds cohesive rather than uneven or hollow.','An engineer measures mic-to-head distances and keeps neighbouring mics roughly three times as far apart as each is from its drum, then checks the sum in mono for phase.','Percussion miking',ARRAY['Timpani head-edge miking','Timpani bowl-side miking','3:1 rule','Comb filtering','Phase cancellation','Spot microphone']::text[],ARRAY['Spacing mics too close together, so overlapping pickup causes comb filtering and a hollow, phasey timpani sound.','Setting unequal distances so one drum is much louder than the others in the captured balance.','Forgetting to check the sum in mono, which hides phase problems that appear on mono playback systems.']::text[],ARRAY['Miking a four-drum timpani set for a large studio orchestra date.','Balancing a pair of timpani that a single spot mic cannot cover evenly.','Setting spacing to stay phase-compatible with the overheads on a live classical capture.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ef16294c-e44c-513b-a3fa-ed4e30825403' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Timpani pair spacing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ef16294c-e44c-513b-a3fa-ed4e30825403','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ef16294c-e44c-513b-a3fa-ed4e30825403' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c0f7b369-3520-502f-b161-bab5a79aa1e3','Tom-bottom microphone','A microphone placed beneath a tom-tom, close to the resonant (bottom) head, used alongside or instead of a top mic to add attack, note definition and low-frequency body; because the bottom head moves opposite to the top head, its signal is usually polarity-inverted to stay in phase with the top mic.','A tom has two heads, top and bottom. A mic under the bottom head adds punch and depth. Its signal is usually flipped so it works with the top mic, not against it.','It captures the resonant head''s tone and attack to make toms fuller and more defined, letting the engineer blend top and bottom for the desired weight.','An engineer clips a mic a few centimetres under the resonant head and flips its polarity, then blends it with the top mic until the tom has punch without phase cancellation.','Drum miking',ARRAY['Underhead tom miking','Under-snare microphone','Polarity inversion','Resonant head','Close miking','Overhead microphone']::text[],ARRAY['Forgetting to invert polarity, so the bottom mic cancels the top mic and the tom loses body.','Placing the mic in a bottom-head vent''s airflow or too close, causing rattle or wind noise.','UNSAFE: Leaning into a loud kit at close range for long tracking sessions without hearing protection risks hearing loss.']::text[],ARRAY['Adding attack and depth to floor toms in a rock production.','Reinforcing tom sustain that overheads alone cannot deliver in a dense mix.','Recording a drum kit where each tom needs isolated, punchy processing.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c0f7b369-3520-502f-b161-bab5a79aa1e3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tom-bottom microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c0f7b369-3520-502f-b161-bab5a79aa1e3','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c0f7b369-3520-502f-b161-bab5a79aa1e3' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '48a6c06c-5e7c-5b6a-92f0-299913078492','Tone-hole-side miking','A woodwind placement in which the microphone is aimed toward the instrument''s tone holes rather than the bell, because most woodwind notes radiate primarily from the first open tone hole and only the lowest notes leave the bell; this captures a more even tonal balance across the instrument''s range.','A woodwind''s sound mostly comes out of its open finger holes, not the bell. Aiming the mic at the holes gives an even tone across all notes. Aiming only at the bell can sound harsh.','It exists to get a balanced, natural woodwind tone across the full range, since only the lowest notes actually project from the bell.','On saxophone or clarinet, an engineer places the mic over the body toward the upper tone holes rather than into the bell to avoid a honky, uneven sound.','Woodwind miking',ARRAY['Close miking','Proximity effect','Polar pattern','Spot microphone','Trombone over-slide miking','Off-axis']::text[],ARRAY['Pointing the mic straight into the bell, which over-emphasises the lowest notes and sounds uneven across the range.','Placing the mic so close to the keys it captures loud key-click and pad noise.','Assuming the bell is the main sound source, as it is for brass; on woodwinds it usually is not.']::text[],ARRAY['Close-miking a saxophone for a horn section where bell miking sounds honky.','Recording clarinet in a studio and needing even tone from low to high register.','Miking a flute toward its embouchure and tone holes rather than the far end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='48a6c06c-5e7c-5b6a-92f0-299913078492' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tone-hole-side miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '48a6c06c-5e7c-5b6a-92f0-299913078492','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='48a6c06c-5e7c-5b6a-92f0-299913078492' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a728e4c1-20bc-5ce5-a316-6709166e7772','Treble-side bridge miking','A close-miking placement for a stringed instrument such as acoustic guitar in which the microphone is positioned near the bridge on the treble (higher-string) side, emphasising string attack, brightness and articulation while capturing less of the body''s low-frequency warmth.','The bridge is where the strings meet the body. Miking near its treble side, by the thin strings, brings out brightness and pick attack. You get less deep body tone from there.','It exists to add clarity and cut, letting a guitar''s attack and high strings sit forward in a mix, often paired with a second mic for balance.','An engineer aims a mic at the treble side of the bridge to brighten a strummed or fingerpicked part, blending it with a twelfth-fret mic for a fuller sound.','String miking',ARRAY['Twelfth-fret miking','Proximity effect','Close miking','3:1 rule','Sound hole','Polar pattern']::text[],ARRAY['Placing the mic too close over the bridge, so proximity effect and body thump muddy the intended brightness.','Using only the bridge mic, giving a thin, brittle tone with no body warmth.','Combining bridge and neck mics without checking phase, causing comb filtering between them.']::text[],ARRAY['Brightening a rhythm acoustic guitar so it cuts through a dense band mix.','Blending a bridge mic with a twelfth-fret mic for a balanced solo-guitar recording.','Adding attack to a fingerpicked part that sounds dull from the sound-hole side.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a728e4c1-20bc-5ce5-a316-6709166e7772' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Treble-side bridge miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a728e4c1-20bc-5ce5-a316-6709166e7772','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a728e4c1-20bc-5ce5-a316-6709166e7772' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5510046d-9795-5c64-9f24-f2d5b7bef8c4','Trombone over-slide miking','A trombone placement in which the microphone is positioned above and in front of the bell, clear of the slide''s full range of travel, so the moving slide never strikes the mic while the bell''s sound is still captured slightly off-axis.','A trombone''s slide shoots far out as it plays. Putting the mic above the bell keeps it out of the slide''s way. The player can move freely and never hit the mic.','It exists to capture a trombone up close without the moving slide colliding with the mic, while keeping a natural bell tone.','In a horn section or live setting, an engineer clamps or stands the mic above the bell line, angled down, so first- through seventh-position slide moves stay clear.','Brass miking',ARRAY['Tuba bell-height miking','Proximity effect','Close miking','Off-axis','Polar pattern','Spot microphone','Slide-path clearance']::text[],ARRAY['Placing the mic directly in front of the bell in the slide''s path, risking a collision that damages the mic or ruins the take.','Aiming straight into the bell up close, producing a harsh, blaring tone with too much high-frequency edge.','UNSAFE: Standing close to loud brass for long sessions without hearing protection can cause permanent hearing damage.']::text[],ARRAY['Miking a trombone in a tight horn section on a small stage.','Recording a trombone soloist who uses full slide extension.','Live-miking trombones where players move and the mic must stay clear of the slide.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5510046d-9795-5c64-9f24-f2d5b7bef8c4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Trombone over-slide miking'),'[^a-z0-9]','','g'));
