INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5395eb37-8f68-567c-8841-ff39f0a95d61','Tuba bell-height miking','A placement for tuba and similar upward-facing large brass in which the microphone is set near the height of the upward-pointing bell, above and slightly off the bell''s axis, to capture the instrument''s broad low-frequency radiation without excessive air blast or harshness.','A tuba''s bell usually points up. Placing the mic up at bell height, just off to one side, captures its big low sound. Sitting right over the bell can add too much air blast.','It exists to capture the tuba''s deep, wide-radiating tone evenly, since low brass spreads sound broadly and needs some distance for balance.','An engineer raises a stand or boom to the tuba''s bell height and angles the mic slightly off-axis, giving distance for the low frequencies to develop.','Brass miking',ARRAY['Trombone over-slide miking','Proximity effect','Close miking','Polar pattern','Spot microphone','Off-axis']::text[],ARRAY['Placing the mic right over the bell, capturing air blast and an unnaturally boomy, uneven low end.','Miking too far off to the side, thinning the fundamental and losing the tuba''s weight.','UNSAFE: Working at close range to loud low brass for extended periods without hearing protection risks hearing loss.']::text[],ARRAY['Miking a tuba in a brass quintet studio session.','Reinforcing tuba in a live brass band where the low end must stay defined.','Adding a spot mic to a tuba under a room pair for orchestral low brass.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5395eb37-8f68-567c-8841-ff39f0a95d61' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tuba bell-height miking'),'[^a-z0-9]','','g'));
