INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf878796-7ebf-5b69-a98b-f862087e68f1','Tubular-bell strike-zone avoidance','A miking practice for tubular bells (orchestral chimes) in which mics are kept away from the top of the tubes where the mallet strikes, positioning them lower along the tubes so the captured sound favours the developing tone rather than the loud metallic attack and mallet noise at the strike point.','Tubular bells are long metal tubes hit at the top with a mallet. Miking right at the top catches a harsh clang and mallet noise. Aiming lower down captures the ringing tone instead.','It exists to capture the bells'' clear, ringing pitch while avoiding the extreme transient and mechanical noise at the strike point, giving a more usable, musical sound.','An engineer positions the mics partway down the tubes rather than over the caps, reducing attack harshness and easing the strain of the loudest transients.','Percussion miking',ARRAY['Timpani head-edge miking','Spot microphone','Overhead microphone','Close miking','Proximity effect','Polar pattern']::text[],ARRAY['Placing the mic directly over the struck caps, capturing a harsh clang and mallet click instead of the tone.','Miking too far down or away, losing the bright attack that gives chimes their character.','UNSAFE: Chimes produce very high peak levels; close, unprotected listening over long sessions risks hearing damage.']::text[],ARRAY['Recording orchestral chimes for a film cue that needs a clean, ringing tone.','Spot-miking tubular bells in a large percussion setup during a live concert.','Capturing chimes for a seasonal-music session without harsh mallet attack.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf878796-7ebf-5b69-a98b-f862087e68f1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tubular-bell strike-zone avoidance'),'[^a-z0-9]','','g'));
