WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bf878796-7ebf-5b69-a98b-f862087e68f1' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54febb1d-c743-5272-98b1-f66d8bbbc422','Twelfth-fret miking','A standard acoustic-guitar placement in which the microphone points at the twelfth fret, where the neck meets the body, providing a balanced blend of string clarity and body resonance and avoiding the boomy low-frequency buildup found directly at the sound hole.','The twelfth fret sits where the guitar neck joins the body. Aiming the mic there gives a balanced, natural tone. It avoids the boomy sound you get right at the hole.','It exists as a reliable starting position that captures even tone—string detail plus body warmth—making the guitar sit well in a mix.','An engineer sets a small-diaphragm condenser a short distance from the twelfth fret as a default, then moves toward the hole for more body or the bridge for more brightness.','String miking',ARRAY['Treble-side bridge miking','Sound hole','Proximity effect','Close miking','3:1 rule','Small-diaphragm condenser']::text[],ARRAY['Aiming the mic straight at the sound hole, which captures a boomy, uneven low-frequency peak.','Placing a cardioid mic too close, so proximity effect over-boosts the low end.','Ignoring the 3:1 rule when adding a second mic, causing comb filtering between them.']::text[],ARRAY['Setting a default single-mic position for a singer-songwriter''s acoustic guitar.','Establishing a balanced starting point before fine-tuning toward the hole or bridge.','Close-miking acoustic guitar on a loud stage where the sound hole would boom.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54febb1d-c743-5272-98b1-f66d8bbbc422' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Twelfth-fret miking'),'[^a-z0-9]','','g'));
