WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54febb1d-c743-5272-98b1-f66d8bbbc422' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3bda5104-4e3a-5685-9a92-9efd871e2222','Under-snare microphone','A microphone placed beneath the snare drum, close to the bottom (snare-side) head and wires, used to capture the bright rattle and buzz of the snares; because the bottom head moves opposite to the top head, this mic is normally polarity-inverted to stay in phase with the top mic.','The snare''s rattling wires sit under the drum. A mic below catches that crisp buzz and snap. Its signal is usually flipped so it adds to the top mic instead of cancelling it.','It exists to capture snare-wire detail and brightness that a top mic alone misses, giving the engineer control over crispness in the blend.','An engineer positions a mic just below the snare wires, inverts its polarity, and blends it under the top mic to add sizzle without hollowing out the body.','Drum miking',ARRAY['Tom-bottom microphone','Underhead tom miking','Polarity inversion','Resonant head','Close miking','Overhead microphone']::text[],ARRAY['Leaving the bottom mic in normal polarity, so it fights the top mic and thins the snare.','Setting bottom-mic level too high, exaggerating wire buzz and hi-hat bleed.','UNSAFE: Working close to a loud kit for long sessions without hearing protection risks hearing damage.']::text[],ARRAY['Adding crisp snare-wire detail to a rock or pop drum recording.','Blending top and bottom snare mics for controllable brightness in the mix.','Reinforcing a dull snare that needs more sizzle without retuning.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3bda5104-4e3a-5685-9a92-9efd871e2222' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Under-snare microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3bda5104-4e3a-5685-9a92-9efd871e2222','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3bda5104-4e3a-5685-9a92-9efd871e2222' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd3fc52cb-a682-547f-9c9b-2742d8c3b966','Underhead microphone','A microphone positioned beneath a drum''s lower (resonant) head and aimed up at it to capture the head''s resonance, attack and—on a snare—the wire buzz; the term covers the general under-head technique of which the under-snare and bottom-tom mics are specific applications, and such mics are typically polarity-inverted to stay in phase with the top mic.','Most drums have a bottom head that also vibrates. A mic under it captures that resonance and buzz. Its signal is usually flipped so it works with the top mic.','It exists to add resonance, attack and wire detail from the underside of a drum, giving the engineer more control than a single top mic allows.','An engineer mounts a mic under the resonant head, inverts polarity, and blends it beneath the top mic to shape body and brightness.','Drum miking',ARRAY['Under-snare microphone','Tom-bottom microphone','Underhead tom miking','Polarity inversion','Resonant head','Close miking']::text[],ARRAY['Skipping polarity inversion, so the underhead mic cancels the top mic and hollows the drum.','Positioning the mic in a vent''s airflow, adding wind rumble and rattle.','UNSAFE: Prolonged close exposure to a loud kit without hearing protection can cause permanent hearing loss.']::text[],ARRAY['Capturing resonant-head detail on snare or toms in a studio session.','Blending top and underhead mics to fine-tune drum body and attack.','Reinforcing drum resonance that overheads alone do not deliver.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d3fc52cb-a682-547f-9c9b-2742d8c3b966' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Underhead microphone'),'[^a-z0-9]','','g'));
