WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d3fc52cb-a682-547f-9c9b-2742d8c3b966' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ebddffb6-0ebc-50ef-b3f3-ea70bcc75785','Underhead tom miking','A tom placement in which a microphone is set beneath the tom, close to its resonant (bottom) head, to capture note sustain, low-frequency body and attack; as with other bottom-head mics it is normally polarity-inverted to remain in phase with any top mic.','This means putting a mic under a tom, near its bottom head. It captures the tom''s ring and depth. The signal is usually flipped so it matches the top mic.','It exists to add sustain and low-end body to toms that a top mic alone cannot fully capture, improving punch and fullness.','An engineer clips a mic under each tom''s resonant head, inverts polarity, and blends it with the top mics for a fuller, more defined tom sound.','Drum miking',ARRAY['Tom-bottom microphone','Under-snare microphone','Underhead microphone','Polarity inversion','Resonant head','Overhead microphone']::text[],ARRAY['Forgetting polarity inversion, causing cancellation with the top tom mic and a thin sound.','Placing the mic too close to the resonant head, choking sustain or catching rattle.','UNSAFE: Long close-range sessions beside a loud kit without hearing protection risk hearing damage.']::text[],ARRAY['Adding depth and sustain to floor toms in a rock production.','Fine-tuning tom body by blending top and underhead mics.','Recording toms that need isolated, punchy processing in a dense mix.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ebddffb6-0ebc-50ef-b3f3-ea70bcc75785' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Underhead tom miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'ebddffb6-0ebc-50ef-b3f3-ea70bcc75785','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='ebddffb6-0ebc-50ef-b3f3-ea70bcc75785' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '61d8986a-5afa-5502-8cb7-bec87bb1cfda','Upper-bout miking','Positioning a microphone over the upper bout of a stringed instrument such as an acoustic guitar or violin—the upper curved lobe of the body nearest the neck and shoulders, narrower than the wider lower bout—rather than at the soundhole or lower bout. This location captures a balanced blend of string articulation and body resonance while avoiding the excess low-frequency boom that concentrates directly over the soundhole.','The bout is the curved shoulder of a guitar or violin body. The upper bout sits near the neck. Aiming a mic there gives a clear, even tone. It skips the boomy sound you get right over the soundhole.','It exists to deliver a natural, well-balanced acoustic tone by moving the microphone away from the bass-heavy soundhole toward a spot that balances pick or bow attack against body warmth.','An engineer aims a small-diaphragm condenser at the upper bout, near where the neck meets the body, then adjusts distance and angle to trade string detail against fullness.','Instrument miking',ARRAY['Soundhole miking','Lower-bout miking','Small-diaphragm condenser','Proximity effect','Spot microphone','3:1 rule']::text[],ARRAY['Aiming at the soundhole instead of the upper bout and then fighting a boomy, bass-heavy recording.','Placing the mic so close that small player movements cause large tone and level changes.','UNSAFE: Patching or unpatching a condenser mic with phantom power still live, which can send a loud thump through monitors and speakers; mute the channel and let phantom power settle before connecting.']::text[],ARRAY['Recording a fingerstyle acoustic guitar and wanting clarity without boom.','Miking a violin in a studio to capture body warmth plus bow detail.','Setting a spot mic on an acoustic guitar in a live acoustic set.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='61d8986a-5afa-5502-8cb7-bec87bb1cfda' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Upper-bout miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '61d8986a-5afa-5502-8cb7-bec87bb1cfda','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='61d8986a-5afa-5502-8cb7-bec87bb1cfda' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '07f6cd66-d4ae-5d17-ad10-11eb8c033f82','Upper-joint miking','Aiming a microphone at the upper joint of a woodwind such as a clarinet—the section holding the upper tone holes and left-hand keys, below the barrel—rather than at the bell. Because much of a woodwind''s sound radiates from open tone holes rather than only the bell, this position captures a more present, balanced tone across registers.','A clarinet is built in sections that join together. The upper joint holds the top finger holes. Sound comes out of the open holes, not just the bell. Aiming a mic at the upper joint gives a fuller, more even tone.','It exists to capture the clarinet''s true voice, since aiming only at the bell over-weights the lowest notes and misses sound leaving the upper tone holes.','An engineer places a condenser near the upper joint, angled across the tone holes, and moves it toward or away from the bell to balance registers.','Instrument miking',ARRAY['Bell miking','Small-diaphragm condenser','Tone hole','Proximity effect','Spot microphone','Off-axis coloration']::text[],ARRAY['Miking only the bell, which over-emphasizes the lowest notes and thins the upper register.','Placing the mic so close that key clatter and breath noise become distracting.','Assuming a clarinet radiates only from the bell, when open tone holes are major sound sources.']::text[],ARRAY['Recording a clarinet solo and wanting even tone from low to high notes.','Miking a clarinet in a wind quintet where bell-only sound is too dark.','Capturing a folk woodwind whose sound leaves mainly from the finger holes.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='07f6cd66-d4ae-5d17-ad10-11eb8c033f82' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Upper-joint miking'),'[^a-z0-9]','','g'));
