SELECT '07f6cd66-d4ae-5d17-ad10-11eb8c033f82','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='07f6cd66-d4ae-5d17-ad10-11eb8c033f82' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ddc0b8c-8f4a-50bc-a8de-20062dab6eb2','Vibraphone motor-noise rejection','Techniques for keeping the mechanical noise of a vibraphone''s rotating-disc (fan) motor out of a close-microphone recording. The motor spins butterfly discs at the tops of the resonator tubes to create the instrument''s tremolo, and its bearings, belt, and vibration can add hum or rumble that microphones near the bars pick up.','A vibraphone has a small motor that spins discs to make its wobbling sound. That motor can hum or rumble. Motor-noise rejection means keeping that machine noise out of the recording. You do it with mic choice, mic position, or by switching the motor off.','It exists so the recorded sound is the ringing metal bars, not the electric motor, keeping quiet passages clean and free of hum or mechanical rumble.','An engineer switches the motor off when tremolo is not needed, positions mics away from the motor housing, uses a high-pass filter, and isolates the instrument from floor vibration.','Percussion miking',ARRAY['Vibraphone resonator miking','High-pass filter','Resonator tube','Tremolo','Mechanical isolation','Spot microphone']::text[],ARRAY['Placing a microphone right next to the motor housing, so its hum and vibration dominate quiet passages.','Leaving the motor running for tracks that do not need tremolo, adding avoidable noise.','Relying only on a noise gate afterward instead of stopping the noise at the source with placement and isolation.']::text[],ARRAY['Recording a soft jazz vibraphone ballad where motor hum would be audible.','Tracking a classical vibraphone part that calls for no tremolo at all.','Isolating a vibraphone on a resonant stage floor that transmits motor vibration.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ddc0b8c-8f4a-50bc-a8de-20062dab6eb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vibraphone motor-noise rejection'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ddc0b8c-8f4a-50bc-a8de-20062dab6eb2','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ddc0b8c-8f4a-50bc-a8de-20062dab6eb2' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '64c8ebed-857f-51b2-9175-d3b6a99ed43e','Vibraphone resonator miking','Placing microphones in relation to a vibraphone''s resonator tubes—the vertical pipes hung beneath the tuned metal bars that reinforce each note''s fundamental—to capture the instrument''s sustained, mellow tone. Miking toward or below the resonators emphasizes body and sustain, while miking closer to the bars emphasizes mallet attack.','Under each vibraphone bar hangs a metal tube called a resonator. It makes the note ring longer and fuller. Miking near these tubes captures a warm, sustained sound. Miking up near the bars catches more of the mallet strike.','It exists to control the balance between warm sustain from the resonators and bright attack from the bars, shaping the vibraphone''s recorded character.','An engineer sets a spaced pair above the bars for attack and clarity, and may add or move mics toward the resonators to bring up body and sustain.','Percussion miking',ARRAY['Resonator tube','Vibraphone motor-noise rejection','Spaced pair','Spot microphone','Small-diaphragm condenser','Mallet attack']::text[],ARRAY['Miking only close to one end of the instrument, which unbalances low and high bars across the keyboard.','Getting so close to the bars that mallet clicks overwhelm the sustained tone.','UNSAFE: Struck metal bars produce sharp, loud transients close up; keep close-monitoring levels moderate, as sustained exposure above about 85 dBA risks hearing damage.']::text[],ARRAY['Recording a vibraphone feature in a jazz ensemble.','Capturing a solo mallet piece that needs long, even sustain.','Balancing attack and body on a vibraphone in a film score session.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='64c8ebed-857f-51b2-9175-d3b6a99ed43e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vibraphone resonator miking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '64c8ebed-857f-51b2-9175-d3b6a99ed43e','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='64c8ebed-857f-51b2-9175-d3b6a99ed43e' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '31fe6b92-a0c3-5a50-bd2d-33444390a6b5','Vocal double alignment','The process of time-aligning a doubled vocal take against the lead so their consonants, phrasing, and pitch inflections line up closely. Editing or nudging the double reduces distracting flams and phase smearing and produces a tight, thicker combined vocal.','A vocal double is a second take of the same line. If it drifts from the first, the words smear and you hear a sloppy double-hit. Alignment means nudging the double so the words hit together. This makes one thicker, tighter vocal.','It exists to make a doubled vocal sound like one bigger voice rather than two loosely timed takes, improving clarity and impact.','An editor lines up the start of each word and hard consonant in the double to the lead, tightening timing while leaving enough natural difference to keep width.','Vocal production',ARRAY['Vocal double','Comping','Time alignment','Phase cancellation','Flam','Tuning']::text[],ARRAY['Aligning so perfectly that the double phases with the lead and the width disappears.','Only lining up the first word and letting later consonants drift out of time.','Fixing loose timing with heavy reverb instead of actually editing the double into place.']::text[],ARRAY['Tightening a doubled chorus vocal in a pop production.','Aligning a stacked harmony so its consonants match the lead.','Cleaning up a rap double so both takes hit each syllable together.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='31fe6b92-a0c3-5a50-bd2d-33444390a6b5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal double alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
