INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd16594ff-afe6-564e-b84b-823ab60f1320','Vocal level riding','Manually adjusting a vocal''s fader or gain over time—by hand or with written automation—so every word sits at a consistent, intelligible level in the mix. It complements compression by correcting broad, musical level changes that a compressor would either miss or over-react to.','Singers get louder and softer as they perform. Level riding means moving the vocal fader so every word can be heard. You raise the quiet words and ease back the loud ones. It works alongside a compressor.','It exists to keep a vocal steady and clear without asking a compressor to do all the work, which would add unwanted pumping or dullness.','An engineer writes fader automation, nudging quiet phrase-endings up and loud belts down so the whole vocal reads evenly against the backing track.','Vocal production',ARRAY['Fader automation','Compression','Gain staging','Clip gain','Vocal reverb ducking','Intelligibility']::text[],ARRAY['Relying on heavy compression alone, which pumps or dulls the vocal instead of gentle riding.','Riding levels so aggressively that the singer''s natural dynamics disappear and the performance sounds flat.','Riding the fader before removing clicks or noises, so those get boosted along with the quiet words.']::text[],ARRAY['Evening out a dynamic lead vocal in a dense pop mix.','Bringing up whispered phrase-endings that a compressor cannot catch cleanly.','Balancing a live-tracked vocal whose distance to the mic kept changing.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d16594ff-afe6-564e-b84b-823ab60f1320' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal level riding'),'[^a-z0-9]','','g'));
