INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'beaaf78c-29a7-538a-90d4-82a12f598543','Vocal off-axis control','Managing the coloration and spill that occur when sound reaches a vocal microphone from angles away from its main (on-axis) direction. Because a directional microphone''s frequency response changes off-axis, controlling the singer''s position and the mic''s aim keeps tone consistent and reduces bleed from other sources and the room.','A directional mic sounds best when the singer is right in front of it. Sound coming from the side hits it ''off-axis'' and can sound dull or colored. Off-axis control means keeping the singer aimed at the mic. It also cuts down bleed from the room and other instruments.','It exists to keep a vocal''s tone even and reject unwanted sound, since a directional mic colors and attenuates whatever arrives from off to the side or rear.','An engineer coaches the singer to stay on-axis, angles the mic to put bleed sources in its least sensitive zone, and picks a polar pattern whose off-axis response stays smooth.','Vocal miking',ARRAY['Polar pattern','Off-axis coloration','Cardioid','Bleed','3:1 rule','Null point']::text[],ARRAY['Letting a singer drift off the mic''s axis, so the tone turns dull and inconsistent take to take.','Ignoring where a cardioid''s rejection null aims, so loud bleed sits in the most sensitive angle.','Assuming every polar pattern rejects sound cleanly; off-axis response is colored, not simply quieter.']::text[],ARRAY['Recording a lead vocal in a room with audible spill from a nearby amp.','Aiming a stage vocal mic so the wedge monitor sits in its rejection null.','Keeping a moving singer''s tone consistent during an energetic take.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='beaaf78c-29a7-538a-90d4-82a12f598543' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal off-axis control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'beaaf78c-29a7-538a-90d4-82a12f598543','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='beaaf78c-29a7-538a-90d4-82a12f598543' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '57bf9f72-1e45-5e1b-8993-0914758ee431','Vocal proximity-effect control','Managing the low-frequency boost that a directional (pressure-gradient) microphone produces as a singer moves closer to it. Techniques include controlling mouth-to-mic distance, applying a high-pass filter, or choosing pattern, so the added bass is used deliberately for warmth or reduced to avoid muddiness. Omnidirectional (pressure) microphones do not exhibit this effect.','Directional mics add extra bass when a singer gets very close. This is the proximity effect. Controlling it means managing how close the singer sings. You can also use a high-pass filter to cut the extra boom. Get it right and you add warmth without mud.','It exists to harness or tame the bass rise of close vocal miking, giving warmth and intimacy when wanted and clarity when the boost becomes boomy.','An engineer sets a working distance, coaches consistent mic technique, and dials a high-pass filter so a close vocal stays warm without turning muddy on loud, close phrases.','Vocal miking',ARRAY['Proximity effect','High-pass filter','Cardioid','Omnidirectional','Pop filter','Working distance']::text[],ARRAY['Letting the singer crowd the mic so the low end balloons and the vocal turns boomy.','Assuming an omnidirectional mic boosts bass up close; the proximity effect applies to directional mics.','Cutting so much low end to fight the boost that the vocal becomes thin and lifeless.']::text[],ARRAY['Recording an intimate close vocal that needs warmth without boom.','Taming bass buildup when a singer leans in on loud choruses.','Coaching a live singer whose changing mic distance keeps shifting the low end.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='57bf9f72-1e45-5e1b-8993-0914758ee431' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal proximity-effect control'),'[^a-z0-9]','','g'));
