SELECT '57bf9f72-1e45-5e1b-8993-0914758ee431','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='57bf9f72-1e45-5e1b-8993-0914758ee431' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6e80cd4c-1f4b-5438-babb-b5a36bdebc42','Vocal reverb ducking','Using a sidechain from the dry vocal to automatically lower the level of the vocal''s reverb return while the singer is active, letting the reverb rise back up in the gaps between phrases. This keeps words intelligible during singing yet preserves a rich reverb tail where there is space for it.','Reverb can blur a vocal and hide the words. Ducking turns the reverb down while the singer sings. It lets the reverb swell back up in the pauses. So you get clear words and a big sound where there is room for it.','It exists to combine intelligibility with size, so a vocal can sit in a large reverb without the wash smearing the lyrics.','An engineer keys a compressor on the reverb return from the dry vocal, so the return dips while the vocal plays and blooms in the pauses at line ends.','Vocal effects',ARRAY['Sidechain (key input)','Ducking','Reverb return','Vocal throw delay','Intelligibility','Send effect']::text[],ARRAY['Setting the ducking release so fast that the reverb pumps loudly between every word.','Keying the ducking from the wet reverb instead of the dry vocal, so it never opens fully.','Ducking so deeply that the reverb disappears and the intended sense of space is lost.']::text[],ARRAY['Keeping a lyric clear over a large hall reverb in a ballad.','Letting a vocal delay-and-reverb wash bloom only in the gaps at line ends.','Adding size to a rap vocal without smearing fast, wordy passages.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6e80cd4c-1f4b-5438-babb-b5a36bdebc42' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal reverb ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6e80cd4c-1f4b-5438-babb-b5a36bdebc42','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6e80cd4c-1f4b-5438-babb-b5a36bdebc42' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c384592b-9cae-5347-96d1-c410fdbd6873','Vocal throw delay','A momentary echo effect, often called a delay throw, in which a single word or phrase—usually at the end of a line—is sent to a delay so it repeats and tails off, while the rest of the vocal stays dry. It is created by automating a delay send up for just that word so the throw stands out against the surrounding phrase.','A delay throw sends just one word into an echo. That word repeats and fades while the rest of the line stays dry. Singers and engineers use it on the last word of a phrase. It adds a catchy moment without washing out the whole vocal.','It exists to add rhythmic interest and emphasis to chosen words without drowning the whole vocal in constant echo.','An engineer automates a delay send up for one word, often a phrase ending, so that word tails into the gap and then the send closes again.','Vocal effects',ARRAY['Delay send','Send effect','Automation','Vocal reverb ducking','Feedback (delay)','Tempo sync']::text[],ARRAY['Leaving the delay send open all the time, so every word smears instead of just the chosen one.','Throwing a word into an untimed delay that fights the song''s tempo.','Setting delay feedback so high that the repeats pile up and clutter the next line.']::text[],ARRAY['Throwing the last word of a chorus line into a tempo-synced echo.','Adding a dub-style delay throw on a single word in a reggae mix.','Emphasizing a hook word in a pop vocal with a short repeating tail.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c384592b-9cae-5347-96d1-c410fdbd6873' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Vocal throw delay'),'[^a-z0-9]','','g'));
