SELECT 'c384592b-9cae-5347-96d1-c410fdbd6873','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c384592b-9cae-5347-96d1-c410fdbd6873' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5f7c89c3-de33-51bd-bb23-20bb8759499e','Wallet damping','A quick studio trick of laying a wallet—or a similar small, soft weight—on the batter head of a snare drum near the edge to shorten ring and reduce overtones. It damps the head lightly, tightening the sound without the heavier deadening of tape or gel pads.','Drums can ring longer than you want. Placing a wallet near the edge of the snare head calms that ring. It is a fast, cheap fix used in studios. It tightens the drum without fully deadening it.','It exists to control unwanted ring and overtones at the source, giving a tighter, more focused drum sound before any processing.','A drummer or engineer sets a wallet near the rim of the snare, sliding it in or out until the ring is tamed but the drum still speaks.','Drum damping',ARRAY['Moongel','Damping ring','Overtones','Snare drum','Close miking','Gaffer tape']::text[],ARRAY['Piling on too much weight, which chokes the drum and kills its tone and sustain.','Placing the wallet in the center of the head instead of near the edge, deadening the drum too much.','UNSAFE: Reaching across a loud, close-miked kit to adjust damping without hearing protection; sustained levels above about 85 dBA risk hearing damage, so wear earplugs.']::text[],ARRAY['Taming a ringing snare quickly during a tracking session.','Dialing back overtones on a rented kit before miking.','Getting a dry, controlled snare for a pop or hip-hop record.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5f7c89c3-de33-51bd-bb23-20bb8759499e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Wallet damping'),'[^a-z0-9]','','g'));
