WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5f7c89c3-de33-51bd-bb23-20bb8759499e' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '97cd910f-314c-504a-a109-08062d196360','Xylophone octave spread control','Controlling how a xylophone''s range of octaves—laid out physically from the long low bars on the player''s left to the short high bars on the right—maps across the stereo image when recorded with a stereo pair or spot microphones. Adjusting microphone spacing, angle, and panning sets how wide or narrow the low-to-high spread sounds in the final stereo picture.','A xylophone''s bars run from low notes on the left to high notes on the right. Recorded in stereo, that layout spreads across the speakers. Spread control means setting how wide that low-to-high image sounds. You do it with mic spacing, angle, and panning.','It exists to make the recorded stereo width of the instrument''s range match the mix, avoiding either an unnaturally wide keyboard or a collapsed, mono-sounding image.','An engineer sets the spacing and angle of a stereo pair over the bars, then adjusts panning so the octave-to-octave spread reads natural rather than exaggerated across the speakers.','Percussion miking',ARRAY['Stereo pair','Spaced pair','XY technique','Panning','Spot microphone','Stereo image']::text[],ARRAY['Spacing the mics so wide that the keyboard sounds unnaturally huge across the stereo field.','Miking mainly one end, so low and high octaves sit at very different levels.','Confusing physical stereo spread of the bars with musical octave range; wider mic spacing does not change the notes played.']::text[],ARRAY['Recording an orchestral xylophone so its range sits believably in the stereo image.','Narrowing an over-wide xylophone image to fit a dense mix.','Balancing low and high bars evenly on a solo mallet piece.']::text[],'c1bd3df7-1ba9-416e-8ebd-538a91ac2517'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='97cd910f-314c-504a-a109-08062d196360' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Xylophone octave spread control'),'[^a-z0-9]','','g'));
