SELECT '97cd910f-314c-504a-a109-08062d196360','c1bd3df7-1ba9-416e-8ebd-538a91ac2517',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='97cd910f-314c-504a-a109-08062d196360' AND gt.achievement_id='c1bd3df7-1ba9-416e-8ebd-538a91ac2517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f7f43af6-da41-5695-b72c-6b1b20c02179','Alternating reverse delay','A reverse-delay effect in which the buffered signal is played back backwards, with the reversed repeats alternating in direction or position—typically bouncing the reversed segments between the left and right channels, or alternating reversed repeats with forward ones. The result is a rhythmic, swelling backwards echo that moves across the stereo field.','A normal delay repeats a sound just as you played it. A reverse delay plays each repeat backwards, so it swells up. ''Alternating'' means the backwards repeats swap sides or take turns. This makes an echo that grows and bounces across the stereo picture.','It exists to turn plain echoes into an evolving, backwards-swelling texture that adds motion and an otherworldly feel, working as an ear-catching effect rather than a simple repeat.','An engineer sends a word, guitar note, or synth stab to the effect so its reversed repeats swell and cross between the speakers, often timed to the song''s tempo.','Delay effect',ARRAY['Reverse reverb','Ping-pong delay','Cross-feedback delay','Tempo sync','Feedback (delay)','Pre-delay']::text[],ARRAY['Assuming the reversed repeat lines up with the original note; the backwards swell peaks before the beat, so timing must be set by ear.','Leaving feedback high so the alternating reversed repeats pile up into an unclear wash.','UNSAFE: Pushing delay feedback toward or past 100% can make the effect self-oscillate and jump to a very loud level; keep feedback below runaway and lower monitor level first, since sustained sound above about 85 dBA risks hearing damage.']::text[],ARRAY['Creating a dreamy, backwards swell before a vocal phrase in a pop production.','Adding motion to a synth stab so its echoes sweep across the stereo field.','Building a riser into a chorus using reversed, bouncing repeats.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f7f43af6-da41-5695-b72c-6b1b20c02179' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Alternating reverse delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f7f43af6-da41-5695-b72c-6b1b20c02179','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f7f43af6-da41-5695-b72c-6b1b20c02179' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1d0d1278-ffd7-5027-9e92-87d32bdbdeac','Ambience algorithm','A reverberation algorithm tuned to emphasize early reflections and a short, sparse decay so it recreates the subtle sound of a small-to-medium real room rather than a long, obvious reverb tail. It adds a sense of space and liveness while keeping the source close and present.','Every room adds tiny early echoes that tell your ears its size. An ambience algorithm copies those early echoes with only a short tail. It makes a dry recording sound like a real room. But it does not add a long, washy reverb.','It exists to place a dry, close-miked source into a believable small space, adding depth and glue without the wash or length of a hall or plate reverb.','An engineer uses an ambience or ''room'' program on drums, vocals, or a whole mix to add realistic space, keeping decay short so the source stays tight.','Reverb algorithm',ARRAY['Early reflections','Room reverb','Pre-delay','Reverb tail','RT60','Diffusion']::text[],ARRAY['Turning the decay time up until an ambience program sounds like a hall, losing the tight, close feel that defines it.','Adding so much ambience that the mix becomes distant and washy instead of just believable.','Confusing early reflections with the long tail; ambience lives mostly in the first reflections, not a long decay.']::text[],ARRAY['Adding a natural room feel to close-miked drums recorded in a dead studio.','Gluing a dry vocal into the track without an obvious reverb tail.','Placing a virtual instrument into a small, realistic space in a mix.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1d0d1278-ffd7-5027-9e92-87d32bdbdeac' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ambience algorithm'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1d0d1278-ffd7-5027-9e92-87d32bdbdeac','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1d0d1278-ffd7-5027-9e92-87d32bdbdeac' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4d510d2e-2c01-5e8d-92fe-b3420f8be4f7','Bloom reverb','A reverb character in which the tail''s density and loudness build up gradually after the initial onset—swelling, or ''blooming,'' toward a peak before decaying—rather than reaching full density immediately. This slow buildup mirrors how echo density in a real space increases over time and is often shaped with pre-delay and diffusion controls.','In a real hall, echoes get thicker and louder for a moment before fading. A bloom reverb copies this slow swell. The tail grows after the note, then fades away. It gives a lush, breathing sense of space.','It exists to create a lush, swelling sense of space that feels natural and emotional, giving reverb a sense of movement instead of appearing instantly at full strength.','An engineer chooses a bloom or long-hall program and sets pre-delay and diffusion so the tail swells behind sustained vocals, pads, or guitars in ballads and cinematic mixes.','Reverb effect',ARRAY['Density buildup','Diffusion','Pre-delay','Reverb tail','RT60','Hall reverb']::text[],ARRAY['Expecting the reverb to be dense instantly; the bloom is the gradual swell, so short sounds may not trigger it well.','Setting decay so long that swelling tails overlap and muddy a busy arrangement.','Using heavy bloom on fast, percussive parts where the slow swell smears the rhythm.']::text[],ARRAY['Adding a swelling tail behind a sustained ballad vocal.','Creating a cinematic wash under pads and strings in a film cue.','Giving a slow guitar part an emotional, breathing sense of space.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4d510d2e-2c01-5e8d-92fe-b3420f8be4f7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bloom reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4d510d2e-2c01-5e8d-92fe-b3420f8be4f7','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4d510d2e-2c01-5e8d-92fe-b3420f8be4f7' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '039b01c8-0d22-5418-9e33-c690b6cb26e4','Chorused reverb','A reverb whose delay lines or wet output are modulated with a slow, chorus-style pitch and time variation, adding gentle movement and shimmer to the tail. The modulation also breaks up the fixed resonances of the delay network, reducing metallic ringing and ''picket-fence'' coloration.','A plain reverb tail can sit still and sound a bit metallic. Chorusing gently wobbles the tail''s pitch, like a slow warble. This adds shimmer and movement. It also smooths out harsh ringing tones.','It exists to make a reverb tail richer, wider, and less static, while the modulation smooths the resonant coloration that fixed delay lines can produce.','An engineer picks a modulated or ''chorus'' reverb, or adds a chorus on the reverb return, to thicken pads, vocals, and guitars and to soften any metallic ring in the tail.','Reverb effect',ARRAY['Detuned reverb','Modulation','Chorus','Comb filter','Diffusion','Reverb tail']::text[],ARRAY['Adding so much modulation depth that sustained notes and pitched instruments sound out of tune.','Assuming modulation only adds shimmer; it also reduces metallic ringing, so removing it can bring the ring back.','Using heavy chorused reverb on lead vocals where obvious pitch wobble is distracting.']::text[],ARRAY['Thickening a synth pad with a lush, moving reverb tail.','Smoothing a metallic-sounding plate reverb on vocals.','Adding shimmer and width to a clean electric guitar.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='039b01c8-0d22-5418-9e33-c690b6cb26e4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Chorused reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '039b01c8-0d22-5418-9e33-c690b6cb26e4','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='039b01c8-0d22-5418-9e33-c690b6cb26e4' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2db26ef8-daec-5112-bff1-e36a11d7858b','Cross-feedback delay','A stereo delay in which each channel''s delayed output is fed back into the opposite channel''s input rather than its own, so repeats alternate—or ''ping-pong''—between the left and right channels. The amount of cross-coupled feedback sets how many times the echoes bounce before decaying.','A stereo delay has a left and a right side. In cross-feedback delay, the left echo feeds the right side, and the right feeds the left. So each repeat jumps from one speaker to the other. This is the classic bouncing ''ping-pong'' echo.','It exists to create a wide, bouncing stereo echo that moves between the speakers, adding space and rhythmic interest without cluttering the center of the mix.','An engineer sets the two delay times and the cross-feedback amount so repeats ping-pong across the stereo field in time with the song, often on vocals, guitars, or synths.','Delay effect',ARRAY['Ping-pong delay','Feedback (delay)','Tempo sync','Stereo width','Slapback','Alternating reverse delay']::text[],ARRAY['Setting the cross-feedback too high so the bouncing repeats never die away and clutter the mix.','Leaving the two channel delay times unmatched so the ping-pong rhythm feels lopsided when that was not intended.','UNSAFE: Feedback at or above 100% makes a delay self-oscillate and can rise suddenly to a very loud, runaway level; keep feedback below that point and lower monitors first, since sustained exposure above about 85 dBA risks hearing damage.']::text[],ARRAY['Adding a wide bouncing echo to a lead vocal in a pop chorus.','Creating a rhythmic ping-pong on a synth or guitar hook.','Widening a mono source by bouncing its repeats across the stereo field.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2db26ef8-daec-5112-bff1-e36a11d7858b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Cross-feedback delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2db26ef8-daec-5112-bff1-e36a11d7858b','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2db26ef8-daec-5112-bff1-e36a11d7858b' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4aeb0e57-aae4-59fb-9031-a8a293e03212','Crossfeed reverb','A reverb configuration in which some signal is fed across between the left and right sides of the reverberator—each channel''s reverb path receiving a portion of the other''s—so the two sides are coupled rather than fully independent. This blends the stereo tail into a more cohesive, enveloping space and controls how wide or mono-compatible the reverb sounds.','A stereo reverb has a left and a right tail. Crossfeed mixes a little of each side into the other. This ties the two sides together. It makes the space feel like one connected room instead of two separate ones.','It exists to control the width and cohesion of a stereo reverb tail, trading fully separate left and right decays for a more unified, enveloping and mono-compatible space.','An engineer adjusts a reverb''s crossfeed or width control to make the tail feel like one connected room and to keep it from collapsing oddly when the mix is checked in mono.','Reverb effect',ARRAY['Decorrelated reverb','Stereo width','Mono compatibility','Reverb tail','Diffusion','Decorrelation']::text[],ARRAY['Confusing reverb crossfeed with headphone crossfeed; here it couples the two reverb channels, not the monitoring feed.','Adding so much crossfeed that the stereo width collapses toward mono and the sense of space narrows.','Forgetting to check the reverb in mono, where too little coupling can cause the tail to thin or shift.','Confusing crossfeed reverb with cross-feedback delay: crossfeed reverb couples the two reverb channels'' tails, while cross-feedback delay feeds each delay channel into the opposite one to create ping-pong repeats.']::text[],ARRAY['Tightening a wide stereo reverb so it holds together on a mono club system.','Blending the two sides of a hall reverb into one enveloping space.','Controlling how wide a plate reverb sits behind a lead vocal.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4aeb0e57-aae4-59fb-9031-a8a293e03212' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Crossfeed reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4aeb0e57-aae4-59fb-9031-a8a293e03212','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4aeb0e57-aae4-59fb-9031-a8a293e03212' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0853356d-2d32-5026-9190-dd307f4b88e0','Decorrelated reverb','A reverb whose left and right outputs are made largely uncorrelated—differing in their fine time and phase detail—so the tail spreads widely and envelops the listener. Low interaural correlation between the two channels is the main cue that makes a reverb sound spacious rather than narrow or point-like.','If the left and right reverb tails are identical, the sound seems to come from one spot. Decorrelation makes the two sides differ in tiny ways. Your ears then hear a wide, wrap-around space. This is what makes a reverb feel big and surrounding.','It exists to widen and envelop the reverb image, because low correlation between the left and right tails is the main cue that tells the ear a space is large and surrounding.','An engineer relies on a reverb''s decorrelated outputs, or a width/decorrelation control, to spread the tail wide behind a mono source, then checks that it still sums cleanly in mono.','Reverb effect',ARRAY['Decorrelation','Delay decorrelation','Stereo width','Crossfeed reverb','Diffusion','Mono compatibility']::text[],ARRAY['Assuming a hard-panned dry copy equals decorrelation; identical copies stay correlated and can cancel in mono.','Pushing decorrelation so far that the tail loses focus or causes phase issues when summed to mono.','Confusing wide stereo tails with more reverb; width comes from decorrelation, not just level.']::text[],ARRAY['Making a mono vocal sit in a wide, enveloping space.','Widening a reverb tail on a sparse arrangement for a sense of scale.','Checking that a wide reverb still holds up when a broadcast folds it to mono.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0853356d-2d32-5026-9190-dd307f4b88e0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decorrelated reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0853356d-2d32-5026-9190-dd307f4b88e0','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0853356d-2d32-5026-9190-dd307f4b88e0' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e0a26fbd-de29-5fdb-9e9a-345960783c9e','Delay capture','Capturing the current contents of a delay line so they can be held and repeated indefinitely or reused—as with a hold/freeze function that loops the buffer, or by printing (recording) the delayed output to an audio track. It turns a passing echo into fixed, reusable material.','A delay stores a short piece of sound in a buffer. Delay capture grabs what is in that buffer and holds it. The captured sound can loop forever or be recorded to a track. It turns a passing echo into something you can keep.','It exists to freeze or save a delay''s contents, so a fleeting repeat can be held as a sustained loop, layered, or committed to a track for further use.','An engineer hits a hold/freeze control to loop the current delay buffer under a solo, or records (prints) the wet delay to a new track to lock in the effect.','Delay effect',ARRAY['Feedback (delay)','Reverb freeze','Delay-into-reverb','Loop','Wet/dry mix','Print (bounce)']::text[],ARRAY['Capturing the buffer at the wrong moment, so the held loop contains an unwanted noise, breath, or half a word.','Forgetting that a frozen delay usually stops taking new input, so playing over it does not update the loop.','UNSAFE: A held or frozen delay can sit at a high sustained level and, with feedback, build up loudly; set monitor level before engaging it, since sustained sound above about 85 dBA risks hearing damage.']::text[],ARRAY['Freezing a delay tail into a drone under a guitar solo.','Printing a rhythmic delay to audio so the effect is locked before mixing.','Holding a captured vocal echo to build a bed for a transition.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e0a26fbd-de29-5fdb-9e9a-345960783c9e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Delay capture'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e0a26fbd-de29-5fdb-9e9a-345960783c9e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e0a26fbd-de29-5fdb-9e9a-345960783c9e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'aa210b49-6738-5915-87d0-66a9a66a4b6f','Delay decorrelation','Using small, differing delays on duplicated or stereo signals so the copies become less correlated with one another, widening the stereo image or thickening a source. Very short offsets between channels reduce correlation, but offsets that are too long are heard as distinct echoes instead of width.','Two identical signals sound like one narrow source. Adding a tiny, slightly different delay to each side makes them differ. Your ears then hear a wider, fuller sound. But if the delay is too long, you hear a separate echo instead.','It exists to widen or thicken a sound by making its channels differ slightly in time, a simple way to build stereo width or size from a mono source.','An engineer adds a few milliseconds of delay to one side of a doubled part, or uses a decorrelation tool, to widen guitars, backing vocals, or synths, then checks mono for cancellation.','Delay technique',ARRAY['Decorrelation','Decorrelated reverb','Haas effect','Stereo width','Comb filter','Mono compatibility']::text[],ARRAY['Setting the offset so long that the intended width becomes an audible slapback echo.','Ignoring mono compatibility; short offsets between channels can comb-filter and partly cancel when summed to mono.','Assuming more delay always means more width; beyond a few milliseconds it turns into a separate echo.']::text[],ARRAY['Widening a doubled rhythm guitar with a few milliseconds of offset on one side.','Thickening a mono synth into a fuller stereo part.','Spreading backing vocals across the stereo field without re-recording them.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='aa210b49-6738-5915-87d0-66a9a66a4b6f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Delay decorrelation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'aa210b49-6738-5915-87d0-66a9a66a4b6f','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='aa210b49-6738-5915-87d0-66a9a66a4b6f' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fc3ca475-cd1e-5817-abbe-58f7848bef59','Delay spill','The delayed repeats or tail of a delay effect carrying over past the source that created them—continuing into a pause, the next phrase, or a section change—whether as an intended wash or as unwanted clutter. Spill is managed by muting the delay send, reducing feedback, or automating the return.','A delay keeps repeating a sound after you play it. Those repeats can carry on into the next part of the song. That leftover echo is called spill. It can sound nice, or it can clutter the mix if you do not control it.','Understanding spill matters because a delay''s leftover repeats fill the gaps between phrases; used well they add space, but left unchecked they blur the next section.','An engineer controls spill by muting or automating the delay send between phrases, trimming feedback, or ducking the delay return so repeats do not run into the next line.','Delay effect',ARRAY['Feedback (delay)','Delay send','Reverb tail','Ducking','Automation','Delay-into-reverb']::text[],ARRAY['Leaving high feedback so repeats spill across section changes and blur the arrangement.','Forgetting to mute or automate the delay send in gaps, so echoes clutter quiet passages.','Fixing spill by cutting the whole delay instead of automating it only where it causes trouble.']::text[],ARRAY['Stopping delay repeats from bleeding into a quiet breakdown.','Letting a delay tail spill into a pause on purpose for effect.','Cleaning up echoes that run over the start of the next vocal line.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fc3ca475-cd1e-5817-abbe-58f7848bef59' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Delay spill'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fc3ca475-cd1e-5817-abbe-58f7848bef59','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fc3ca475-cd1e-5817-abbe-58f7848bef59' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1d0f35a6-028f-5a74-8bb6-2b57ed9ae87b','Delay-into-reverb','A serial routing in which a delay is placed before a reverb, so each delay repeat is then reverberated. The repeats seed the reverb at rhythmic intervals, producing a spacious, rhythmic wash that is denser and more diffuse than either effect alone.','Here a delay comes first, then a reverb after it. Each echo from the delay is then blurred by the reverb. This makes a rich, rhythmic wash of sound. It feels bigger and smoother than using either effect by itself.','It exists to combine rhythm and space, letting timed delay repeats feed a reverb so the tail pulses in time while still sounding large and diffuse.','An engineer routes a delay into a reverb, in series or send-to-send, so a vocal or guitar throws timed repeats that bloom into a spacious tail, often tempo-synced.','Signal routing',ARRAY['Delay send','Reverb tail','Pre-delay','Diffused delay','Tempo sync','Send effect']::text[],ARRAY['Piling long reverb onto heavy delay feedback so the combined wash smears the whole mix.','Reversing the order without meaning to; reverb into delay repeats the whole reverberated sound and behaves differently.','Not tempo-syncing the delay, so its repeats fight the groove before hitting the reverb.']::text[],ARRAY['Creating a big, rhythmic wash behind a sparse vocal in a ballad.','Making a single guitar note bloom into a timed, spacious tail.','Building an ambient pad texture from a simple synth stab.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1d0f35a6-028f-5a74-8bb6-2b57ed9ae87b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Delay-into-reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1d0f35a6-028f-5a74-8bb6-2b57ed9ae87b','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1d0f35a6-028f-5a74-8bb6-2b57ed9ae87b' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '24e855a6-ad7a-5423-bd45-01885d12319d','Density buildup','The increase in echo density within a reverb over time, as sparse early reflections give way to ever-more-closely-spaced echoes that merge into a smooth late tail. In real rooms this density grows roughly as the square of time, and reverb algorithms recreate it with recirculating comb and all-pass (diffusion) stages.','Right after a sound, a room gives a few separate echoes. As time passes, the echoes pile up closer and closer together. Soon they blur into one smooth wash. This growing thickness is called density buildup.','It matters because smooth, high echo density is what makes a reverb tail sound natural; too little density sounds grainy or fluttery, while a good buildup sounds like a real space.','An engineer uses a reverb''s diffusion and density controls to set how fast the tail thickens, raising diffusion to smooth grainy or fluttery tails on transient sources like drums.','Reverb behavior',ARRAY['Diffusion','Early reflections','Reverb tail','Bloom reverb','All-pass filter','Comb filter']::text[],ARRAY['Setting diffusion or density too low, leaving a grainy or fluttery tail on percussive sounds.','Assuming density and decay time are the same; density is how thick the tail is, decay is how long it lasts.','Cranking density on every source, which can dull the natural early reflections that give a sound its space.']::text[],ARRAY['Smoothing a grainy reverb tail on a snare with more diffusion.','Setting how quickly a hall''s tail thickens behind a vocal.','Choosing a low-density setting for a vintage, grainy reverb character.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='24e855a6-ad7a-5423-bd45-01885d12319d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Density buildup'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '24e855a6-ad7a-5423-bd45-01885d12319d','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='24e855a6-ad7a-5423-bd45-01885d12319d' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9abf331b-9aab-5337-97d9-54192cd30c58','Detuned reverb','A reverb whose tail is slightly pitch-shifted or modulated—often with the two channels detuned in opposite directions—to add lushness, width, and movement. The small, continuous pitch variation also smooths the fixed resonances of the delay network, reducing metallic coloration.','A detuned reverb shifts the tail''s pitch by a tiny amount. Often one side goes slightly up and the other slightly down. This adds a lush, wide, shimmering feel. It also smooths out harsh, metallic ringing in the tail.','It exists to make a reverb tail lusher and wider and to reduce metallic ringing, using small pitch offsets to blur the fixed resonances of the reverb.','An engineer picks a detuned or modulated reverb, or adds subtle pitch modulation to the return, to give pads, vocals, and guitars a wide, shimmering, less metallic tail.','Reverb effect',ARRAY['Chorused reverb','Modulation','Pitch shift','Comb filter','Reverb tail','Stereo width']::text[],ARRAY['Using too much detune so sustained, pitched material sounds noticeably out of tune.','Confusing detuned reverb with chorus on the source; here the pitch shift smooths the tail, not the dry signal.','Applying heavy detune on exposed solo instruments where the pitch drift becomes obvious.']::text[],ARRAY['Adding a wide, shimmering tail to a synth pad.','Smoothing a metallic plate reverb behind a vocal.','Giving a clean guitar a lush, moving sense of space.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9abf331b-9aab-5337-97d9-54192cd30c58' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Detuned reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9abf331b-9aab-5337-97d9-54192cd30c58','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9abf331b-9aab-5337-97d9-54192cd30c58' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1605d247-3b97-5f17-a7cc-8d38494fe1c5','Diffused delay','A delay whose repeats are passed through diffusion (typically all-pass stages) so each echo is smeared and softened rather than reproduced as a sharp, distinct repeat. The result sits between a clean delay and a reverb, giving blurred, cloud-like echoes.','A normal delay gives sharp, clear repeats. A diffused delay smears each repeat so it is soft and blurry. The echoes sound more like little clouds than sharp copies. It sits somewhere between a delay and a reverb.','It exists to soften a delay''s repeats so they blend into the mix, giving the space of a delay without hard, distinct echoes competing with the source.','An engineer raises a delay''s diffusion, or feeds it through an all-pass or reverb stage, so repeats blur into a smooth tail behind vocals, guitars, or synths.','Delay effect',ARRAY['Diffusion','All-pass filter','Delay-into-reverb','Reverb tail','Feedback (delay)','Density buildup']::text[],ARRAY['Expecting sharp, countable repeats; diffusion deliberately smears them, so rhythmic echoes become less distinct.','Adding heavy diffusion and high feedback until the delay turns into an uncontrolled wash.','Confusing a diffused delay with reverb; it is still a delay, just with softened repeats.']::text[],ARRAY['Blurring a delay''s repeats so they sit smoothly behind a lead vocal.','Creating a dreamy, cloud-like echo on a synth line.','Blending guitar repeats into the mix without sharp, distracting echoes.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1605d247-3b97-5f17-a7cc-8d38494fe1c5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Diffused delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1605d247-3b97-5f17-a7cc-8d38494fe1c5','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1605d247-3b97-5f17-a7cc-8d38494fe1c5' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6df52cd9-5b19-5f25-96a8-92ab325e808c','Downward shimmer','A shimmer-reverb variation in which the pitch-shifted signal fed through the reverb is transposed downward—typically an octave or a fifth below—rather than the more common upward octave, so the sustaining tail adds a darker, lower harmonic layer beneath the source. It is produced by placing a pitch shifter in the reverb''s feedback or parallel path set to a negative interval.','Shimmer reverb feeds a pitch-shifted copy of the sound back into the reverb tail. Normal shimmer shifts that copy up an octave for a bright sheen. Downward shimmer shifts it down instead. This adds a deep, dark layer under the original sound.','It exists to give a reverb tail extra weight and darkness, adding a sub-harmonic, brooding pad-like layer instead of the airy sheen of upward shimmer.','An engineer sets a pitch shifter in the reverb feedback or a parallel voice to minus one octave (or a fifth down), then blends it under a guitar, synth, or vocal to build a dark ambient bed.','Reverb effect',ARRAY['Shimmer reverb','Pitch shifting','Reverb tail','Feedback (delay)','Octave','Ambient reverb']::text[],ARRAY['Setting the downward-shifted feedback too high, so the low layer builds up and masks the dry source.','Confusing downward shimmer with a low-shelf boost; shimmer adds a new pitched voice, not just tone.','Letting the sub-octave pile up until it muddies the low end of the whole mix.']::text[],ARRAY['Building a dark ambient pad under a clean guitar part.','Adding brooding weight beneath a synth line in a film cue.','Creating a lower, darker tail on a vocal for a moody section.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6df52cd9-5b19-5f25-96a8-92ab325e808c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Downward shimmer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6df52cd9-5b19-5f25-96a8-92ab325e808c','415df21a-f4ef-4337-84b3-c847231c6d62',true
