INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '67f3e6bc-6db3-581b-ba88-a285aa53049d','Dual delay','A delay configuration that runs two independent delay lines at once, each with its own time, feedback, level, and often panning, so a single source can produce two distinct repeating patterns. The two lines may be set to different rhythmic values or panned apart to create rhythmic interplay or a wide stereo echo.','A dual delay is two delays running at the same time. Each one has its own timing and settings. You can set them to different note lengths or pan them apart. This gives a wider, more rhythmic echo than a single delay.','It exists to create rhythmic and stereo complexity from one source, letting two different delay times weave together instead of a single repeating echo.','An engineer sets one line to a dotted-eighth and the other to a quarter note, pans them left and right, and blends them so a guitar or vocal spreads into a rhythmic stereo pattern.','Delay type',ARRAY['Ping-pong delay','Tempo sync','Feedback (delay)','Stereo delay','Dotted-eighth delay','Delay send']::text[],ARRAY['Setting both lines to the same time, which just doubles level instead of creating two patterns.','Piling too much feedback on both lines so the repeats collide into a wash.','Forgetting to tempo-sync the two times, so the pattern fights the song''s groove.']::text[],ARRAY['Spreading a lead guitar into a wide rhythmic stereo echo.','Layering a quarter-note and a dotted-eighth delay on a synth hook.','Creating call-and-response echoes across the stereo field on a vocal.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='67f3e6bc-6db3-581b-ba88-a285aa53049d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dual delay'),'[^a-z0-9]','','g'));
