SELECT '67f3e6bc-6db3-581b-ba88-a285aa53049d','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='67f3e6bc-6db3-581b-ba88-a285aa53049d' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '54c8acc3-f9e7-5654-9bfd-e0a0d90cc8d2','Dual-mono reverb','Running reverb as two separate mono processors—one per channel—so left and right are reverberated independently, rather than through a single true-stereo algorithm that shares reflections and cross-feed between channels. Each side produces its own decorrelated tail, which can widen the image but does not preserve the stereo positioning of a true-stereo reverb.','A dual-mono reverb uses two separate mono reverbs, one for the left side and one for the right. Each side makes its own tail. This can sound wide. But it does not keep the left-to-right placement the way a true stereo reverb does.','It exists to add independent reverb to each channel for width or to treat two mono sources separately, though it lacks the linked cross-channel reflections of a true-stereo reverb.','An engineer may put two mono reverbs on a stereo bus, or feed a source into a reverb whose two sides are decorrelated, to widen a tail—while knowing precise stereo imaging will not be preserved.','Reverb type',ARRAY['True stereo reverb','Reverb return','Decorrelation','Stereo image','Mono compatibility','Send effect']::text[],ARRAY['Assuming dual-mono reverb preserves stereo position like true-stereo reverb; it treats each side on its own.','Feeding a mono source into two identical mono reverbs, which stays centered instead of widening.','Ignoring mono compatibility, so a decorrelated dual-mono tail partly cancels when summed to mono.']::text[],ARRAY['Adding independent reverb to a hard-panned double-tracked guitar.','Widening a mono synth pad by decorrelating its left and right tails.','Reverberating two separate mono sources with one plugin instance per side.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='54c8acc3-f9e7-5654-9bfd-e0a0d90cc8d2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Dual-mono reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '54c8acc3-f9e7-5654-9bfd-e0a0d90cc8d2','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='54c8acc3-f9e7-5654-9bfd-e0a0d90cc8d2' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '82500fb9-cfd6-5453-88fd-bfb9558ac4a7','Ducked delay','A delay effect whose repeats are automatically attenuated while the dry source is present, using a sidechain (key) from the input so the echoes duck down during phrases and swell back up in the gaps. This keeps the source clear and intelligible while still allowing audible tails between notes or words.','A ducked delay turns its echoes down while the singer or player is sounding. When they pause, the echoes rise back up. This keeps the words or notes clear. You still hear the delay tails in the gaps.','It exists to combine a strong delay with intelligibility, so the effect fills space between phrases without smearing the dry source itself.','An engineer sidechains the delay return to a compressor keyed from the dry vocal, so repeats dip while the singer sings and bloom in the pauses at line ends.','Delay technique',ARRAY['Ducking','Sidechain (key input)','Delay send','Vocal reverb ducking','Feedback (delay)','Reverb return']::text[],ARRAY['Setting the release too fast, so the delay pumps back up loudly between every word.','Keying the ducking from the wet delay instead of the dry source, so it never opens cleanly.','Ducking so deeply that the delay disappears and the sense of space is lost.']::text[],ARRAY['Keeping a lyric clear over a heavy quarter-note delay in a dense mix.','Letting a dub delay bloom only in the gaps between vocal phrases.','Adding space to a busy rap vocal without smearing fast passages.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='82500fb9-cfd6-5453-88fd-bfb9558ac4a7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Ducked delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '82500fb9-cfd6-5453-88fd-bfb9558ac4a7','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='82500fb9-cfd6-5453-88fd-bfb9558ac4a7' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a97177ef-7ec6-5df7-91fb-7e3eab6360f8','Duplet delay','A delay whose time is set to a duplet—two equal notes played in the span normally occupied by three (a triplet)—so the repeats fall as an even two-against-three subdivision within a compound-meter or triplet-based groove. It is the rhythmic counterpart to triplet or dotted delay values, chosen to lock echoes to music in 6/8 or shuffle feels.','In some time signatures each beat splits into three even parts. A duplet splits that same beat into two even parts instead. A duplet delay sets its echo time to that two-part feel. This locks the delay to songs with a triplet or 6/8 groove.','It exists to time delay repeats to a two-against-three subdivision so echoes sit musically in compound-meter or triplet-feel songs rather than fighting the groove.','In a 6/8 or shuffle track, an engineer sets the delay to the duplet value so repeats land evenly across the beat instead of on straight or triplet divisions.','Delay timing',ARRAY['Tempo sync','Triplet delay','Dotted-eighth delay','Delay time','Compound meter','Note value']::text[],ARRAY['Confusing a duplet with a triplet; a duplet is two even notes in the space of three.','Using a duplet delay in straight 4/4, where it clashes with the eighth-note grid.','Setting the delay by ear and drifting off the compound-meter grid.']::text[],ARRAY['Timing a delay to a 6/8 ballad so echoes sit in the groove.','Adding echoes to a shuffle-feel track without fighting the triplet pulse.','Placing two-against-three echoes on a melody in compound meter.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a97177ef-7ec6-5df7-91fb-7e3eab6360f8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Duplet delay'),'[^a-z0-9]','','g'));
