SELECT '70889a83-4de7-5ad2-a64c-c8f6209b4eff','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='70889a83-4de7-5ad2-a64c-c8f6209b4eff' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '448b771f-00c5-5a8f-84a7-d09d47268f01','Euclidean delay pattern','A multi-tap delay whose active taps are placed across a fixed number of time steps using a Euclidean rhythm—an algorithm that distributes a given number of pulses as evenly as possible among the available steps. The result is a repeating, often syncopated tap pattern (such as 3 taps over 8 steps) of the kind found in many world-music rhythms.','A Euclidean pattern spreads a set number of hits as evenly as possible over a set number of steps. A Euclidean delay uses this to place its echo taps. For example, three taps spread across eight steps. This makes rhythmic, syncopated echo patterns.','It exists to generate musically interesting, evenly-spread rhythmic delay patterns from two simple numbers—pulses and steps—instead of setting each tap by hand.','An engineer sets a Euclidean delay to, say, 5 taps over 16 steps at tempo, so echoes fall into a repeating syncopated groove that locks to the track.','Delay pattern',ARRAY['Multi-tap delay','Tempo sync','Euclidean rhythm','Delay tap','Syncopation','Rhythmic delay']::text[],ARRAY['Forgetting to tempo-sync the step length, so the pattern drifts against the song.','Choosing pulse and step counts that clash with the song''s meter.','Piling on feedback so the evenly-spread taps blur into an indistinct wash.']::text[],ARRAY['Generating a syncopated echo groove on a synth pluck.','Creating a world-rhythm-style tap pattern under a melody.','Turning a single note into a repeating polyrhythmic figure.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='448b771f-00c5-5a8f-84a7-d09d47268f01' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Euclidean delay pattern'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '448b771f-00c5-5a8f-84a7-d09d47268f01','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='448b771f-00c5-5a8f-84a7-d09d47268f01' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '12e1a14d-21d0-5f0e-9751-6c08ad11fb70','Feedback ducking','A technique in which the feedback (regeneration) amount of a delay is automatically reduced while the input signal is present—via a sidechain from the dry source—so repeats build up only in the gaps and do not pile onto the source. It differs from ducking the delay output level in that it controls how many repeats accumulate, not just their loudness.','Feedback controls how many times a delay repeats. Feedback ducking turns that regeneration down while the source is playing. So the echoes stop piling up during the notes. They build back only in the gaps.','It exists to stop delay repeats from stacking up over a busy source, keeping the effect controlled while still letting tails develop in the spaces.','An engineer sidechains the delay''s feedback control to the dry input, so held or fast passages keep the regeneration low and the repeats grow only during pauses.','Delay technique',ARRAY['Feedback (delay)','Ducked delay','Sidechain (key input)','Ducking','Feedback freeze','Regeneration']::text[],ARRAY['Confusing feedback ducking with output ducking; one limits how many repeats build, the other only their level.','Reducing feedback so aggressively that the delay never develops a tail at all.','Setting a slow recovery, so the repeats never return in the gaps.']::text[],ARRAY['Keeping a high-feedback dub delay from washing out a busy verse.','Letting delay repeats build only in the spaces between guitar phrases.','Controlling runaway regeneration on a self-oscillating delay during dense passages.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='12e1a14d-21d0-5f0e-9751-6c08ad11fb70' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feedback ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '12e1a14d-21d0-5f0e-9751-6c08ad11fb70','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='12e1a14d-21d0-5f0e-9751-6c08ad11fb70' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fe14099c-0f28-5fc2-8db2-e31ecacca7b2','Feedback filtering','Placing a filter (commonly a low-pass or band-pass) inside a delay''s feedback loop so each successive repeat is progressively band-limited, typically losing high-frequency content as it recirculates. This models the darkening of analog tape and bucket-brigade echoes and keeps stacked repeats from becoming harsh or cluttered.','In a delay, each echo can be fed back to make more echoes. Feedback filtering puts a tone filter in that loop. So every repeat gets a little darker than the one before. This copies the warm, fading sound of old tape echoes.','It exists to make repeats decay in tone as well as level, mimicking analog echo and stopping bright, stacked repeats from cluttering or harshening the mix.','An engineer sets a low-pass in the delay feedback so trailing repeats grow darker, letting many echoes sit under a source without building up sibilance or fizz.','Delay processing',ARRAY['Feedback (delay)','Tape delay','Low-pass filter','Analog delay','Regeneration','Bucket-brigade delay']::text[],ARRAY['Confusing feedback filtering with filtering the delay output; only in the loop does each repeat get progressively darker.','Filtering so heavily that repeats vanish after one or two echoes.','Leaving the loop unfiltered, so bright digital repeats stack into a harsh, cluttered tail.']::text[],ARRAY['Emulating a warm tape echo on a vocal.','Keeping long guitar delays from building up harsh high end.','Darkening each repeat of a dub delay as it trails off.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fe14099c-0f28-5fc2-8db2-e31ecacca7b2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feedback filtering'),'[^a-z0-9]','','g'));
