INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5bef3ad9-369c-50cd-a00a-00ac55fab687','Feedback freeze','A function that holds a delay or reverb''s feedback at (or near) unity while temporarily blocking new input, so the currently circulating audio sustains indefinitely as a continuous loop or drone. Releasing the freeze returns the effect to normal decay, and the captured audio can be layered under new material.','Freeze locks a delay or reverb so its current sound sustains forever. The feedback is set to hold the audio in a loop. New sound is usually kept out so the frozen part stays steady. It makes an instant pad or drone you can play over.','It exists to capture and sustain a moment of audio as an endless pad or drone, giving a held bed to layer new parts against.','A player hits a freeze footswitch to hold a chord''s reverb or delay as a sustained drone, then plays a melody on top of the frozen bed.','Reverb/delay function',ARRAY['Feedback (delay)','Reverb tail','Infinite reverb','Regeneration','Ambient reverb','Sustain']::text[],ARRAY['Freezing on a dissonant or noisy moment, leaving an unpleasant drone locked in.','Expecting new playing to enter the freeze; most freezes block the input to hold the buffer steady.','UNSAFE: Stacking freezes or setting feedback above unity can make the sustained level climb until it clips or spikes loudly; watch gain and keep monitoring moderate, since sustained exposure above about 85 dBA risks hearing damage.']::text[],ARRAY['Holding a guitar chord as a pad to solo over.','Creating an ambient drone bed live under a vocal.','Sustaining a synth swell indefinitely in an intro.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5bef3ad9-369c-50cd-a00a-00ac55fab687' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feedback freeze'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5bef3ad9-369c-50cd-a00a-00ac55fab687','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5bef3ad9-369c-50cd-a00a-00ac55fab687' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6b78f056-5b6b-5cd5-a4a6-b417b7c4a84c','Feedback throw','A performance move in which a delay''s feedback (regeneration) is momentarily boosted—often together with the send level—on a single word or note, so that moment spins off into a cascade of self-multiplying repeats before the feedback is pulled back. It is a dub- and mix-style effect for emphasizing a phrase ending.','A throw sends one word or note into a big echo. A feedback throw also cranks the delay''s regeneration for that moment. So the sound spins off into many building repeats. Then you pull the feedback back before the next line.','It exists to spotlight a single word or note with a dramatic, self-multiplying echo cascade without drowning the rest of the performance in feedback.','An engineer rides the delay send and feedback up on a phrase ending, lets it spin into cascading repeats, then drops both back before the next line starts.','Delay technique',ARRAY['Delay throw','Delay send','Feedback (delay)','Dub delay','Automation','Ducked delay']::text[],ARRAY['Leaving the feedback boosted, so repeats run away and swamp the next line.','Throwing into an untimed delay that fights the song''s tempo.','UNSAFE: Pushing delay feedback into runaway self-oscillation can send a sudden, loud building squeal to the speakers; keep a hand on the send and monitor at safe levels, as sustained exposure above about 85 dBA risks hearing damage.']::text[],ARRAY['Spinning the last word of a chorus into cascading dub repeats.','Throwing a snare hit into a building echo at a transition.','Emphasizing a hook word with a momentary feedback burst.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6b78f056-5b6b-5cd5-a4a6-b417b7c4a84c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Feedback throw'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6b78f056-5b6b-5cd5-a4a6-b417b7c4a84c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6b78f056-5b6b-5cd5-a4a6-b417b7c4a84c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c7295f9b-db80-5c2e-b71a-8736e56f59ca','Fibonacci delay pattern','A scheme for setting the delay times of a multi-tap delay, or the delay-line lengths inside a reverberator, to values following the Fibonacci sequence (each term the sum of the two before it: 1, 1, 2, 3, 5, 8, 13, ...) or their ratios. Because successive Fibonacci ratios approach the golden ratio—an irrational number—the taps fall into a maximally non-repeating pattern that avoids the periodic echoes and comb-filter coloration produced by evenly spaced delays.','The Fibonacci sequence starts 1, 1, then adds each number to the one before. So it runs 1, 1, 2, 3, 5, 8, and so on. Setting echo times to these spacings makes the repeats fall unevenly. That stops the machine-gun flutter you get from evenly spaced echoes. The result sounds smoother and more natural.','It exists to spread delay taps so they do not land on a regular grid, which smooths the echo pattern and reduces the ringing and comb-filter coloration caused by periodic, evenly spaced repeats.','A sound designer or reverb programmer assigns tap or delay-line times using Fibonacci spacings when building a diffuse, natural-sounding early-reflection or multi-tap pattern rather than a rhythmic, evenly divided one.','Delay design',ARRAY['Golden-ratio delay','Multi-tap delay','Input diffusion','Comb filter','Early reflections','Feedback delay network']::text[],ARRAY['Assuming Fibonacci timing sets a musical rhythm, when it is chosen to avoid regular spacing rather than to lock to a tempo grid.','Focusing on the exact numbers rather than the irregular spacing they create, when the goal is simply non-periodic taps.','Using so few, widely spaced taps that individual echoes are heard instead of a smooth, diffuse pattern.']::text[],ARRAY['Programming a diffuse early-reflection pattern for a custom reverb algorithm.','Designing a multi-tap delay that avoids an obvious, repeating rhythmic pulse.','Smoothing the flutter in a short ambience effect on a dry vocal.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c7295f9b-db80-5c2e-b71a-8736e56f59ca' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fibonacci delay pattern'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c7295f9b-db80-5c2e-b71a-8736e56f59ca','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c7295f9b-db80-5c2e-b71a-8736e56f59ca' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7718ec99-982c-59c6-9729-2ffc322f8b21','Free-time delay','A delay whose repeat time is set directly in absolute units (milliseconds) independent of the song''s tempo, rather than synchronized to a musical note value or the sequencer''s clock. The echoes keep a fixed spacing regardless of tempo and do not lock to the beat.','Most delays can lock their echoes to the song''s beat. A free-time delay does not. You set its echo time in milliseconds by ear. The repeats stay the same length even if the tempo changes. Engineers use it when they want spacing that is not tied to the beat.','It exists to let an engineer dial an echo spacing purely by ear or for a specific effect, giving repeats that float against the groove instead of reinforcing the beat.','An engineer switches a delay out of tempo-sync mode and sets the time manually in milliseconds—often for slapback, a doubling effect, or a deliberately off-grid wash on a vocal or guitar.','Delay technique',ARRAY['Tempo-synced delay','Slapback delay','Haas delay','Groove-quantized delay','Doubling','Pre-delay']::text[],ARRAY['Leaving a delay in free-time when the part needs to lock to the beat, so the echoes drift against the groove.','Assuming free-time and tempo-synced delays sound the same, when only the synced one tracks tempo changes.','Setting the time by numbers alone instead of listening, and missing a spacing that sits better against the track.']::text[],ARRAY['Dialing a short slapback echo on a rockabilly vocal by ear.','Adding a fixed doubling delay to thicken a guitar regardless of song tempo.','Creating an intentionally off-grid ambient wash that floats over the beat.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7718ec99-982c-59c6-9729-2ffc322f8b21' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Free-time delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7718ec99-982c-59c6-9729-2ffc322f8b21','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7718ec99-982c-59c6-9729-2ffc322f8b21' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '818750ee-20d6-530c-ba46-0dfd9501836e','Frequency-dependent decay','The property of a reverberant space or reverb algorithm in which the decay time (RT60) differs across the spectrum—typically high frequencies decaying faster than low and mid frequencies because air absorption and most surface materials absorb more energy at high frequencies. Reverb processors model this with lowpass filtering in the feedback path so the tail grows darker as it fades.','In a real room, high notes fade away faster than low notes. Air and soft surfaces soak up treble more than bass. So a reverb tail slowly gets darker as it dies out. Reverb units copy this by rolling off the highs as the sound decays. It makes the effect sound like a real space.','It exists to make reverberation sound natural, since real rooms rarely decay evenly; controlling how fast highs fade shapes whether a space feels bright and live or dark and warm.','An engineer adjusts a reverb''s high-frequency damping or decay-ratio controls so the tail darkens realistically, taming harshness on cymbals or adding warmth without dulling the direct sound.','Reverb behavior',ARRAY['RT60','High-frequency decay multiplier','Damping','Air absorption','Decay time','Early reflections']::text[],ARRAY['Thinking reverb decays at one single time, when real spaces decay at different rates in different frequency bands.','Setting the high-frequency decay so long that cymbals and sibilance wash and smear the mix.','Cutting all the high-frequency decay, leaving a dull, lifeless tail with no air.']::text[],ARRAY['Shaping a hall reverb so cymbals do not ring harshly in the tail.','Adding warmth to a vocal plate by shortening the high-frequency decay.','Matching an artificial reverb to the dark decay of a real, carpeted room.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='818750ee-20d6-530c-ba46-0dfd9501836e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-dependent decay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '818750ee-20d6-530c-ba46-0dfd9501836e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='818750ee-20d6-530c-ba46-0dfd9501836e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b71b22ff-0bf3-5fcd-804a-fd64e9675727','Frequency-dependent reverb width','A reverb design or processing choice in which the stereo width of the reverberation varies by frequency band—commonly keeping low frequencies narrow or mono while allowing mid and high frequencies to spread wider in the stereo image. This mirrors how low-frequency energy in real rooms is less directional, and helps keep a mix''s low end centered and mono-compatible.','Low sounds are hard to place in space; high sounds are easier. So engineers often keep a reverb''s bass in the center and let its highs spread wide. This keeps the low end tight and solid. It also avoids problems when the mix plays in mono. The result feels wide up top but focused down low.','It exists to give a reverb a wide, enveloping high end while keeping bass energy centered, which preserves low-end punch and mono compatibility.','An engineer uses a reverb with per-band width control, or splits the reverb return with a crossover, to narrow the lows and widen the highs so the effect sits wide without loosening the low end.','Reverb parameter',ARRAY['Stereo width','Mono compatibility','Crossover','Frequency-dependent decay','Reverb return','Mid-side processing']::text[],ARRAY['Spreading low-frequency reverb wide, which smears the low end and can weaken it in mono.','Assuming a reverb''s width is the same at every frequency, when it can be shaped per band.','Widening the highs so aggressively that the reverb loses a stable phantom center.']::text[],ARRAY['Keeping a big vocal reverb wide up top but mono in the bass for a club system.','Fixing a reverb that thins or collapses when a mix is summed to mono.','Adding width to a synth pad''s reverb without muddying the low end.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b71b22ff-0bf3-5fcd-804a-fd64e9675727' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-dependent reverb width'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b71b22ff-0bf3-5fcd-804a-fd64e9675727','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b71b22ff-0bf3-5fcd-804a-fd64e9675727' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '63413e63-1e8a-5453-b28c-fab27a618ae5','Gated room microphone','A room or ambience microphone whose signal is passed through a noise gate so the captured reverberation is cut off abruptly rather than allowed to decay naturally. The gate opens on a loud transient such as a drum hit and closes after a set hold and release, producing the dense-then-suddenly-silent ''gated reverb'' sound made famous on 1980s drum recordings.','A room mic picks up a drum plus the room''s natural echo. Feeding that mic through a gate lets you chop the echo off fast. The gate opens on the hit, then snaps shut. You hear a big burst of ambience that stops suddenly. This is the huge, punchy 1980s drum sound.','It exists to make a drum sound huge and powerful by adding a wall of room ambience, then cutting it off before the natural tail muddies the groove or masks the next hit.','An engineer routes a heavily compressed room mic through a gate on the drum bus, setting the threshold to open on hits and the hold/release to close before the next beat, for an explosive but tight ambience.','Reverb technique',ARRAY['Gated reverb','Noise gate','Room microphone','Ambience','Reverb tail','Drum bus']::text[],ARRAY['Setting the gate release too long, so the ambience bleeds into the next hit and loses the abrupt cutoff.','Setting the threshold so high that softer hits fail to open the gate and drop out.','UNSAFE: Monitoring a heavily compressed, loud room-mic burst at high level; sustained exposure above about 85 dBA (A-weighted decibels) risks hearing damage, so keep monitoring levels moderate.']::text[],ARRAY['Getting an explosive 1980s-style snare and tom sound in a rock mix.','Adding controlled power to drums recorded in a live-sounding room.','Tightening an over-long room ambience so it does not wash across the groove.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='63413e63-1e8a-5453-b28c-fab27a618ae5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gated room microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '63413e63-1e8a-5453-b28c-fab27a618ae5','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='63413e63-1e8a-5453-b28c-fab27a618ae5' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '78a35fdb-3398-5576-b2ec-85a3832ee20b','Golden-ratio delay','A delay or reverb design in which delay times or delay-line lengths are set in the golden ratio (approximately 1.618) to one another. Because the golden ratio is the ''most irrational'' number and cannot be closely approximated by simple whole-number fractions, spacing taps by it yields a maximally aperiodic pattern that avoids the coincident reflections, resonances, and comb-filter coloration produced by harmonically related delays.','The golden ratio is a special number, about 1.618, found often in nature. Spacing echoes by this ratio makes them line up as unevenly as possible. That avoids the ringing and repeating patterns of even spacing. Reverb designers use it to get a smooth, natural wash.','It exists to make delay and reverb taps as non-repeating as possible, minimizing resonant peaks and metallic coloration that occur when delay lengths share simple whole-number relationships.','A reverb designer chooses delay-line lengths in golden-ratio proportions when tuning a network so its tail is dense and smooth rather than ringing on particular pitches.','Delay design',ARRAY['Fibonacci delay pattern','Comb filter','Feedback delay network','Input diffusion','Early reflections','Multi-tap delay']::text[],ARRAY['Believing the golden ratio adds a mystical quality, when it simply produces maximally non-repeating delay spacing.','Setting delay lengths in simple whole-number ratios, which reintroduces the ringing the design aims to avoid.','Treating golden-ratio timing as a rhythmic musical value rather than a tool for smooth diffusion.']::text[],ARRAY['Tuning the delay lengths inside a custom reverb for a smooth, uncolored tail.','Designing a multi-tap delay that avoids obvious repeating pitches.','Reducing metallic ringing in a short ambience patch.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='78a35fdb-3398-5576-b2ec-85a3832ee20b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Golden-ratio delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '78a35fdb-3398-5576-b2ec-85a3832ee20b','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='78a35fdb-3398-5576-b2ec-85a3832ee20b' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c3a76c8f-7df3-5b9d-b5b4-e217a9cf0af9','Groove-quantized delay','A tempo-synced delay whose repeat timing is shifted to follow a groove or swing template rather than landing on straight, evenly divided subdivisions. The echoes are nudged early or late to match the swing feel of the track, so the repeats sit in the pocket instead of sounding mechanically on-grid.','A normal synced delay puts echoes on an even grid. A groove-quantized delay bends that timing to match a song''s swing. The repeats fall a little early or late, like a human groove. This makes the echoes feel like part of the performance. They sit in the pocket instead of sounding stiff.','It exists to make tempo-synced echoes feel musical and human by matching the song''s swing, rather than clashing with a swung rhythm by landing on a rigid straight grid.','An engineer applies a swing or groove template to a synced delay—or sets a swing percentage on the plug-in—so echoes on a shuffled hip-hop or house track fall with the groove instead of against it.','Delay technique',ARRAY['Tempo-synced delay','Swing','Quantization','Free-time delay','Dotted-eighth delay','Groove template']::text[],ARRAY['Using a straight-grid delay on a heavily swung track, so the echoes fight the groove.','Applying so much swing to the delay that repeats clash with the drums instead of locking to them.','Confusing groove-quantized timing with off-grid free-time delay, when this one still follows the tempo.']::text[],ARRAY['Matching a delay''s echoes to the shuffle of a hip-hop beat.','Locking a synced vocal delay to a swung house groove.','Making a rhythmic guitar delay sit in the pocket of a live-feeling track.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c3a76c8f-7df3-5b9d-b5b4-e217a9cf0af9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Groove-quantized delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c3a76c8f-7df3-5b9d-b5b4-e217a9cf0af9','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c3a76c8f-7df3-5b9d-b5b4-e217a9cf0af9' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'eeee5ec5-397c-52ae-88bc-5c47990bcde8','Haas delay','A stereo-widening or reinforcement technique based on the Haas (precedence) effect, in which a copy of a signal is delayed by roughly 1–35 ms relative to the original and typically panned oppositely. Within this window the ear fuses the two arrivals into a single event localized toward the earlier one, so the delayed copy broadens the image and adds loudness without being heard as a distinct echo; beyond about 40 ms the copy separates into an audible echo.','Two copies of a sound may arrive within a few thousandths of a second. Then your ears hear one sound, not two. Your ears place that single sound where the first copy came from. Panning the original one way and a short-delayed copy the other makes the sound wider. Push the delay past about 40 milliseconds and you start to hear a separate echo. The effect is named after researcher Helmut Haas.','It exists to widen or thicken a sound and steer where it appears to come from, using the ear''s tendency to lock onto the first arrival rather than adding an obvious echo.','An engineer duplicates a mono source, delays one side by around 10–30 ms, and pans the two apart to spread a vocal, guitar, or synth across the stereo field.','Psychoacoustic effect',ARRAY['Precedence effect','Haas effect','Slapback delay','Stereo width','Comb filter','Free-time delay']::text[],ARRAY['Setting the delay too long (past about 40 ms), so the copy becomes an audible echo instead of fusing into one wider image.','Ignoring mono compatibility, since a Haas-widened sound can partly cancel or shift when summed to mono.','Making the delayed side much louder than the original, which pulls localization toward it and can break the effect.']::text[],ARRAY['Widening a mono synth or guitar to fill a stereo mix.','Adding width and presence to a lead vocal without an obvious echo.','Reinforcing a distant loudspeaker with a delay so sound still seems to come from the stage.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='eeee5ec5-397c-52ae-88bc-5c47990bcde8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Haas delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'eeee5ec5-397c-52ae-88bc-5c47990bcde8','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='eeee5ec5-397c-52ae-88bc-5c47990bcde8' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '10d9f8ea-075b-50f7-83cd-82836a4a345f','High-frequency decay multiplier','A reverb parameter that scales the decay time of high frequencies relative to the reverb''s mid-band decay time, expressed as a ratio or multiplier. A value below 1 shortens the high-frequency tail so treble fades faster than the mids (modeling air and surface absorption), while a value near or above 1 lets highs ring on for a brighter, more artificial space.','Reverbs let you set how long the sound rings out. This control changes that time for the high notes only. Set it below one and the treble fades faster than the rest. That copies how real rooms lose their highs first. Set it high and the reverb stays bright and airy.','It exists to shape the tonal balance of a reverb tail over time, letting an engineer make highs decay faster for realism or linger for brightness, independent of the overall decay time.','An engineer lowers the high-frequency decay multiplier to tame harsh cymbal or sibilant tails, or raises it for a brighter, more sustained ambience on pads and vocals.','Reverb parameter',ARRAY['Frequency-dependent decay','RT60','Damping','Decay time','Crossover','Air absorption']::text[],ARRAY['Confusing the multiplier with overall decay time, when it only scales the high-frequency portion.','Setting the high-frequency decay very long, so cymbals and sibilance wash and smear.','Pulling it so low that the tail turns dull and muffled with no air.']::text[],ARRAY['Shortening a bright plate''s high-frequency tail so vocals stay clear.','Dialing a natural hall where treble dies faster than the low mids.','Keeping a synth reverb airy by letting the highs ring longer.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='10d9f8ea-075b-50f7-83cd-82836a4a345f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('High-frequency decay multiplier'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '10d9f8ea-075b-50f7-83cd-82836a4a345f','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='10d9f8ea-075b-50f7-83cd-82836a4a345f' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cd814a43-e2a9-5e8b-9c28-32144e7acb2c','Infinite reverb','A reverb mode in which the decay time is set effectively to infinity so the reverberation sustains indefinitely instead of dying away. It is produced by raising the feedback in the reverb network to (or just below) unity gain, or by a dedicated ''freeze'' or ''hold'' function that locks the current tail into a continuous, unchanging pad.','Normally a reverb tail slowly fades to silence. Infinite reverb never fades. It holds the sound forever as a steady wash. Many units have a ''freeze'' or ''hold'' button that does this. Musicians use it to build long, drifting pads from a single note or chord.','It exists to sustain a sound indefinitely, turning a short input into a continuous pad or drone for ambient textures, transitions, or holding a note under a passage.','An engineer engages a reverb''s freeze or infinite-decay mode to hold a chord as a swelling background pad, then plays or sings over the sustained wash.','Reverb mode',ARRAY['Decay time','RT60','Feedback delay network','Input diffusion','Shimmer reverb','Interval shimmer']::text[],ARRAY['Pushing feedback above unity gain, so the reverb builds up and self-oscillates into runaway level.','UNSAFE: Letting an infinite or self-oscillating reverb build unchecked while monitoring loud; a sudden level runaway can spike output and risk hearing damage or blown drivers, so keep monitoring moderate and a hand on the fader.','Freezing a tail that still contains the dry transient, so the pad has an unwanted click or word looping in it.']::text[],ARRAY['Holding a synth chord as a continuous ambient pad.','Creating a drone bed under a film scene transition.','Sustaining a guitar note into an endless wash for a post-rock texture.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cd814a43-e2a9-5e8b-9c28-32144e7acb2c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Infinite reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cd814a43-e2a9-5e8b-9c28-32144e7acb2c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cd814a43-e2a9-5e8b-9c28-32144e7acb2c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4df15e2f-86be-5248-94c3-0ae48abb8f98','Input diffusion','A reverb parameter that controls how much the input signal is smeared in time by a chain of allpass filters before (or as) it enters the reverb''s recirculating network. Higher input diffusion spreads sharp transients into many closely spaced reflections so the reverb builds smoothly; lower diffusion preserves distinct early echoes, giving a grainier, more articulate onset.','A reverb can smear the start of a sound before the tail builds. This control sets how much smearing happens up front. Turn it up and sharp hits melt into a smooth wash. Turn it down and you hear separate early echoes. Percussion often needs high diffusion; sustained sounds can use less.','It exists to control the texture of a reverb''s onset, letting an engineer trade a smooth, dense build-up against clearer, more distinct early reflections to suit the source material.','An engineer raises input diffusion on drums and percussion so transients do not produce discrete flutter echoes, and lowers it on sustained sources like vocals or pads to keep early reflections defined.','Reverb parameter',ARRAY['Allpass filter','Early reflections','Diffusion','Comb filter','Pre-delay','RT60']::text[],ARRAY['Setting diffusion very low on percussive sources, producing metallic flutter instead of a smooth tail.','Maxing diffusion on sustained material, which can smear and blur the early reflections you wanted to hear.','Confusing input diffusion with decay time, when it shapes the onset texture rather than how long the tail lasts.']::text[],ARRAY['Smoothing a snare''s reverb so the onset does not flutter.','Keeping early reflections distinct on a vocal for a sense of a real room.','Tuning a plate reverb''s grain on a piano or guitar.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4df15e2f-86be-5248-94c3-0ae48abb8f98' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Input diffusion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4df15e2f-86be-5248-94c3-0ae48abb8f98','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4df15e2f-86be-5248-94c3-0ae48abb8f98' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1be93fb6-44d7-5ff5-b1fb-706824f7754a','Input-ducked delay','A delay effect whose repeats are automatically attenuated while the dry input signal is present, and allowed to rise in the gaps, using a sidechain (ducking) from the input to a compressor on the delay return. This keeps echoes from cluttering a busy part and lets them bloom only when the source pauses.','Echoes can pile up and clutter a busy vocal. An input-ducked delay turns the echoes down while the singer sings. In the gaps between phrases, the echoes rise up. So the words stay clear and the delay still adds space. It uses the dry signal to control the echo level.','It exists to keep a delay from smearing or masking the source, holding the repeats back during phrases and letting them swell in the spaces so the effect adds depth without hurting clarity.','An engineer sidechains a compressor on the delay return, keyed from the dry vocal, so the echoes duck under each sung phrase and bloom in the pauses at line ends.','Delay technique',ARRAY['Ducking','Sidechain (key input)','Delay return','Vocal reverb ducking','Feedback (delay)','Send effect']::text[],ARRAY['Setting the ducking release too fast, so the delay pumps loudly between words.','Keying the ducking from the wet delay instead of the dry input, so it never opens fully.','Ducking so deeply that the echoes vanish and the intended sense of space is lost.']::text[],ARRAY['Adding a long echo to a busy lead vocal without smearing the lyrics.','Letting a delay wash bloom only in the gaps of a wordy rap verse.','Keeping a rhythmic guitar delay from cluttering a dense arrangement.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1be93fb6-44d7-5ff5-b1fb-706824f7754a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Input-ducked delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1be93fb6-44d7-5ff5-b1fb-706824f7754a','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1be93fb6-44d7-5ff5-b1fb-706824f7754a' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6fadcb80-ca3c-596c-a47b-4ddf6046df7a','Interval shimmer','A shimmer-reverb effect in which the reverb feedback is pitch-shifted by a fixed musical interval—commonly an octave, fifth, or fourth—so each pass through the loop adds a new pitched layer stacked at that interval above (or below) the input. Repeated regeneration builds an evolving, harmonically rich tail rather than the simple octave rise of basic shimmer.','Shimmer reverb feeds its echo back through a pitch shifter. Interval shimmer shifts that feedback by a set musical step, like a fifth or an octave. Each pass stacks another note at that step. The tail slowly grows into a glowing chord. It turns a single note into a lush, rising wash.','It exists to add harmonic, ethereal color to a reverb tail, stacking pitched intervals with each regeneration so a simple source blooms into an evolving, pad-like texture.','A guitarist or producer sets a shimmer reverb''s pitch interval (for example a fifth or an octave) and raises the feedback so held notes build into a rich, sustained harmonic wash.','Reverb effect',ARRAY['Shimmer reverb','Pitch shifting','Feedback (reverb)','Infinite reverb','Freeze','Reverb tail']::text[],ARRAY['UNSAFE: Setting pitch-shifted feedback near or above unity lets the reverb build to a runaway, escalating level; keep monitoring moderate and a hand on the fader to protect hearing and speakers.','Choosing an interval that clashes with the song''s key, making the shimmer sound out of tune.','Blending the shimmer so loud that it buries the dry source instead of haloing it.']::text[],ARRAY['Turning a held guitar note into a glowing, chord-like ambient pad.','Adding a rising, angelic sheen to a synth or vocal in a cinematic track.','Building an evolving harmonic drone from a single sustained source.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6fadcb80-ca3c-596c-a47b-4ddf6046df7a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Interval shimmer'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6fadcb80-ca3c-596c-a47b-4ddf6046df7a','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6fadcb80-ca3c-596c-a47b-4ddf6046df7a' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4870ce81-7ca8-570f-8c89-94881f15969a','Inverse ducked delay','A delay treatment in which a sidechain detector keyed from the dry source controls the echo level with the opposite gain envelope of a standard ducked delay: the delay repeats are raised while the source signal is present and attenuated in the gaps between phrases, rather than the usual arrangement where echoes are suppressed during phrases and swell in the silences.','A normal ducked delay hides the echoes while someone sings. It lets them swell in the gaps. An inverse ducked delay flips this idea. It makes the echoes louder while the singer sings. Then it turns them down in the gaps.','It exists to give a mix engineer dynamic, program-dependent control over echoes, letting the delay reinforce a source during active passages while stepping back in the pauses, the reverse of conventional ducking.','An engineer sidechains a compressor on the delay return from the dry vocal so the repeats rise with the vocal and fall in the gaps, then blends the return to taste.','Delay technique',ARRAY['Ducked delay','Output-ducked delay','Sidechain','Slapback delay','Feedback delay','Pre-delay']::text[],ARRAY['Confusing it with standard ducked delay, which suppresses echoes during phrases rather than raising them.','Setting sidechain attack and release so slow that the level changes lag the performance and sound sloppy.','Pushing feedback and level so high that the constantly present echoes clutter the mix and mask the source.']::text[],ARRAY['Reinforcing a lead vocal with echo energy during sung phrases while keeping the gaps clean.','Adding rhythmic delay to a synth line that pushes up under the notes and eases off between them.','Creating a texture that sits under a source rather than filling the spaces around it.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4870ce81-7ca8-570f-8c89-94881f15969a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Inverse ducked delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4870ce81-7ca8-570f-8c89-94881f15969a','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4870ce81-7ca8-570f-8c89-94881f15969a' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c0c7b951-9f66-5424-bcfe-2900aec863b3','Keyed reverb gating','A technique in which a noise gate placed on a reverb return is opened and closed by an external key (sidechain) signal rather than by the reverb''s own level, so the abrupt onset and truncation of the reverb tail follow the dynamics of the keying source. It extends the classic gated-reverb effect by tying the gate''s timing to a separate trigger such as the dry drum hit.','A gate is a switch that opens for loud sounds and shuts for quiet ones. Gated reverb chops the reverb tail off sharply. Keyed reverb gating uses a second sound to work that switch. So another track decides exactly when the reverb is heard.','It exists to control precisely when a reverb tail is audible, letting the effect follow a chosen trigger for tight, rhythmic, or dramatic gating instead of relying on the reverb''s own decay level.','An engineer feeds the dry snare into the key input of a gate on the reverb return, then sets threshold, hold, and release so the reverb bursts with each hit and cuts off cleanly.','Reverb technique',ARRAY['Gated reverb','Noise gate','Sidechain','Pre-delay','Reverb time (RT60)','Non-linear reverb']::text[],ARRAY['Keying the gate from a source with slow or weak transients, so the gate opens late or misfires.','Setting hold and release too short, which clips the reverb into an unnatural click instead of a burst.','Forgetting that the key signal is only a trigger and does not itself pass to the output.']::text[],ARRAY['Recreating the tight, explosive 1980s gated snare sound with an external trigger.','Making a lush reverb pulse rhythmically in time with a drum or percussion track.','Cutting a long reverb tail off cleanly before the next section for a dramatic stop.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c0c7b951-9f66-5424-bcfe-2900aec863b3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Keyed reverb gating'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c0c7b951-9f66-5424-bcfe-2900aec863b3','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c0c7b951-9f66-5424-bcfe-2900aec863b3' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f43b91e0-c341-550a-9b43-ce0f7120064c','Layered reverb','A production technique that combines two or more reverb processors—typically run in parallel and sometimes in series—to build a single composite space, for example pairing a short early-reflection or ambience reverb with a longer, denser tail. Each layer can use a different algorithm, decay time, or tonal balance so the combined result has more depth and realism than any one unit alone.','One reverb can only do so much. Layered reverb runs two or more reverbs together. One might add a small room, another a long tail. Blending them builds a richer, deeper sense of space.','It exists to give the engineer independent control over different parts of a reverberant field—early reflections, tail length, and tone—so a space can be sculpted with more nuance than a single reverb allows.','An engineer sends a vocal to two aux returns, a short plate for presence and a long hall for depth, then balances their levels and pre-delays to place the voice in a believable space.','Reverb technique',ARRAY['Early reflections','Pre-delay','Reverb time (RT60)','Plate reverb','Hall reverb','Send/return']::text[],ARRAY['Stacking several long reverbs until the mix turns muddy and the source loses clarity.','Leaving both layers full-range so their low frequencies build up and cloud the bottom end.','Using identical settings on each layer, which adds level but no real added dimension.']::text[],ARRAY['Placing a lead vocal in a space with both intimate early reflections and a long, lush tail.','Combining a room reverb and a plate on drums for both natural ambience and sustain.','Building a cinematic pad texture from several reverbs with different tones and decay times.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f43b91e0-c341-550a-9b43-ce0f7120064c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Layered reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f43b91e0-c341-550a-9b43-ce0f7120064c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f43b91e0-c341-550a-9b43-ce0f7120064c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '84307fbc-5744-54ac-a949-4db8d17a0eb9','Level-dependent ambience','An approach in which the amount or character of ambience applied to a source varies with the source''s signal level, usually by driving a dynamics processor on the reverb send or return from the dry level. Loud passages typically receive less audible ambience and quiet passages more, keeping the effect present without washing out dense material.','Loud parts of a track can drown in reverb. Level-dependent ambience changes with the volume. When the sound is loud, it adds less space. When the sound is soft, it adds more. This keeps the mix clear.','It exists to keep a reverb tasteful and intelligible across dynamics, adding space where it is wanted in quiet moments and pulling back where loud, dense passages would otherwise become cluttered.','An engineer sidechains the reverb return to the dry track so busy, loud sections duck the ambience and sparse, quiet sections let it bloom.','Reverb technique',ARRAY['Ducked delay','Reverb send','Sidechain','Pre-delay','Reverb time (RT60)','Early reflections']::text[],ARRAY['Setting the dynamics so aggressively that the ambience pumps audibly with every level change.','Confusing it with a fixed reverb amount, then wondering why the tail seems to come and go.','Ignoring release time, so the ambience snaps back too fast or lingers too long after loud passages.']::text[],ARRAY['Keeping a busy chorus clear while letting the verses breathe with more space.','Automating ambience on a dynamic vocal that moves from a whisper to a belt.','Managing reverb on a drum bus so fills do not smear while quieter grooves stay ambient.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='84307fbc-5744-54ac-a949-4db8d17a0eb9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Level-dependent ambience'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '84307fbc-5744-54ac-a949-4db8d17a0eb9','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='84307fbc-5744-54ac-a949-4db8d17a0eb9' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '14310dbe-cb0b-5e32-8f48-7f65e3e2b2ba','Level-modulated delay','A delay effect in which a control parameter—commonly the wet level, feedback amount, or mix—is modulated by the amplitude envelope of the input signal rather than by a fixed low-frequency oscillator. As the source gets louder or softer, the delay''s contribution changes in step, making the echoes respond dynamically to the performance.','This delay reacts to how loud you play. When the sound gets louder, the echoes change with it. They might grow or shrink in volume. The delay follows your playing instead of staying fixed.','It exists to make delay feel responsive and musical, tying the echo''s presence to the dynamics of the part so the effect supports rather than fights the performance.','An engineer routes the input envelope to the delay''s level or feedback so hard-hit notes push the echoes forward and soft notes let them recede.','Delay technique',ARRAY['Ducked delay','Inverse ducked delay','Modulated delay','Envelope follower','Feedback delay','Sidechain']::text[],ARRAY['Confusing it with modulated delay, which sweeps delay time with an oscillator, not with level.','Setting the envelope response so fast that the delay level jitters unnaturally with every transient.','UNSAFE: Modulating feedback toward self-oscillation can produce a sudden, extreme level spike; keep monitoring levels moderate and lower the control-room volume before testing high-feedback settings, to protect hearing and speakers.']::text[],ARRAY['Making guitar echoes swell only on hard-picked accents and stay subtle elsewhere.','Tying synth delay depth to how hard keys are played for expressive repeats.','Keeping vocal delays out of the way until a loud line pushes them forward.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='14310dbe-cb0b-5e32-8f48-7f65e3e2b2ba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Level-modulated delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '14310dbe-cb0b-5e32-8f48-7f65e3e2b2ba','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='14310dbe-cb0b-5e32-8f48-7f65e3e2b2ba' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd098dcb0-24dc-5568-a948-c309ea965102','Low-frequency decay multiplier','A reverb parameter that sets the decay time of low-frequency content as a multiple of the main (mid-band) reverb time; a multiplier above 1.0 makes bass frequencies ring longer than the mids, while a value below 1.0 makes them decay faster. On many units it is called Bass Multiply or Bass RT and operates relative to a chosen crossover frequency.','Real rooms often hold onto low notes longer than high ones. This control sets how long the bass part of the reverb lasts. A setting of two makes bass ring twice as long as the mids. A lower setting makes bass fade faster.','It exists to shape the tonal balance of the reverb tail over time, letting an engineer emulate warm rooms with long bass decay or tighten boomy low end that would otherwise cloud the mix.','An engineer raises the multiplier for a warmer, larger-sounding hall, or lowers it below 1.0 to keep a dense low-end mix clean under the reverb.','Reverb parameter',ARRAY['Reverb time (RT60)','Pre-delay','High-frequency damping','Crossover frequency','Diffusion','Hall reverb']::text[],ARRAY['Pushing the bass multiplier high on a full mix, then fighting a boomy, muddy low end.','Assuming it changes the reverb level; it changes low-frequency decay time, not loudness.','Overlooking the crossover setting that decides which frequencies the multiplier affects.']::text[],ARRAY['Warming up a vocal reverb by letting low frequencies ring a little longer.','Tightening a drum reverb by cutting bass decay so kicks stay punchy.','Emulating a large concert hall where low frequencies sustain longer than highs.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d098dcb0-24dc-5568-a948-c309ea965102' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Low-frequency decay multiplier'),'[^a-z0-9]','','g'));
