WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d098dcb0-24dc-5568-a948-c309ea965102' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0b98a9ea-9a41-5ba7-9a57-d40212ebc31e','Microdelay widening','A stereo-widening technique that applies a very short delay—typically a few milliseconds up to roughly 30 ms—to one channel of a signal relative to the other, exploiting the precedence (Haas) effect so the ear fuses the two into one wider image rather than hearing a distinct echo. The small inter-channel time difference broadens perceived width without altering the mono content''s pitch.','Delaying one side of a sound by a tiny amount makes it seem wider. The ear blends the two into one sound. This works because our hearing merges sounds that arrive very close together. The gap must stay short, or you hear a separate echo.','It exists to create stereo width from a mono or narrow source using only timing, giving a bigger image without the phase-cancellation problems that come from simple level panning.','An engineer duplicates a mono guitar, delays one side by around 10 to 25 milliseconds, and pans the two hard apart to spread it across the stereo field.','Delay technique',ARRAY['Haas effect','Precedence effect','Slapback delay','Comb filtering','Mono compatibility','Pre-delay']::text[],ARRAY['Using a delay long enough, beyond roughly 35 to 50 ms, that listeners hear a distinct slap echo instead of width.','Ignoring mono compatibility, so the widened track partly cancels when the mix is summed to mono.','Widening a bass or kick, where short inter-channel delays cause phase problems and weaken the low end.']::text[],ARRAY['Turning a single mono guitar take into a wide stereo part.','Spreading a mono synth or backing vocal across the stereo image.','Adding width to a doubled part without re-recording a second performance.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0b98a9ea-9a41-5ba7-9a57-d40212ebc31e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Microdelay widening'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0b98a9ea-9a41-5ba7-9a57-d40212ebc31e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0b98a9ea-9a41-5ba7-9a57-d40212ebc31e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '98404926-a64f-5a0b-a82f-2505f9489cfd','Modulated delay','A delay effect in which the delay time is continuously varied, usually by a low-frequency oscillator, causing small cyclical pitch shifts and moving comb-filter coloration in the output. Short modulated delays with feedback form the basis of flanging and chorus, while modulating a longer delay adds movement and richness to the repeats.','A normal delay repeats a sound after a set time. A modulated delay keeps changing that time slightly. This adds a gentle wobble or shimmer to the echoes. It is how chorus and flanger effects are made.','It exists to add motion, thickness, and a sense of life to otherwise static delays, and it provides the core mechanism behind chorus, flanging, and vibrato effects.','An engineer adds slow, shallow modulation to a delay so the repeats gently detune and feel less mechanical, or dials in faster, deeper modulation for an obvious chorus or flange.','Delay technique',ARRAY['Modulated reverb','Chorus','Flanging','Feedback delay','Low-frequency oscillator (LFO)','Comb filtering']::text[],ARRAY['Setting modulation depth so deep that the pitch warble sounds seasick and out of tune.','Confusing it with level-modulated delay, which varies loudness, not delay time.','Adding modulation to a tempo-synced delay and expecting the timing to stay perfectly locked.','UNSAFE: High feedback on a short modulated delay (flanging) can self-oscillate into a loud, piercing tone; keep monitoring levels moderate and turn down the control room before raising feedback, to protect hearing and equipment.']::text[],ARRAY['Thickening a lead vocal or guitar with a subtle chorused delay.','Creating classic flanging by modulating a very short delay with feedback.','Making synth or ambient echoes drift and evolve instead of repeating identically.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='98404926-a64f-5a0b-a82f-2505f9489cfd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Modulated delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '98404926-a64f-5a0b-a82f-2505f9489cfd','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='98404926-a64f-5a0b-a82f-2505f9489cfd' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '329fbb30-9c8b-5d8a-a5bf-a96200422f9c','Modulated reverb','A reverb in which the internal delay taps or comb/all-pass structures are continuously modulated—by parameters such as spin, wander, or chorus—so the timbre of the reverberant tail shifts over time. This movement breaks up static resonances and metallic ringing, producing a smoother, richer, and more natural decay.','Digital reverb tails can sound metallic or ringy. Modulated reverb keeps gently moving the sound inside the tail. This smooths out the harsh ringing. The result is a lusher, more natural space.','It exists to reduce the periodic, metallic artifacts of digital reverberation and to add a lush, chorused character, giving the tail a livelier and more organic quality.','An engineer raises the reverb''s modulation, spin, or chorus depth to smooth a ringing tail, or pushes it further for an obvious shimmering, chorused wash on pads and vocals.','Reverb technique',ARRAY['Modulated delay','Chorus','Diffusion','Comb filtering','Reverb time (RT60)','Plate reverb']::text[],ARRAY['Cranking modulation so high the reverb sounds detuned and warbly on sustained notes.','Confusing tail modulation with pre-delay or decay-time controls, which do different jobs.','Applying heavy modulated reverb to a piano or bass, where the pitch movement sounds unstable.']::text[],ARRAY['Smoothing a ringing digital hall on a lead vocal.','Adding lush, chorused depth to synth pads and ambient guitars.','Recreating classic 1980s modulated plate and hall sounds.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='329fbb30-9c8b-5d8a-a5bf-a96200422f9c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Modulated reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '329fbb30-9c8b-5d8a-a5bf-a96200422f9c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='329fbb30-9c8b-5d8a-a5bf-a96200422f9c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2bf8ad0d-0838-5cfc-b83d-6a639f3eb2bb','Mono-in/stereo-out reverb','A reverb configuration in which a single mono input signal is processed to produce a two-channel stereo output, with the left and right reverb tails decorrelated so the source appears to sit in a wide, enveloping space. The mono input is sent to both channels of the processor, which returns a stereo reverberant field.','You feed this reverb one single, mono sound. It sends back a two-channel stereo tail. The left and right sides differ slightly. This spreads the sound into a wide, roomy space.','It exists to turn a mono source into a spacious stereo image, providing width and a sense of environment from a single input without needing a stereo recording.','An engineer sends a mono vocal or snare to a mono-in/stereo-out reverb on an aux, then returns the stereo output to place the source in a wide space.','Reverb technique',ARRAY['Decorrelation','Stereo width','Pre-delay','Early reflections','Reverb time (RT60)','Plate reverb']::text[],ARRAY['Assuming the two output channels are identical; they are decorrelated, and summing to mono can partly cancel them.','Feeding it a stereo source and losing the left-right positioning of the dry signal in the tail.','Panning both returns to the center, which throws away the width the effect creates.']::text[],ARRAY['Placing a mono lead vocal in a wide stereo space.','Adding stereo ambience to a mono-recorded snare or guitar.','Creating width in a mix built largely from mono sources.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2bf8ad0d-0838-5cfc-b83d-6a639f3eb2bb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mono-in/stereo-out reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2bf8ad0d-0838-5cfc-b83d-6a639f3eb2bb','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2bf8ad0d-0838-5cfc-b83d-6a639f3eb2bb' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '455bfc23-00a7-5dc3-863a-bffcbeecec9e','Non-repeating tap pattern','A multitap delay or early-reflection design in which the individual tap times are spaced irregularly rather than at equal intervals, so the pattern does not repeat periodically. Avoiding a regular period prevents the metallic, comb-filtered coloration and audible flutter that evenly spaced taps produce, yielding a smoother, more natural and diffuse result.','Evenly spaced echoes can sound metallic, like a ringing tube. A non-repeating tap pattern spaces the echoes unevenly. Because they never fall into a steady beat, the sound is smoother. It feels more like a real room.','It exists to make delays and early reflections sound natural and diffuse by breaking up the regular spacing that causes tonal coloration and flutter echo.','A designer or engineer chooses irregular tap times in a multitap delay or early-reflection stage to avoid ringing and build a convincing sense of space.','Delay technique',ARRAY['Multitap delay','Early reflections','Comb filtering','Diffusion','Flutter echo','Slapback delay']::text[],ARRAY['Spacing taps at equal intervals, which reintroduces the metallic comb-filter ringing the pattern is meant to avoid.','Using too few taps, so the result sounds like separate echoes rather than a smooth field.','Assuming any random spacing works; poorly chosen times can still cluster into audible periodicity.']::text[],ARRAY['Designing natural-sounding early reflections in a reverb algorithm.','Building a multitap delay that adds space without a ringing, tubular tone.','Avoiding flutter echo when placing several delay taps close together.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='455bfc23-00a7-5dc3-863a-bffcbeecec9e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Non-repeating tap pattern'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '455bfc23-00a7-5dc3-863a-bffcbeecec9e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='455bfc23-00a7-5dc3-863a-bffcbeecec9e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cbbd0abe-8bf6-52ce-926d-f5a6ea73d9b3','Output-ducked delay','A ducked-delay implementation in which the level reduction is applied to the delay''s output (return) stage, driven by a sidechain detector keyed from the dry source. While the source is present the returned echoes are attenuated, and they rise again in the gaps between phrases, keeping the delay from cluttering the dry signal.','A delay can bury the singer under echoes. Output-ducked delay turns the echoes down while the singer sings. It lets them rise in the gaps. The turning-down happens at the delay''s output.','It exists to keep delay repeats out of the way during active passages and let them bloom in the pauses, preserving clarity while still adding echo and depth.','An engineer places a compressor on the delay return, sidechained from the dry vocal, so the echoes duck under each phrase and swell in the spaces.','Delay technique',ARRAY['Ducked delay','Inverse ducked delay','Sidechain','Feedback delay','Pre-delay','Slapback delay']::text[],ARRAY['Setting release too fast, so echoes pop back up abruptly the instant a phrase ends.','Keying the ducker from the wet return instead of the dry source, which defeats the ducking.','Confusing it with inverse ducked delay, which raises the echoes during phrases instead of lowering them.']::text[],ARRAY['Keeping a vocal intelligible while still using a long, obvious delay.','Letting delay throws fill the gaps at the ends of vocal lines.','Adding rhythmic echo to a busy rap or lead line without masking the words.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cbbd0abe-8bf6-52ce-926d-f5a6ea73d9b3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Output-ducked delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cbbd0abe-8bf6-52ce-926d-f5a6ea73d9b3','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cbbd0abe-8bf6-52ce-926d-f5a6ea73d9b3' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c4d7361f-c92a-5833-89cb-1fe4d152fe37','Pitch-recursive reverb','A reverb in which one or more pitch shifters are placed in the feedback (regeneration) path, so that as the reverberant tail recirculates it is repeatedly transposed, typically upward by an octave. Each pass adds another shifted layer, building an ascending, harmonically evolving ''shimmer'' rather than a static decay.','In this reverb, the tail is pitch-shifted each time it loops back. Often it moves up an octave. Because it keeps recirculating, the pitched layers stack up. This creates a rising, glowing shimmer sound.','It exists to produce ethereal, evolving reverb textures—most famously the shimmer effect—by feeding a transposed copy of the tail back into the reverb so harmonics build over time.','An engineer sets a shimmer or pitch reverb''s feedback pitch to plus one octave and raises the pitch feedback so guitar or synth chords bloom into a rising, angelic wash.','Reverb technique',ARRAY['Modulated reverb','Feedback delay','Pitch shifting','Reverb time (RT60)','Diffusion','Layered reverb']::text[],ARRAY['UNSAFE: Raising pitch feedback near maximum can send the recirculating tail into runaway build-up and a sudden loud level spike; keep monitor levels moderate and lower the control-room volume before pushing high feedback, to protect hearing and speakers.','Expecting a natural room sound; the pitched feedback is an obvious special effect, not a realistic space.','Feeding it complex, dissonant chords, where the stacked octaves clash and sound muddy.']::text[],ARRAY['Creating the classic ambient shimmer wash on electric guitar.','Adding an ethereal, rising texture under a synth pad or vocal.','Building cinematic, evolving soundscapes from simple sustained notes.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c4d7361f-c92a-5833-89cb-1fe4d152fe37' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Pitch-recursive reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c4d7361f-c92a-5833-89cb-1fe4d152fe37','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c4d7361f-c92a-5833-89cb-1fe4d152fe37' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '745e18b4-3513-519b-8f6b-c4992224e1f0','Polymetric delay','A delay effect whose repeat timings are set so that two or more different metrical groupings sound at once against the song''s pulse, for example a repeat pattern implying one meter over a rhythm section in another. It is the delay-based application of polymeter, in which multiple meters share a common beat unit but have differing measure lengths, so their downbeats drift apart and periodically realign.','This is an echo effect timed to two beat groupings at once. One echo pattern feels like one time signature. The music sits in another. The patterns drift apart, then line back up.','It adds rhythmic complexity and forward motion by layering a contrasting metric feel over the source, so the repeats weave through the groove rather than simply doubling it.','A mix engineer sets tempo-synced delay times on an aux send so the repeats group into a different meter from the drums, creating an evolving polymetric pattern under a vocal or synth line.','Delay Technique',ARRAY['Polyrhythmic delay','Quintuplet delay','Tempo-synced delay','Regenerative delay','Dotted-eighth delay','Delay feedback']::text[],ARRAY['Confusing polymeter with polyrhythm: polymeter stacks different meters, while polyrhythm stacks different subdivisions of the same beat.','Setting the delay time by ear without tempo sync, so the intended metric grouping never lines up with the song.','Using too much feedback, which piles up repeats until the polymetric pattern turns to mush.']::text[],ARRAY['Programming a synth delay in electronic music so its repeats imply five beats over a four-beat drum pattern.','Adding a delay to a guitar arpeggio so the echoes group into a contrasting meter for a building section.','Sound-designing an evolving ambient bed where shifting metric layers hold the listener''s interest.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='745e18b4-3513-519b-8f6b-c4992224e1f0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Polymetric delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '745e18b4-3513-519b-8f6b-c4992224e1f0','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='745e18b4-3513-519b-8f6b-c4992224e1f0' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e79986e4-bc97-594d-a4ed-2d25771ff28c','Polyrhythmic delay','A delay effect whose repeat timings create a polyrhythm against the source, sounding two or more contrasting subdivisions of the same beat at once - most commonly a dotted-eighth repeat set against straight eighth or quarter notes to imply patterns such as three against two. Unlike polymeter, the beat is shared and only the divisions differ.','This echo is timed to clash gently with the beat''s normal divisions. A common trick sets the repeats to dotted eighth notes. The echoes and the rhythm make a rolling three-against-two feel.','It creates rhythmic interest and movement by weaving cross-rhythms through a part, filling the gaps between notes without changing what the musician actually played.','Engineers pick a tempo-synced value such as dotted-eighth on a vocal or guitar delay so the repeats fall between the main hits, producing the classic rhythmic delay heard across pop and rock mixes.','Delay Technique',ARRAY['Polymetric delay','Dotted-eighth delay','Quintuplet delay','Tempo-synced delay','Regenerative delay','Slapback delay']::text[],ARRAY['Confusing polyrhythm with polymeter: polyrhythm keeps one beat and layers different subdivisions over it.','Leaving the delay too loud, so the cross-rhythm competes with the lead instead of supporting it.','Not tempo-syncing the delay, so the intended three-against-two pattern drifts out of time.']::text[],ARRAY['Setting a dotted-eighth delay on a lead vocal to fill space in a sparse verse.','Adding a polyrhythmic guitar delay for a driving, rhythmic guitar texture.','Programming synth echoes that imply three against two over a four-on-the-floor beat.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e79986e4-bc97-594d-a4ed-2d25771ff28c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Polyrhythmic delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e79986e4-bc97-594d-a4ed-2d25771ff28c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e79986e4-bc97-594d-a4ed-2d25771ff28c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4dacff77-88fc-5968-afcb-3f89b287adbb','Prime-number delay spacing','A reverb and echo design practice in which the lengths of parallel or series delay lines are chosen to be mutually prime (sharing no common factors), so their echo trains do not coincide periodically. Introduced in Schroeder''s colorless-reverberation work, it spreads reflections more evenly and suppresses the resonant coloration and flutter that occur when delay lengths share common divisors.','Digital reverb is built from many short echo loops. If their lengths share common factors, echoes stack up and ring. Choosing lengths with no shared factors spreads the echoes out and keeps the sound smooth.','It raises echo density smoothly and avoids metallic ringing and comb-filter coloration, helping an artificial reverb sound like a natural space rather than a set of tuned resonances.','Reverb designers and plug-in builders pick prime or coprime sample-delay lengths for comb and allpass sections; technicians rarely set it directly but hear its effect as a smooth, uncolored tail.','Reverb Design',ARRAY['Reverb diffusion','Reverb density','Comb filter','Allpass filter','Schroeder reverberator','Feedback delay network']::text[],ARRAY['Assuming any prime numbers work, when the delays must also be spread across a suitable range to avoid a sparse or ringing tail.','Thinking prime spacing alone makes a reverb sound natural, ignoring diffusion, damping and modulation.','Confusing this technique with tempo-based delay timing, which has nothing to do with reducing coloration.']::text[],ARRAY['Designing a Schroeder or feedback-delay-network reverb algorithm in software.','Tuning comb-filter delay lengths to remove a metallic ring from an early digital reverb.','Teaching how classic digital reverbs achieve a dense, smooth tail.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4dacff77-88fc-5968-afcb-3f89b287adbb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Prime-number delay spacing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4dacff77-88fc-5968-afcb-3f89b287adbb','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4dacff77-88fc-5968-afcb-3f89b287adbb' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '01234ec8-5a5f-5299-8699-68917827280f','Printed reverse reverb','A reverse-reverb effect that has been rendered (bounced) to a permanent audio file rather than left on a live effect return. The reverb tail is produced by reversing a source, adding reverb, then reversing the result, so the tail swells up into the note; ''printing'' commits that processed audio to a track for playback and further editing.','Reverse reverb makes the echo swell up before a sound, like a breath in. You build it by flipping the audio, adding reverb, then flipping it back. ''Printed'' means you bounce it to a new audio file to keep.','Printing locks in the reverse-reverb swell so it plays back the same every time, frees up processing, and lets the engineer edit, time-align and trim the tail precisely.','An engineer reverses a vocal phrase, prints reverb onto it, reverses it back, then slides the swelling tail so it crescendos into the downbeat of a chorus or a snare hit.','Reverb Technique',ARRAY['Reverse reverb','Pre-delay','Reverb tail','Bounce (render)','Reverb attack','Reverb density']::text[],ARRAY['Bouncing before the reverb tail is fully captured, so the swell gets cut off when the audio is reversed.','Not accounting for the tail length, which leaves the swell mistimed against the downbeat.','Trying to do it non-destructively in real time, when the reverse step needs a committed audio file.']::text[],ARRAY['Creating a swelling vocal intro that rises into the first word of a chorus.','Building a backwards cymbal or snare swell leading into a drop in dance music.','Printing a reverse-reverb guitar chord as a transition between song sections.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='01234ec8-5a5f-5299-8699-68917827280f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Printed reverse reverb'),'[^a-z0-9]','','g'));
