INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4c66e209-b6a9-544a-b2fa-900e7abf97cf','Quintuplet delay','A tempo-synced delay whose repeat time equals one fifth of a beat or bar, placing echoes on a quintuplet grid - five evenly spaced repeats in the time a beat would normally divide into four. It applies the quintuplet, an irregular tuplet subdivision, to echo timing.','A quintuplet splits one beat into five equal parts instead of four. This delay times its echoes to that five-part grid. The repeats feel fast and slightly unusual against a normal beat.','It offers an uncommon rhythmic delay pattern that stands apart from the usual eighth or dotted-eighth echoes, adding tension and a distinctive, busy rhythmic texture.','A producer selects a quintuplet delay value in a tempo-synced plug-in to get a rippling, off-kilter echo on a synth, a vocal chop or a percussion hit.','Delay Technique',ARRAY['Tempo-synced delay','Polyrhythmic delay','Dotted-eighth delay','Triplet delay','Regenerative delay','Polymetric delay']::text[],ARRAY['Assuming a quintuplet divides the beat into four; it divides it into five.','Expecting it to sit neatly with the groove, when quintuplet timing intentionally feels against the grid.','Piling on feedback until the fast five-part repeats blur into noise.']::text[],ARRAY['Programming a rippling quintuplet echo on an electronic synth stab.','Adding an unusual rhythmic delay to a vocal chop in a modern pop production.','Designing a busy percussion echo that pushes against a straight beat.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4c66e209-b6a9-544a-b2fa-900e7abf97cf' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Quintuplet delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4c66e209-b6a9-544a-b2fa-900e7abf97cf','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4c66e209-b6a9-544a-b2fa-900e7abf97cf' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '294b800d-3238-5147-a471-7dda17bdfb7f','Random delay','A delay whose delay time is continuously varied by a random (noise-based) modulation source rather than a periodic LFO, producing small, unpredictable fluctuations in the timing and pitch of the repeats. The randomization de-correlates the echoes and, in reverbs, breaks up static, metallic resonances.','Most modulated delays wobble in a steady pattern. A random delay instead shifts its timing by tiny random amounts. This makes the echoes feel more natural and less like a fixed, ringing machine.','Random modulation exists to smear fixed resonances and avoid the static, metallic character of an unmodulated delay or reverb, imitating the subtle instability of real spaces and analog gear.','Engineers raise a random or spin/wander-style modulation control on a reverb or delay to thicken and slightly de-tune the tail, removing an unnatural ring without an obvious pitch wobble.','Delay Modulation',ARRAY['Modulated delay','Reverb diffusion','Spin and wander','Chorus','Reverb density','Regenerative delay']::text[],ARRAY['Adding too much random modulation, which makes pitched material sound out of tune.','Confusing random modulation with a regular LFO wobble; random modulation has no fixed rate.','Expecting it to fix timing problems, when it only changes tone and texture.']::text[],ARRAY['Smoothing a metallic digital reverb tail with subtle random modulation.','Slightly de-tuning delay repeats so they blend behind a lead vocal.','Emulating analog or tape-delay instability on a clean digital delay.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='294b800d-3238-5147-a471-7dda17bdfb7f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Random delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '294b800d-3238-5147-a471-7dda17bdfb7f','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='294b800d-3238-5147-a471-7dda17bdfb7f' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd44183dd-0f2d-589f-924a-daa81962fe91','Regeneration throw','A mix move in which a single word, phrase or hit is momentarily sent to a delay whose regeneration (feedback) is set high, so the thrown signal spawns a cascade of decaying repeats that trail off after the source stops. It combines a delay ''throw'' - a brief, automated send - with high feedback for a dramatic tail.','A throw sends just one word or hit into a delay for a moment. High regeneration means that echo repeats many times as it fades. The result is a trailing string of echoes on a single moment.','It spotlights a single moment and creates space or drama, letting one word or drum hit ring out in repeats without washing the whole part in delay.','An engineer automates a delay send up on the last word of a line while feedback is high, so that word throws a long, fading echo tail into the next section.','Delay Technique',ARRAY['Delay throw','Regenerative delay','Delay feedback','Aux send','Dub delay','Slapback delay']::text[],ARRAY['UNSAFE: Pushing regeneration to or beyond 100 percent can send the feedback into runaway self-oscillation and a sudden loud burst that risks hearing and monitor damage; keep feedback below unity and your hand on the fader.','Leaving the send open too long, so the throw smears into the following words instead of one moment.','Automating the send but forgetting to raise feedback, so the throw makes only one weak repeat.']::text[],ARRAY['Throwing a long echo tail off the last word of a rap or vocal line.','Sending a snare hit into a feeding-back delay for a dub-style transition.','Creating a dramatic trailing echo into a breakdown or drop.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d44183dd-0f2d-589f-924a-daa81962fe91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Regeneration throw'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd44183dd-0f2d-589f-924a-daa81962fe91','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d44183dd-0f2d-589f-924a-daa81962fe91' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e17928dd-23d9-5d29-9cf3-412d54940aa1','Regenerative delay','A delay in which a portion of the delayed output is fed back into the delay input, so each pass recirculates at reduced level to produce a series of successive, decaying repeats. The feedback (regeneration) amount sets how many repeats occur and how slowly they fade; at or above unity gain the loop self-oscillates.','A simple delay makes one echo. A regenerative delay feeds its echo back in, so it repeats again and again. Each repeat is quieter, so the echoes slowly fade away.','Feedback turns a single echo into a natural-sounding train of repeats, letting one control set the length and decay of the echo tail.','A technician sets the feedback (regeneration or repeats) control to choose how many echoes follow the sound, from a couple of slaps to a long, self-sustaining wash.','Delay Type',ARRAY['Delay feedback','Regeneration throw','Slapback delay','Tempo-synced delay','Dub delay','Reverb feedback loop']::text[],ARRAY['UNSAFE: Setting feedback to or above 100 percent causes runaway self-oscillation and a rapidly building loud signal that can damage hearing and loudspeakers; keep regeneration below unity and be ready to pull it back.','Confusing feedback (number of repeats) with delay mix (how loud the delay sits in the mix).','Using very high feedback on busy parts, so the repeats build into a muddy wash.']::text[],ARRAY['Dialing repeat count on a vocal delay from a single slap to a long trail.','Creating a dub-style self-feeding delay wash on a snare or effect.','Building an ambient guitar texture from long, slowly decaying repeats.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e17928dd-23d9-5d29-9cf3-412d54940aa1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Regenerative delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e17928dd-23d9-5d29-9cf3-412d54940aa1','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e17928dd-23d9-5d29-9cf3-412d54940aa1' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '04163bfd-fb33-573d-aae8-cb5b73eca26e','Reverb attack','The initial build-up phase of a reverb''s amplitude envelope - how quickly and with what contour the reverberant energy rises to its maximum after the direct sound - before the decay phase begins. In many reverbs the attack is short or near-instantaneous, but controls such as Shape and Spread let it build more gradually for a swelling onset.','A reverb''s sound has two stages: it builds up, then fades away. The attack is that build-up stage. A fast attack starts the tail at once. A slow attack lets it swell in gently.','Shaping the attack controls how a reverb enters, from an instant splash behind a transient to a slow swell, which affects how the reverb blends with and supports the dry sound.','An engineer lengthens the reverb attack (via Shape/Spread or an attack control) for a gentle, swelling pad or vocal ambience, or keeps it fast for a tight, immediate room on drums.','Reverb Parameter',ARRAY['Reverb decay time','Pre-delay','Early reflections','Reverb diffusion','Reverb density','Printed reverse reverb']::text[],ARRAY['Confusing reverb attack (how the tail builds up) with pre-delay (the gap before the tail starts).','Assuming every reverb has an adjustable attack, when many fix it as short or instantaneous.','Setting a slow attack on percussive material and losing the tight, immediate response the part needs.']::text[],ARRAY['Creating a slow-swelling reverb onset on a sustained synth pad.','Keeping a fast reverb attack on a snare for a tight, punchy room.','Shaping a gradual reverb build behind a held vocal note.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='04163bfd-fb33-573d-aae8-cb5b73eca26e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb attack'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '04163bfd-fb33-573d-aae8-cb5b73eca26e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='04163bfd-fb33-573d-aae8-cb5b73eca26e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9119659d-5730-530c-a2ce-3f8c7908b67f','Reverb damping','A reverb control that sets how quickly high (and sometimes low) frequencies decay relative to the mid-band, applying a frequency-dependent loss - typically a low-pass filter in the feedback path - so the tail grows progressively darker over time. It models the absorption of sound by air and room surfaces, which attenuates high frequencies faster than lows.','In a real room, echoes lose their bright, high sounds fastest. Reverb damping copies that. It makes the high frequencies fade quicker than the rest. More damping gives a darker, warmer, more distant tail.','Damping makes artificial reverb sound natural by imitating how air and soft surfaces soak up high frequencies, and it keeps a bright tail from clashing with or masking the mix.','An engineer increases high-frequency damping to tuck a vocal or snare reverb behind the dry sound, or reduces it for a bright, airy tail on strings and cymbals.','Reverb Parameter',ARRAY['Reverb decay time','High-frequency rolloff','Reverb diffusion','Reverb density','Absorption','Pre-delay']::text[],ARRAY['Confusing damping with decay time: damping shapes the tone of the tail, while decay time sets its length.','Over-damping until the reverb sounds dull and lifeless, losing air and depth.','Assuming damping only affects highs, when some reverbs also let you damp the low frequencies.']::text[],ARRAY['Darkening a long hall reverb so it sits under a lead vocal.','Simulating a carpeted, curtained room by damping the high frequencies heavily.','Stopping cymbal reverb from turning harsh by increasing high-frequency damping.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9119659d-5730-530c-a2ce-3f8c7908b67f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb damping'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '9119659d-5730-530c-a2ce-3f8c7908b67f','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9119659d-5730-530c-a2ce-3f8c7908b67f' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fcc76d01-0239-5bfc-94e4-5f4c67deaf94','Reverb density','The number of individual reflections (echoes) per unit time within a reverb tail - how tightly packed the echoes are. High density means many closely spaced reflections that fuse into a smooth, continuous wash; low density leaves audible, discrete echoes and a grainy or fluttery texture. Schroeder''s rule of thumb targets roughly 1,000 echoes per second or more for a smooth late reverb.','Density is how many echoes are packed into the reverb. High density means so many echoes that they blur into a smooth wash. Low density lets you hear separate, grainy echoes.','Density sets how smooth or grainy the tail sounds, letting the reverb range from a thin, fluttery early-digital character to a thick, seamless space.','An engineer raises density for a lush, smooth vocal or string reverb, or lowers it to keep individual reflections audible for a vintage or rhythmic effect.','Reverb Parameter',ARRAY['Reverb diffusion','Echo density','Reverb damping','Early reflections','Prime-number delay spacing','Reverb attack']::text[],ARRAY['Confusing density (how many echoes there are) with diffusion (how fast the echoes build up and smear).','Assuming low density is always a flaw, when it can give a useful vintage or rhythmic character.','Expecting density to change the length of the tail, which is set by the decay time instead.']::text[],ARRAY['Thickening a smooth vocal plate reverb by raising density.','Dialing lower density for a grainy, retro digital-reverb sound.','Diagnosing a thin, fluttery tail caused by too few reflections.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fcc76d01-0239-5bfc-94e4-5f4c67deaf94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb density'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fcc76d01-0239-5bfc-94e4-5f4c67deaf94','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fcc76d01-0239-5bfc-94e4-5f4c67deaf94' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cdb41a00-f37f-5a5d-9ae0-9a8c849441f7','Reverb diffusion','A reverb parameter that controls how quickly early reflections spread out and build into a dense tail, and how much incoming transients are smeared or softened. Low diffusion leaves sparse, distinct reflections that can sound grainy, fluttery or metallic; high diffusion, produced by allpass diffuser stages, yields a smooth, dense, lush tail. It models how cluttered surfaces break reflections into many scattered paths.','Diffusion controls how fast the echoes spread and blur together. Low diffusion leaves sharp, separate echoes that can sound metallic. High diffusion smears them into a smooth, thick tail. It copies how a cluttered room scatters sound.','Diffusion shapes the texture of the reverb, softening harsh transients and turning a set of discrete echoes into a natural, continuous space.','An engineer raises diffusion for smooth reverb on sustained sources like vocals and pads, and lowers it on percussion so the reflections stay defined and rhythmic.','Reverb Parameter',ARRAY['Reverb density','Allpass filter','Early reflections','Reverb damping','Prime-number delay spacing','Reverb attack']::text[],ARRAY['Confusing diffusion with density: diffusion is the rate of build-up and smearing, while density is how many echoes there are.','Using high diffusion on transient percussion, which can smear the attack and blur the groove.','Leaving diffusion very low and then blaming the algorithm for a metallic, fluttery tail.']::text[],ARRAY['Smoothing a vocal reverb by increasing diffusion to remove flutter.','Lowering diffusion on a drum reverb to keep the reflections tight and rhythmic.','Dialing diffusion back to expose early reflections for a slap or ambience effect.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cdb41a00-f37f-5a5d-9ae0-9a8c849441f7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb diffusion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'cdb41a00-f37f-5a5d-9ae0-9a8c849441f7','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cdb41a00-f37f-5a5d-9ae0-9a8c849441f7' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5d65adf6-f1ae-5b8e-974c-674354adcc71','Reverb feedback loop','The recirculating feedback path inside a reverb algorithm - for example the loop around a comb filter or the cross-coupled feedback matrix of a feedback delay network - that recycles delayed signal back into itself to sustain the decaying tail. The loop gain must stay below unity for the reverb to decay and remain stable; at or above unity the loop self-oscillates and the level runs away.','A reverb keeps its tail going by feeding its own delayed sound back into itself. That recycling path is the feedback loop. If it feeds back too strongly, the sound never dies and can build out of control.','The feedback loop stretches a few delays into a long, dense decay, so the reverb can sustain a tail far longer than its raw delay lines without needing endless separate delays.','Reverb designers set feedback gains below unity to control decay time and stability, while live and studio engineers watch for runaway build-up when reverb or delay returns are accidentally routed back into their own inputs.','Reverb Structure',ARRAY['Comb filter','Feedback delay network','Regenerative delay','Reverb decay time','Reverb density','Prime-number delay spacing']::text[],ARRAY['UNSAFE: Routing a reverb or delay return back into its own input, or setting internal feedback at or above unity, can cause runaway self-oscillation and a sudden loud burst that damages hearing and loudspeakers; keep loop gain below unity and mute before troubleshooting.','Confusing the internal DSP feedback loop with acoustic feedback between a microphone and a speaker.','Assuming more feedback simply means a longer tail, ignoring the instability and coloration it adds as it nears unity.']::text[],ARRAY['Designing a comb-filter or feedback-delay-network reverb algorithm.','Troubleshooting a runaway howl when an aux return is mistakenly fed back to its own send.','Explaining why an artificial reverb''s decay time depends on its internal feedback gain.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5d65adf6-f1ae-5b8e-974c-674354adcc71' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb feedback loop'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5d65adf6-f1ae-5b8e-974c-674354adcc71','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5d65adf6-f1ae-5b8e-974c-674354adcc71' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a25b31cb-2b73-5d79-bb8c-612f3f330f35','Reverb freeze','A processor function that sets the reverb decay time to infinite and, on most units, blocks further signal from entering the reverb network, so the existing reverberant tail is captured and sustained as a static pad or wash until the control is released.','Freeze catches the reverb tail and holds it. The sound keeps ringing like a held pad. On most units it stops new sound from getting in. You get a frozen wash until you switch it off.','It exists to turn a decaying reverb into a sustained pad or drone, letting an engineer hold ambience under a passage without re-triggering it.','An engineer assigns Freeze to a footswitch or an automation lane to hold a lush tail under a vocal or breakdown, then releases it to let the mix breathe.','Reverb parameter',ARRAY['Reverb hold','Reverb tail','Decay time (RT60)','Reverb regeneration','Infinite reverb']::text[],ARRAY['Freezing a tail that still holds the previous note or chord, so the held wash clashes with the new harmony.','Forgetting that many units block input while frozen, then wondering why newly played notes never join the tail.','UNSAFE: Soloing or boosting a sustained frozen wash on headphones or monitors at high level for long stretches; sustained exposure above about 85 dBA risks permanent hearing loss, so keep monitoring levels moderate and take breaks.']::text[],ARRAY['Holding an ambient pad under a spoken-word or vocal passage.','Creating a sustained drone transition between two song sections.','Film sound design, freezing room tone into an evolving texture.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a25b31cb-2b73-5d79-bb8c-612f3f330f35' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb freeze'),'[^a-z0-9]','','g'));
