SELECT 'b6d29445-7c11-5794-b925-415b39d34b35','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b6d29445-7c11-5794-b925-415b39d34b35' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'fce99224-64a1-5254-989a-8edc78c5c36e','Reverb swell','A technique in which the level of a reverb return, or the send feeding it, is automated to rise over time, so the reverberant field gradually blooms behind or ahead of a source, producing a crescendo of ambience rather than a fixed wet level.','A reverb swell is when the echo slowly gets louder over a few seconds. You automate the reverb volume to fade up. It makes a sound bloom and grow instead of staying flat.','It exists to add motion and drama to a static part, letting ambience build into a transition, downbeat, or emotional peak instead of sitting at a constant level.','An engineer draws a volume ramp on the reverb return under a held vocal note so the space grows into the chorus, then pulls it back for the verse.','Reverb technique',ARRAY['Reverse-envelope reverb','Reverb-into-delay','Reverb tail ducking','Pre-delay','Automation']::text[],ARRAY['Confusing a reverb swell (automated wet level rising) with a volume swell on the dry source','Swelling the reverb so late that it arrives after the moment it was meant to lift','Automating the send instead of the return, which changes character rather than just level, unless that is intended']::text[],ARRAY['Blooming ambience into the drop of an electronic track','Rising reverb under a sustained vocal note going into a chorus','Creating a cinematic riser under a film cue transition']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='fce99224-64a1-5254-989a-8edc78c5c36e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb swell'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'fce99224-64a1-5254-989a-8edc78c5c36e','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='fce99224-64a1-5254-989a-8edc78c5c36e' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0d43d8e0-c616-5356-985f-e4e0b7982a66','Reverb tail ducking','The application of dynamic gain reduction, typically sidechain compression keyed by the dry source, to a reverb return, so the reverb tail is attenuated while the source is present and allowed to rise in the gaps between phrases, preserving intelligibility without sacrificing ambience.','Reverb tail ducking turns the echo down while someone sings, then lets it swell up in the gaps. A sidechain listens to the dry voice and controls the reverb. This keeps words clear but still roomy.','It exists to reconcile a large, lush reverb with a clear, upfront source: the tail stays out of the way during words and fills the space between them.','A mix engineer sidechains a long vocal reverb to the lead vocal so the reverb ducks under each line and blooms in the pauses.','Reverb technique',ARRAY['Reverb tail expansion','Reverb swell','Sidechain compression','Ducking','Reverb tail equalization']::text[],ARRAY['Setting release too fast so the reverb pumps audibly instead of recovering smoothly','Keying the ducker from the wet return instead of the dry source, so it never opens fully','Over-ducking until the reverb disappears entirely, defeating the point of using it']::text[],ARRAY['Keeping a big vocal reverb from masking lyrics in a dense pop mix','Ducking snare reverb under a busy drum pattern for clarity','Letting a dialogue reverb breathe between lines in film post']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0d43d8e0-c616-5356-985f-e4e0b7982a66' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb tail ducking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0d43d8e0-c616-5356-985f-e4e0b7982a66','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0d43d8e0-c616-5356-985f-e4e0b7982a66' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '35901a97-5b05-56b5-9ddc-9753a001647a','Reverb tail equalization','Equalization applied specifically to a reverb''s output (the wet tail), most often high-passing to remove low-frequency buildup and low-passing or notching to tame harsh or sibilant resonances, so the ambience sits in the mix without masking the dry source or accumulating mud.','Reverb tail equalization means using tone controls on the echo itself. You usually cut the low rumble and soften the harsh highs. This keeps the reverb clear and stops it muddying the mix.','It exists to control the frequency footprint of reverb so the tail adds space without clouding the low end or adding harshness, letting a fuller wet level be used cleanly.','An engineer inserts an EQ after the reverb on the return, high-passing the low end and rolling off the extreme highs so the tail seats behind the vocal.','Reverb technique',ARRAY['Reverb tail ducking','Reverb tail expansion','Pre-delay','High-pass filter','Reverb stacking']::text[],ARRAY['Leaving the reverb full-range so low frequencies build into mud across a busy mix','Equalizing the send input and the return the same way and losing track of which shapes tone versus drive','Rolling off so much top that the reverb sounds dull and disconnected from the source']::text[],ARRAY['High-passing a hall reverb so it stops masking the bass','Taming sibilant reverb on a bright vocal with a low-pass or de-esser on the return','Darkening a reverb tail to sit an instrument further back in the mix']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='35901a97-5b05-56b5-9ddc-9753a001647a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb tail equalization'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '35901a97-5b05-56b5-9ddc-9753a001647a','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='35901a97-5b05-56b5-9ddc-9753a001647a' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '88964da5-8fd9-5417-a076-7b9147a0091f','Reverb tail expansion','The application of a dynamics expander to a reverb return so the tail''s level is controlled by its own dynamics, typically downward expansion that attenuates the decay once it falls below a set threshold, used to tame reverb wash and increase contrast between the loud onset and the quiet tail as a gentler alternative to hard gating.','Reverb tail expansion uses an expander on the echo. It turns the quiet part of the tail down further. This makes the reverb fade cleaner and keeps quiet gaps free of wash. It works like a softer gate.','It exists to tame the low-level wash of a reverb decay without the abrupt cutoff of a gate, tightening the tail and improving clarity in the gaps.','An engineer places a downward expander after a long reverb so the tail recedes during pauses but stays lush under sustained notes.','Reverb technique',ARRAY['Reverb tail ducking','Gated reverb','Reverb tail equalization','Downward expansion','Noise gate']::text[],ARRAY['Confusing an expander with a gate; expansion is gradual, gating is an abrupt cut','Setting the threshold so high that the whole tail is chopped, sounding gated by accident','Using fast attack and release settings that make the tail chatter or pump']::text[],ARRAY['Cleaning up the low-level wash of a long hall reverb between vocal phrases','Tightening a drum reverb tail without the hard cutoff of a gate','Reducing reverb buildup in quiet verse sections']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='88964da5-8fd9-5417-a076-7b9147a0091f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb tail expansion'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '88964da5-8fd9-5417-a076-7b9147a0091f','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='88964da5-8fd9-5417-a076-7b9147a0091f' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8ee0729e-5834-56f9-bf57-8cffa1fef071','Reverb wander','The perceptible drift or movement of a reverb tail''s pitch or spatial character over time, produced when the reverberator modulates its internal delay-line lengths; the modulation smears comb-filter resonances to reduce metallic ringing but, at higher depths, is heard as a wandering, chorused, or detuned tail.','Reverb wander is a slow, drifting movement in the reverb tail. The echo seems to shift or waver in pitch. It comes from the reverb gently changing its own timing. A little smooths the sound; a lot makes it feel unstable.','Internal modulation exists to break up the fixed resonances (comb filtering) that make simple reverbs sound metallic, so the resulting gentle wander makes the tail smoother and more natural, or intentionally lush and moving.','An engineer raises the modulation depth on a hall reverb to remove a ringing tone from a piano tail, accepting a little pitch wander as it smooths out.','Reverb technique',ARRAY['Comb filtering','Modulation','Chorus','Reverb tail equalization','Pre-delay','Reverb spin']::text[],ARRAY['Cranking modulation depth so high that the tail sounds seasick or out of tune on sustained pitched material','Assuming all reverb wander is a defect, when mild modulation is deliberately used to smooth the tail','Blaming the reverb for pitch drift that is actually chorus or a detuned source']::text[],ARRAY['Smoothing a metallic piano reverb tail with subtle modulation','Adding lush movement to a pad or ambient texture','Diagnosing an unwanted warble in a reverb tail on sustained vocals']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8ee0729e-5834-56f9-bf57-8cffa1fef071' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb wander'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8ee0729e-5834-56f9-bf57-8cffa1fef071','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8ee0729e-5834-56f9-bf57-8cffa1fef071' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd13d9496-b105-5f5c-aba8-419770752e59','Reverb-into-delay','A serial routing in which a reverb is placed before a delay, so the delay line repeats an already reverberant signal; each rhythmic echo carries a full reverb tail, producing dense, ambient, and sometimes washed-out repeats rather than distinct dry taps.','Reverb-into-delay means the sound hits the reverb first, then the delay. So each echo repeat already has reverb on it. The repeats sound soft and washed instead of sharp. It builds a thick, dreamy space.','It exists to create atmospheric, blurred echoes where every repeat is diffuse, useful for ambient and cinematic textures; it is the opposite emphasis from delay-into-reverb, which keeps taps distinct before smearing them.','A producer routes a synth through a plate reverb into a tempo-synced delay so each echo is a soft ambient bloom rather than a clear repeat.','Signal routing',ARRAY['Serial reverb','Delay-into-reverb','Reverb stacking','Pre-delay','Feedback']::text[],ARRAY['Expecting distinct echoes; reverb-first blurs each repeat, unlike delay-into-reverb','Letting delay feedback stack reverberant repeats until the mix turns to mush','Placing them in the wrong order and wondering why the result sounds different than intended']::text[],ARRAY['Building ambient washes on a synth pad','Creating dreamy, blurred vocal throws in a downtempo track','Designing cinematic transition textures from a single hit']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d13d9496-b105-5f5c-aba8-419770752e59' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverb-into-delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd13d9496-b105-5f5c-aba8-419770752e59','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d13d9496-b105-5f5c-aba8-419770752e59' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '439758eb-0e0a-5baa-b802-6fba07e419c1','Reverse-envelope reverb','A reverb effect whose amplitude envelope is reversed so the reverberant energy rises from silence to a peak and then stops abruptly, rather than decaying naturally; when time-aligned before a source it appears to swell up into the note, an anticipatory effect often called reverse reverb or pre-verb.','Reverse-envelope reverb makes the echo grow louder and then stop, instead of fading away. Placed before a word, it sounds like the reverb pulls into the note. It gives an eerie backwards swell that a real room cannot make.','It exists to create a dramatic, unnatural rise into a sound, an attention-grabbing intro or transition effect, by inverting the normal decay so ambience anticipates rather than follows the source.','An engineer time-aligns a reverse-envelope reverb ahead of a vocal line''s first word so the space swells up and cuts off exactly as the word lands.','Reverb technique',ARRAY['Reverb swell','Gated reverb','Pre-delay','Reverb-into-delay','Reverb tail expansion']::text[],ARRAY['Confusing the built-in reverse-envelope preset with true reversed-audio reverb, which sounds different','Failing to time-align the swell so its peak lands on the source, breaking the illusion','Overusing it until every phrase has a dramatic pre-verb and the effect loses impact']::text[],ARRAY['Swelling into the first word of a vocal in an intro','Creating a rising transition before a downbeat','Building suspense before a sound-design hit in film']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='439758eb-0e0a-5baa-b802-6fba07e419c1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Reverse-envelope reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
