WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='439758eb-0e0a-5baa-b802-6fba07e419c1' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '92c268a7-3953-5d1c-bbf6-27d62c9ec7ab','Runaway feedback','A self-sustaining acoustic feedback condition in which the loop gain of a sound-reinforcement system reaches or exceeds unity (0 dB), so a re-circulating tone grows in level with each pass through the microphone-amplifier-loudspeaker loop until limited by clipping, compression, or component failure; the characteristic rising howl or squeal of an out-of-control PA system.','Runaway feedback is the loud howl that grows and grows in a sound system. It happens when the mic keeps picking up its own speaker. Each loop makes it louder. Left alone, it can hurt ears and blow speakers.','The term names a failure mode, not a tool: understanding it exists so technicians recognise the onset of feedback and cut gain before it damages hearing or equipment.','A live engineer who hears a tone begin to build pulls the offending channel or master fader and notches the frequency before it escalates into a full howl.','System safety',ARRAY['Self-oscillating delay','Loop gain','Gain before feedback','Ring out','Notch filter']::text[],ARRAY['UNSAFE: Pushing master gain past the feedback threshold to chase level, risking a sudden high-SPL howl that can damage hearing; OSHA limits 8-hour exposure to 90 dBA and NIOSH recommends 85 dBA','UNSAFE: Running a system with no limiter or loudspeaker protection, so a runaway howl can drive drivers to destruction','Ringing out a room but then adding gain or moving a mic, which re-opens the feedback path','Notching feedback with EQ while ignoring that the root cause is excessive loop gain']::text[],ARRAY['A vocal mic aimed at a monitor wedge begins to squeal as the fader is raised','A handheld mic carried in front of the main speakers erupts into a howl','Gain-staging a new PA and finding the feedback threshold during soundcheck']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='92c268a7-3953-5d1c-bbf6-27d62c9ec7ab' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Runaway feedback'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '92c268a7-3953-5d1c-bbf6-27d62c9ec7ab','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='92c268a7-3953-5d1c-bbf6-27d62c9ec7ab' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8a7c67a3-95e6-586d-bff3-27e8ab61419d','Self-oscillating delay','A delay operated with its feedback (regeneration) control at or above unity gain, so the repeats no longer decay but sustain or build indefinitely, causing the delay line to oscillate and generate a continuous drone or swelling texture from a single input; a deliberately used but potentially uncontrolled feedback condition.','A self-oscillating delay happens when the echo feeds back so strongly it never dies out. The repeats keep going or grow louder on their own. Musicians use it to make drones and swells. Pushed too far, it can get very loud fast.','It exists as a creative sound-design tool, turning an echo into a sustaining oscillator for drones, risers, and dub-style washes by exploiting feedback at unity, while demanding care because the level can escalate.','A dub or ambient engineer rides the feedback knob up until the delay sustains, then rolls it back to tame the build, often filtering the loop to shape the tone.','Delay technique',ARRAY['Runaway feedback','Feedback','Regeneration','Loop gain','Dub delay']::text[],ARRAY['UNSAFE: Cranking feedback into self-oscillation on a loud monitoring or PA system, where the runaway build can spike to hearing-damaging SPL; keep monitoring within OSHA/NIOSH exposure limits and keep a hand on the level','Assuming feedback below unity will self-oscillate; it only sustains at or above unity gain','Leaving self-oscillation running unfiltered so it climbs into harsh, potentially speaker-stressing levels','Confusing musical self-oscillation with accidental acoustic feedback, which is a fault to fix']::text[],ARRAY['Creating a sustaining drone from a single guitar note in ambient music','Dub mixing where the delay is pushed to build and swell','Sound-design risers made by ramping delay feedback into oscillation']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8a7c67a3-95e6-586d-bff3-27e8ab61419d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Self-oscillating delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8a7c67a3-95e6-586d-bff3-27e8ab61419d','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8a7c67a3-95e6-586d-bff3-27e8ab61419d' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '23a7b2c1-0e4e-5093-b077-d21fad4e131a','Septuplet delay','A tempo-synced delay whose time is set to a septuplet subdivision, seven equal divisions of a rhythmic unit such as a beat or a bar, so the repeats fall on an unusual seven-in-the-space grid, producing a fast, polyrhythmic echo that sits against the underlying meter.','A septuplet delay sets the echo to seven even repeats inside one beat or bar. Most delays use two, three, or four steps. Seven creates an unusual, rolling rhythm that pushes against the main groove.','It exists to create rhythmically complex, off-grid echo patterns, a polyrhythmic texture that a standard eighth, triplet, or dotted delay cannot produce, adding tension and movement.','A producer syncs a delay to a septuplet division on a synth stab so the repeats ripple across the bar in seven, creating a rolling polyrhythm.','Delay technique',ARRAY['Dotted delay','Triplet delay','Tempo sync','Ping-pong delay','Slapback delay']::text[],ARRAY['Assuming any tempo-sync delay is on a normal grid; septuplet timing deliberately sits off the usual divisions','Miscalculating the delay time by treating seven-in-a-beat as seven-in-a-bar, or vice versa','Using heavy feedback on a septuplet delay until the dense repeats smear into noise']::text[],ARRAY['Adding polyrhythmic movement to an electronic synth line','Creating a rolling echo texture on a percussive hit','Sound design where an off-grid echo builds rhythmic tension']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='23a7b2c1-0e4e-5093-b077-d21fad4e131a' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Septuplet delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '23a7b2c1-0e4e-5093-b077-d21fad4e131a','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='23a7b2c1-0e4e-5093-b077-d21fad4e131a' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a09a1c83-e80b-530a-8f78-572bf28ad65b','Serial reverb','A configuration in which one reverb feeds into another in series rather than in parallel, so the second reverb processes the output of the first; commonly a small early-reflection or room reverb feeding a larger hall or tail reverb, layering a close space inside a larger one for greater realism and depth.','Serial reverb chains one reverb into another. The sound goes through the first reverb, then straight into the second. Often a small room feeds a big hall. This stacks a near space inside a larger one for a deeper sound.','It exists to build a coherent sense of depth, placing early reflections from a room reverb inside the tail of a hall, so sources sound as if they share one believable layered acoustic environment; it is a staple of orchestral and film mixing.','A film composer routes each section through a short early-reflection reverb, then sends that into a single long hall, so the whole orchestra sits in one convincing space.','Reverb technique',ARRAY['Reverb stacking','Short-long reverb layering','Early reflections','Pre-delay','Parallel reverb']::text[],ARRAY['Confusing serial (one feeds the next) with parallel (both fed from the source) routing','Feeding a long reverb into another long reverb, smearing everything into an indistinct wash','Forgetting that the first reverb''s tone colours everything the second reverb then processes']::text[],ARRAY['Placing an orchestra in a room-inside-a-hall for film scoring','Feeding an early-reflection room into a plate for vocal depth','Building a layered ambient space on a synth pad']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a09a1c83-e80b-530a-8f78-572bf28ad65b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Serial reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a09a1c83-e80b-530a-8f78-572bf28ad65b','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a09a1c83-e80b-530a-8f78-572bf28ad65b' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9bea5f20-765e-5fd4-b82e-b491e08a2d9b','Short-long reverb layering','A layering technique using two reverbs in parallel, one short (a room or early-reflection reverb for immediate size and definition) and one long (a hall or plate for a sustained tail), each blended and shaped independently, so a source gains both close-up presence and extended decay without one compromising the other.','Short-long reverb layering uses two reverbs together. One is short and gives quick room detail. The other is long and adds a big, slow tail. Mixing both gives a sound close-up clarity and a long echo at once.','It exists to separate the two jobs of reverb, defining nearby space and providing long sustain, so each can be tuned on its own; this gives depth and size without the muddiness of one reverb trying to do both.','An engineer blends a short room reverb for body with a long hall for tail on a vocal, high-passing and level-matching each so the voice feels both present and spacious.','Reverb technique',ARRAY['Reverb stacking','Serial reverb','Early reflections','Pre-delay','Reverb tail equalization']::text[],ARRAY['Letting the long reverb dominate so the short reverb''s clarity is lost','Not high-passing both layers, so combined low-frequency energy muddies the mix','Assuming the two must run in series; layering here means parallel, blended independently']::text[],ARRAY['Giving lead vocals both presence and a long tail','Layering a tight room and a long hall on a snare','Creating depth on an orchestral submix']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9bea5f20-765e-5fd4-b82e-b491e08a2d9b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Short-long reverb layering'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
