WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9bea5f20-765e-5fd4-b82e-b491e08a2d9b' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b9822100-8ab5-5cc0-a0fe-a5796b4e11f4','Single-tap delay','A delay configuration that produces a single delayed copy (one "tap") of the input, giving exactly one distinct repeat at a fixed delay time. With feedback set to zero it yields one echo; it is the simplest delay topology, in contrast to multi-tap delays that read several output points from the delay buffer.','A single-tap delay makes just one echo of a sound. You hear the sound, then one repeat, and that is all. It is the simplest kind of delay effect.','It adds one clean, controllable repeat to a signal, used to thicken or place a sound in time without the density or clutter of multiple repeats.','An engineer sets one delay time and zero feedback to place a single slap or repeat behind a vocal or guitar, often timed to the track.','Delay type',ARRAY['Multi-tap delay','Slapback','Feedback','Tempo-Synchronized Delay','Delay time']::text[],ARRAY['Confusing a single-tap delay with feedback; one tap gives one repeat, while feedback re-circulates it into many.','Assuming a single-tap delay cannot be rhythmic; a single tempo-synced tap still lands on a musical subdivision.','UNSAFE: Cranking delay feedback near maximum to test the effect, which can build a runaway signal and expose you and monitors to sudden damaging levels.']::text[],ARRAY['Adding one short slap behind a lead vocal to thicken it without obvious echo.','Placing a single quarter-note repeat on a guitar riff for a simple rhythmic bounce.','Using one timed repeat as a send effect to widen a mono source.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b9822100-8ab5-5cc0-a0fe-a5796b4e11f4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Single-tap delay'),'[^a-z0-9]','','g'));
