SELECT 'b9822100-8ab5-5cc0-a0fe-a5796b4e11f4','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b9822100-8ab5-5cc0-a0fe-a5796b4e11f4' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '00912f6a-9dbe-576c-8b56-6d305c72b575','Slurred delay','A delay treatment in which the individual repeats lose their sharp, discrete attacks and blur together into a smeared, indistinct wash rather than clearly separated echoes. It arises from heavy delay-line modulation, diffusion, filtering, or closely overlapping short delay times that fuse the taps into a continuous texture.','A slurred delay smears its echoes so they blur together. Instead of clear, separate repeats, you hear a soft wash. It is like echoes melting into each other.','It exists to turn crisp, rhythmic repeats into an atmospheric, reverb-like texture, useful when the goal is mood and space rather than audible echo timing.','An engineer shortens the delay time, adds modulation or diffusion, and rolls off highs so the repeats smear into a pad-like ambience behind a part.','Delay technique',ARRAY['Modulation','Diffusion','Feedback','Tap density','Multi-tap delay','Reverb']::text[],ARRAY['Treating slur as a defect; here the blurring of repeats is the intended, musical result.','Adding so much feedback and modulation that the smeared wash masks the dry part and muddies the mix.','Expecting a slurred delay to keep tight rhythmic timing, when its purpose is to dissolve that timing into texture.']::text[],ARRAY['Turning a rhythmic delay into an ambient wash beneath a sparse vocal.','Smearing short modulated repeats on a synth to create dreamy, blurred movement.','Softening a delay''s separate echoes into a reverb-like bed for a cinematic pad.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='00912f6a-9dbe-576c-8b56-6d305c72b575' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Slurred delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '00912f6a-9dbe-576c-8b56-6d305c72b575','415df21a-f4ef-4337-84b3-c847231c6d62',true
