INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '87f5a181-998d-5c29-8d1d-a2891a30caa3','Spillover','A feature that lets the wet tail of a delay or reverb continue to ring and decay naturally across a preset change or bypass, rather than being cut off abruptly. The already-generated repeats or reverb tail "spill" into the next state while new processing begins, giving a seamless transition.','Spillover lets echoes or reverb keep ringing when you switch settings. The old tail fades out on its own instead of cutting off. It makes changes sound smooth, not sudden.','It exists so that switching patches or bypassing an effect does not chop off a musical tail, preserving natural decay during live performance and mixing.','A guitarist enables spillover on a delay or reverb pedal so a held repeat rings out while they step to the next preset for the following section.','Effect behavior',ARRAY['Feedback','Decay time','Reverb tail','True bypass','Delay time']::text[],ARRAY['Expecting spillover to work instantly; some units require the current preset to be active for a few seconds before enough buffer exists to spill.','Assuming spillover carries the tail across every possible change, when it usually only works between compatible preset or bypass states.','Confusing spillover with true bypass; spillover manages existing tails, while bypass routes the dry signal around the effect.']::text[],ARRAY['Switching delay presets between song sections without the previous echoes cutting off.','Bypassing a reverb at the end of a phrase while its tail decays naturally.','Changing patches live on a multi-effects unit so repeats ring through the transition.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='87f5a181-998d-5c29-8d1d-a2891a30caa3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spillover'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '87f5a181-998d-5c29-8d1d-a2891a30caa3','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='87f5a181-998d-5c29-8d1d-a2891a30caa3' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a1733c08-3b27-501c-892c-73caca2dbb59','Split early/late processing','A reverb design approach that treats the early reflections and the late reverberant tail as two separate stages, each with its own level, timing, and tonal controls. Splitting them lets the initial discrete reflections and the dense decaying tail be shaped and balanced independently before being recombined.','Reverb has two parts: early bounces and a longer tail. Split processing shapes these two parts on their own. You can change one part without changing the other.','It exists because early reflections define perceived size and distance while the late tail sets decay and density, so controlling each separately gives precise, natural-sounding spaces.','A mixer raises early reflections for presence and pulls back the late tail''s level or decay so a vocal sits in a room without drowning in wash.','Reverb technique',ARRAY['Early reflections','Reverb tail','Pre-delay','Decay time (RT60)','Diffusion']::text[],ARRAY['Ignoring early reflections and adjusting only the tail, losing the cues that convey room size and distance.','Setting the two stages to clash, for example bright early reflections against a dull tail, which sounds unnatural.','Assuming every reverb offers this split; many simpler algorithms bundle early and late together with no separate controls.']::text[],ARRAY['Boosting early reflections to bring a vocal forward while keeping the tail short and quiet.','Designing a convincing hall by tuning reflection pattern separately from decay length.','Adding early reflections for space on a dry drum while limiting late reverb to avoid mud.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a1733c08-3b27-501c-892c-73caca2dbb59' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Split early/late processing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a1733c08-3b27-501c-892c-73caca2dbb59','415df21a-f4ef-4337-84b3-c847231c6d62',true
