INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '699c3532-a58d-58eb-8838-24d3c9276882','Stereo offset delay','A stereo delay technique that applies slightly different delay times to the left and right channels, so each side repeats at a marginally different moment. The small inter-channel time difference broadens the stereo image and adds width without producing an obviously separate echo.','This delay uses slightly different times for the left and right sides. The small gap makes a sound feel wider. Your ears read the two sides as a bigger stereo picture.','It exists to widen a mono or narrow source by exploiting the ear''s use of tiny left-right timing differences to judge spatial spread.','An engineer sets the right channel a few milliseconds longer than the left on a vocal or synth send to spread it wide across the speakers.','Stereo delay',ARRAY['Haas effect','Ping-pong delay','Stereo width','Delay time','Slapback']::text[],ARRAY['Using offsets so large that the two sides are heard as separate echoes instead of one wide sound.','Ignoring mono compatibility; large offsets can cause comb filtering and level loss when the mix is summed to mono.','Confusing stereo offset with ping-pong; offset shifts both sides at once, while ping-pong bounces repeats between channels.']::text[],ARRAY['Widening a lead vocal by delaying one channel a few milliseconds more than the other.','Spreading a mono synth across the stereo field on a background pad.','Adding subtle width to a doubled guitar without an audible echo.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='699c3532-a58d-58eb-8838-24d3c9276882' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stereo offset delay'),'[^a-z0-9]','','g'));
