INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '690c16c8-0b56-583f-84d4-fc7a6a4cece8','Swing delay','A tempo-based delay whose repeats are given a swing or shuffle feel by shifting alternate taps slightly off the straight grid, so pairs of subdivisions play long-short rather than evenly. It lets echoes lock to a groove that swings instead of sitting on rigid straight timing.','A swing delay pushes some echoes a little late on purpose. This gives the repeats a bouncy, shuffled groove. It helps the delay match a song that swings.','It exists so delay repeats sit naturally in grooves that are not straight, matching the swing of the performance instead of fighting it.','An engineer dials a swing or groove amount on a tempo-synced delay so eighth-note repeats shuffle in time with a swung drum track.','Delay technique',ARRAY['Tempo-Synchronized Delay','Tap pattern','Groove','Dotted eighth delay','Delay time']::text[],ARRAY['Applying swing to a straight track, which makes the repeats fight the rhythm and feel sloppy.','Matching the wrong swing amount so the delay shuffles differently from the song''s own groove.','Assuming every delay offers swing; many only provide straight note divisions with no groove control.']::text[],ARRAY['Shuffling eighth-note vocal repeats to match a swung hip-hop or jazz groove.','Adding a swung delay to a guitar so its echoes bounce with the drums.','Locking a synth delay to the track''s shuffle so repeats sit in the pocket.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='690c16c8-0b56-583f-84d4-fc7a6a4cece8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Swing delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '690c16c8-0b56-583f-84d4-fc7a6a4cece8','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='690c16c8-0b56-583f-84d4-fc7a6a4cece8' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '2e4da2c2-74e9-5bda-973e-d5ca225fbb98','Tap density','In a multi-tap delay, the number of taps (delayed outputs) concentrated within a given span of time. High tap density packs many closely spaced repeats together, blending them toward a continuous, reverb-like texture, while low density leaves sparse, distinct echoes.','Tap density is how many echoes, or taps, happen in a set time. Many taps packed close make a thick, busy sound. Fewer taps sound open and clear.','It exists to control how smooth or discrete a multi-tap effect sounds, letting a delay range from clear rhythmic repeats to a dense, ambient wash.','An engineer adds more taps in a short window to build a thick reverb-like tail, or thins them out for a few clean, countable echoes.','Multi-tap parameter',ARRAY['Multi-tap delay','Tap spacing','Tap pattern','Diffusion','Slurred delay','Reverb']::text[],ARRAY['Piling on taps until the density masks the dry signal and the effect turns to mush.','Confusing tap density with feedback; density is how many taps exist, while feedback recirculates them.','Expecting high density to stay rhythmic, when closely packed taps fuse into texture rather than clear beats.']::text[],ARRAY['Increasing tap density to make a multi-tap delay approximate a reverb tail.','Reducing density to a few discrete echoes for a clear rhythmic pattern.','Building a thick ambient bed under a sustained pad with many closely spaced taps.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='2e4da2c2-74e9-5bda-973e-d5ca225fbb98' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tap density'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '2e4da2c2-74e9-5bda-973e-d5ca225fbb98','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='2e4da2c2-74e9-5bda-973e-d5ca225fbb98' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c04923fa-12c2-54e8-9f34-d092821f9ce5','Tap pattern','The overall arrangement of taps in a multi-tap delay: when each tap occurs, and often its level and stereo placement. The pattern defines the rhythmic and spatial shape of the repeats, from evenly spaced grids to irregular or panned sequences.','A tap pattern is the layout of a delay''s echoes. It sets when each echo lands and where it sits left or right. Different patterns create different rhythms and shapes.','It exists to let a designer sculpt the rhythm and spatial movement of the repeats, turning a plain delay into a musical or textural pattern.','An engineer places taps on specific subdivisions and pans them alternately left and right to build a bouncing rhythmic figure behind a part.','Multi-tap parameter',ARRAY['Multi-tap delay','Tap spacing','Tap density','Ping-pong delay','Tempo-Synchronized Delay']::text[],ARRAY['Building a tap pattern that ignores the song tempo, so the repeats clash with the beat.','Overcrowding the pattern with panned taps until the stereo image becomes confusing.','Confusing the pattern (where taps sit) with density (how many taps fall in a span of time).']::text[],ARRAY['Programming a left-right tap pattern to create a rhythmic bounce on a synth.','Designing an irregular tap layout for an unusual echo groove on a vocal.','Setting a tempo-locked pattern so repeats reinforce the drum rhythm.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c04923fa-12c2-54e8-9f34-d092821f9ce5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tap pattern'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
