INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cf69d710-6def-55ea-bf5c-4a57719b0403','Tap spacing','The time interval between consecutive taps in a multi-tap delay. Wide spacing yields clearly separated echoes, while narrow spacing packs the taps close together so they blur toward a continuous texture; spacing may be even or deliberately varied.','Tap spacing is the time gap between one echo and the next. Wide gaps give clear, separate repeats. Tight gaps blur the echoes into a smoother texture.','It exists to control the rhythm and smoothness of a multi-tap delay, setting whether repeats read as distinct hits or fuse into a wash.','An engineer widens tap spacing for a clear dotted rhythm, or tightens it so the taps merge into a dense, ambient tail.','Multi-tap parameter',ARRAY['Multi-tap delay','Tap density','Tap pattern','Delay time','Slurred delay']::text[],ARRAY['Assuming equal spacing is always required; uneven spacing is often what creates a musical groove.','Spacing taps so tightly they comb-filter and thin the tone instead of thickening it.','Confusing spacing (gap between taps) with density (how many taps occupy a time span).']::text[],ARRAY['Setting wide tap spacing for a clear, countable rhythmic delay.','Tightening spacing so taps merge into a reverb-like smear.','Varying spacing across taps to create an evolving, non-repeating echo figure.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cf69d710-6def-55ea-bf5c-4a57719b0403' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tap spacing'),'[^a-z0-9]','','g'));
