SELECT 'cf69d710-6def-55ea-bf5c-4a57719b0403','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cf69d710-6def-55ea-bf5c-4a57719b0403' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd9141b5a-76a4-519e-b548-511ab427e54c','Tempo-Synchronized Delay','A delay whose delay time is locked to the song''s tempo and set in musical note values (such as quarter, eighth, dotted, or triplet) rather than a fixed time in milliseconds. As tempo changes, the delay time tracks it so repeats always land on the musical grid; the millisecond value follows the relation ms equals sixty thousand divided by beats per minute for a quarter note.','This delay locks its timing to the song''s tempo. The echoes land on the beat, like quarter or eighth notes. So the delay stays in time as the music plays.','It exists so echoes reinforce the rhythm instead of clashing with it, keeping repeats musically aligned even when the tempo changes.','An engineer selects a note value like a dotted eighth and the delay follows the project tempo, so vocal or guitar repeats sit on the beat.','Delay timing',ARRAY['Tempo-relative delay','Dotted eighth delay','Delay time','Swing delay','Beats per minute']::text[],ARRAY['Forgetting to update the sync when the project tempo changes on a delay set in fixed milliseconds.','Choosing a note value that clutters the mix, such as straight eighths on an already busy part.','Assuming host sync is exact when a delay is not receiving reliable tempo information from the DAW.']::text[],ARRAY['Setting a dotted-eighth delay on a lead guitar so repeats lock to the track.','Syncing a vocal throw to quarter notes so it stays in time at any tempo.','Keeping a synth delay on the grid while the arrangement changes tempo.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d9141b5a-76a4-519e-b548-511ab427e54c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tempo-Synchronized Delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'd9141b5a-76a4-519e-b548-511ab427e54c','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='d9141b5a-76a4-519e-b548-511ab427e54c' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c8e7e1ab-f09e-5ccb-aa9a-14d51dd98620','Tempo-relative delay','A delay whose time is specified relative to the musical tempo as a note value (for example an eighth or dotted-quarter) rather than as an absolute duration, so the effective delay time scales proportionally with the tempo. It is the note-value expression of tempo synchronization, keeping repeats aligned to the beat across tempo changes.','A tempo-relative delay is set as a note value. You choose something like an eighth note. The delay time then follows the song''s tempo by itself.','It exists so a delay stays musically in time by being defined in beats rather than in a fixed duration, adapting automatically as tempo changes.','An engineer picks a note-value setting so the same patch stays on-beat across songs at different tempos without re-typing millisecond values.','Delay timing',ARRAY['Tempo-Synchronized Delay','Tempo-synchronized predelay','Delay time','Dotted eighth delay','Beats per minute']::text[],ARRAY['Treating a note-value setting as a fixed time, then wondering why repeats shift when the tempo changes.','Picking a subdivision that fights the groove, like triplets over a straight feel.','Assuming the host tempo is passed correctly when the delay is actually running free.']::text[],ARRAY['Choosing an eighth-note delay so one preset works across multiple songs at different tempos.','Keeping guitar repeats on-beat when a live set changes tempo between numbers.','Setting a delay in note values so it re-syncs automatically after a tempo edit.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c8e7e1ab-f09e-5ccb-aa9a-14d51dd98620' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tempo-relative delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c8e7e1ab-f09e-5ccb-aa9a-14d51dd98620','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='c8e7e1ab-f09e-5ccb-aa9a-14d51dd98620' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5409adc1-c994-5c81-910c-c3e6800aedbd','Tempo-synchronized predelay','A reverb pre-delay whose gap between the dry sound and the onset of the reverb is locked to the song''s tempo and set as a note value rather than a fixed time. Timing the pre-delay to a musical subdivision keeps the reverb''s start rhythmically aligned with the track.','Predelay is a short gap before a reverb starts. Here that gap is locked to the song''s tempo. So the reverb begins in time with the beat.','It exists to keep a reverb''s onset rhythmic and clear, separating the dry sound from the wet reverb while staying tied to the groove.','A mixer sets pre-delay to a sixteenth or eighth note so a vocal reverb blooms just after each phrase in time with the song.','Reverb parameter',ARRAY['Pre-delay','Reverb tail','Early reflections','Tempo-Synchronized Delay','Decay time']::text[],ARRAY['Setting pre-delay so long that the reverb feels detached from the source instead of supporting it.','Assuming a fixed-millisecond pre-delay tracks tempo: a note-value pre-delay re-syncs automatically, but a fixed-ms pre-delay does not and drifts off the beat when the tempo changes.','Confusing pre-delay with decay; pre-delay sets when the reverb starts, not how long it lasts.']::text[],ARRAY['Syncing vocal reverb pre-delay to a sixteenth note so it stays clear and rhythmic.','Timing a snare reverb''s onset to the beat for a tight, pumping ambience.','Keeping a reverb''s bloom locked to tempo as an arrangement speeds up or slows down.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5409adc1-c994-5c81-910c-c3e6800aedbd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Tempo-synchronized predelay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5409adc1-c994-5c81-910c-c3e6800aedbd','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5409adc1-c994-5c81-910c-c3e6800aedbd' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6b421cd4-753f-5280-a5a9-e697d2e15779','True-stereo reverb','A reverb topology that processes the left and right inputs through separate paths and cross-feeds each input into both output channels, so the reverberant field preserves the original left-right position of the source. It contrasts with dual-mono (each side processed only into its own channel) and mono-in stereo-out designs; in convolution form it uses four impulse-response paths per stereo channel pair.','True-stereo reverb keeps the left and right sides fully separate. A sound on the left stays on the left in its echo. This keeps the stereo picture clear and natural.','It exists to keep the stereo position of each source intact inside the reverb, so a wide mix retains its imaging instead of collapsing toward the center.','A mixer sends an already-stereo drum bus or keyboard to a true-stereo reverb so left and right elements keep their placement in the reverberant space.','Stereo reverb',ARRAY['Dual-mono reverb','Stereo width','Early reflections','Reverb tail','Convolution reverb','Pre-delay']::text[],ARRAY['Assuming any stereo-out reverb is true stereo; many sum the input to mono before adding the tail.','Feeding a mono source and expecting true-stereo benefits, which require a stereo input to work; a mono source has no left-right position to preserve.','Overusing wide true-stereo reverb until the extra energy blurs the stereo image and mono balance.']::text[],ARRAY['Reverberating a stereo drum overhead bus while keeping cymbals on their correct sides.','Placing a wide stereo keyboard in a hall without collapsing its left-right spread.','Preserving the panning of a stereo string section inside a shared reverb space.']::text[],'415df21a-f4ef-4337-84b3-c847231c6d62'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6b421cd4-753f-5280-a5a9-e697d2e15779' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('True-stereo reverb'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6b421cd4-753f-5280-a5a9-e697d2e15779','415df21a-f4ef-4337-84b3-c847231c6d62',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6b421cd4-753f-5280-a5a9-e697d2e15779' AND gt.achievement_id='415df21a-f4ef-4337-84b3-c847231c6d62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f2c8869b-863e-5f2a-8491-eb6330bab1ce','Acoustic-delay compensation','The practice of applying electronic delay to one or more microphones so that their signals arrive in time alignment with those of a more distant reference array, correcting for the finite propagation time of sound in air (approximately 343 m/s at 20 degrees C, about 2.9 ms per metre). It prevents a nearer microphone from preceding the main array, which would otherwise pull the stereo image toward the close mic and cause comb-filter coloration when the channels are summed.','Sound takes time to travel through air. A close mic hears a player before a far main mic does. This tool adds a small delay to the close mic. Now both mics line up in time and sound clean together.','It exists to reconcile microphones placed at different distances from a source so their combined sound is coherent, preserving accurate imaging and timbre rather than producing phasey, image-skewing summation.','An engineer measures or calculates the path-length difference between a spot microphone and the main pair, then dials that many milliseconds of delay into the spot channel so both align on playback.','Time alignment',ARRAY['Center-microphone delay reference','Correlation-based spot alignment','Precedence effect','Spot microphone','Comb filtering','Decca Tree']::text[],ARRAY['Delaying the wrong microphone (delaying the distant main array instead of the near spot), which worsens the timing error rather than fixing it.','Assuming alignment must be sample-perfect; over-tight alignment can remove natural depth cues (see alignment-induced flattening).','Forgetting that moving a microphone changes its required delay, then leaving a stale delay value in the channel.']::text[],ARRAY['Delaying close spot mics on woodwinds to match a Decca Tree in an orchestral session.','Aligning a distant ambience pair to the main array so reverb does not arrive early.','Compensating a soloist spot mic that sits several metres in front of the main array.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f2c8869b-863e-5f2a-8491-eb6330bab1ce' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acoustic-delay compensation'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f2c8869b-863e-5f2a-8491-eb6330bab1ce','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f2c8869b-863e-5f2a-8491-eb6330bab1ce' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'dffb61f1-420d-57b5-a7aa-2ca07ba41185','Acoustic-shadow stereo','A stereo recording approach that places a solid, often absorptive baffle between two (usually omnidirectional) microphones so the barrier acoustically shadows sound arriving from off-axis directions, producing frequency- and angle-dependent level and spectral differences between the channels. Because the shadowing increases with frequency, it emulates the directional cues created by the human head; the Jecklin disk (OSS) and the sphere microphone are canonical examples.','This method puts a solid disk between two mics. The disk blocks some sound from reaching the far mic. That copies how your head shadows sound for each ear. The two mics then hear slightly different sound. That builds a stereo picture.','It exists to add interchannel level and spectral differences to spaced omnidirectional microphones, which on their own capture mainly time differences, yielding a more stable and headphone-friendly stereo image.','An engineer mounts two omni capsules on either side of a baffle such as a foam-covered disk, typically about 165 mm apart across a roughly 300 mm disk, and positions the assembly toward the ensemble.','Stereo technique',ARRAY['Jecklin disk','Sphere microphone','Spaced pair','Interchannel level difference','Binaural recording','Omnidirectional microphone']::text[],ARRAY['Treating the baffle as optional and removing it, which collapses the intended level differences back to a plain spaced pair.','Using directional microphones on the disk, defeating the omni-plus-baffle principle the technique relies on.','UNSAFE: Hot-patching phantom-powered condenser capsules while the console channel is live, sending a loud transient into monitors; mute or unpatch before connecting and let phantom power settle.']::text[],ARRAY['Recording a solo instrument or small ensemble with a Jecklin disk for a natural, spacious image.','Capturing an acoustic ambience track that translates well on headphones.','Location recording where a compact single-point stereo rig is preferred over a wide spaced pair.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='dffb61f1-420d-57b5-a7aa-2ca07ba41185' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Acoustic-shadow stereo'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'dffb61f1-420d-57b5-a7aa-2ca07ba41185','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='dffb61f1-420d-57b5-a7aa-2ca07ba41185' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '44a2c698-bde2-521b-94e3-8fbfc6ae7434','Alignment-induced flattening','The loss of perceived front-to-back depth and perspective that results when spot and support microphones are all time-aligned (delay-compensated) to the main array, removing the natural inter-microphone arrival-time differences that convey distance. Collapsing these cues can flatten the soundstage into a more two-dimensional, foreground-heavy image.','Engineers often delay extra mics to line them up in time. But this can erase natural distance clues. The music may then sound flat, like a photo with no depth.','Naming this trade-off exists to remind engineers that delay compensation, while fixing coherence, can over-correct and strip the depth information the main array captured, so alignment should be applied judiciously.','When a mix sounds flat after aligning every spot, an engineer backs off some compensation or leaves distant supports slightly late to restore the sense of layered depth.','Time alignment',ARRAY['Acoustic-delay compensation','Center-microphone delay reference','Spot microphone','Depth perspective','Precedence effect','Main microphone array']::text[],ARRAY['Time-aligning every microphone by default without listening for the resulting loss of depth.','Confusing genuine depth cues with phase errors and ''correcting'' them away.','Aligning to sample accuracy as a rule, ignoring that some arrival-time spread is musically desirable.']::text[],ARRAY['An orchestral mix that sounds close and flat once all spot mics are delayed to the tree.','A choral recording where over-alignment removes the natural distance of a rear section.','Deciding how much to delay a soloist spot without pinning the whole stage to the front.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='44a2c698-bde2-521b-94e3-8fbfc6ae7434' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Alignment-induced flattening'),'[^a-z0-9]','','g'));
