SELECT '44a2c698-bde2-521b-94e3-8fbfc6ae7434','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='44a2c698-bde2-521b-94e3-8fbfc6ae7434' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0e914456-383b-5886-b535-ba89d7ff753b','Antiphonal microphone group','A dedicated subset of microphones assigned to an antiphonal ensemble, that is, a body of performers positioned apart from the main group (such as a second choir, a brass choir, or divided forces placed in a gallery or on the opposite side) so that call-and-response antiphonal music is captured with its intended spatial separation. The group is balanced and often panned to reflect the physical placement of that ensemble.','Some music has two groups that answer each other from far apart. This is a set of mics aimed at the second, separate group. It keeps their call-and-response spread out in the mix.','It exists to preserve the deliberate spatial dialogue of antiphonal writing, capturing the separated ensemble cleanly and at the correct position rather than letting it blur into the main pickup.','For a work with divided choirs, an engineer sets a small array on the second choir, checks its balance and delay against the main array, and pans it to its hall position.','Ensemble miking',ARRAY['Balcony microphone','Choir loft microphone','Spot microphone','Main microphone array','Acoustic-delay compensation','Panning']::text[],ARRAY['Panning the antiphonal group to the center, erasing the spatial separation the composer intended.','Ignoring the propagation delay from the distant group, so it arrives early against the main array.','UNSAFE: Positioning tall stands for a raised antiphonal group without securing bases or safety-cabling flown mics, risking a fall hazard; follow OSHA fall-protection and stand-rigging practice.']::text[],ARRAY['Recording Gabrieli or other Venetian polychoral music with separated brass and voices.','A Requiem calling for an offstage or gallery brass choir answering the main orchestra.','A large festival chorus split into two spatially divided bodies.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0e914456-383b-5886-b535-ba89d7ff753b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Antiphonal microphone group'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0e914456-383b-5886-b535-ba89d7ff753b','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0e914456-383b-5886-b535-ba89d7ff753b' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '19671126-ac07-52db-a37b-8497c6a354e0','Balcony microphone','A microphone placed in or on a hall''s balcony or gallery, used either to capture performers positioned there (for example antiphonal brass, a gallery choir, or organ) or to pick up the reverberant field and audience from an elevated rear vantage. Its height and distance make it valuable for spatial depth and hall ambience.','This mic sits up in a hall balcony. It can catch singers or players placed up there. It can also catch the room echo from a high spot.','It exists to reach sources or ambience that a stage-level main array cannot cover well, adding elevation, hall character, and coverage of balcony-placed performers.','An engineer rigs a microphone at the balcony rail on a stand or clamp, aims it at the intended source or into the room, and blends or delays it against the main array.','Ensemble miking',ARRAY['Antiphonal microphone group','Choir loft microphone','Ambience microphone','Main microphone array','Acoustic-delay compensation','Reverberation']::text[],ARRAY['Blending the balcony mic too hot, so its long delay smears transients and blurs the image.','Aiming it at a noisy audience area and capturing coughs and rustle instead of useful ambience.','UNSAFE: Working at the balcony edge or on a ladder to rig without fall protection or a safety cable on the mic; follow OSHA 1926 Subpart M and ANSI/ESTA E1 rigging practice.']::text[],ARRAY['Miking a gallery organ or antiphonal brass placed in the balcony.','Adding a rear ambience channel for a live concert recording.','Capturing hall reverberation for an immersive or surround mix.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='19671126-ac07-52db-a37b-8497c6a354e0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Balcony microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '19671126-ac07-52db-a37b-8497c6a354e0','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='19671126-ac07-52db-a37b-8497c6a354e0' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a022ab25-dd67-501a-8ea5-bc277c8d8975','Bass outrigger','A widely spaced flanking omnidirectional microphone placed outboard of a main array or Decca Tree, positioned toward the low-string or bass side of the ensemble and used to reinforce low-frequency weight and widen the stereo image. Outriggers extend the effective width beyond the main tree and, being omnidirectional, add low-frequency extension and warmth.','An outrigger is a wide mic set out to the side of the main mics. This one leans toward the low, bassy instruments. It adds width and a fuller low end to the sound.','It exists to broaden the stereo stage and add low-end foundation that the closely grouped main tree alone cannot supply, without resorting to close spot mics on the basses.','An engineer places an omni several metres to the side (often over the cellos or double basses), then blends it in for width and low-frequency support, delaying it if needed to align with the tree.','Stereo array',ARRAY['Decca Tree','Outrigger microphone','Spaced pair','Omnidirectional microphone','Center-fill microphone','Acoustic-delay compensation']::text[],ARRAY['Spacing outriggers so wide that the image splits into two exaggerated edges with a weak center.','Forgetting to delay outriggers relative to the tree, causing timing smear when summed.','Using directional mics and losing the low-frequency extension that omnis provide.']::text[],ARRAY['Widening an orchestral image and adding bass weight around a Decca Tree.','Reinforcing the double-bass and cello foundation in a large-hall recording.','Extending stereo spread for a big-band or film-scoring session.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a022ab25-dd67-501a-8ea5-bc277c8d8975' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Bass outrigger'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'a022ab25-dd67-501a-8ea5-bc277c8d8975','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a022ab25-dd67-501a-8ea5-bc277c8d8975' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '89745174-252b-5b78-a5ac-db057d1166f2','Center-downfill microphone','A centrally placed microphone angled downward to reinforce the front-and-center of a large or tiered ensemble that a higher, more distant main array covers weakly, analogous to a downfill loudspeaker filling the near-front seats below the main hangs. It complements, rather than replaces, the main pickup by adding presence to the closest central performers.','A big choir or band can be hard to catch from one high spot. This center mic tilts down to grab the front and middle. It fills in players the main mics hear weakly.','It exists to fill the near-central portion of an ensemble that the elevated main array underrepresents, improving clarity and balance for front-row or floor-level central sources.','An engineer positions a cardioid above and forward of the ensemble center, tilts it down onto the front rows, and blends it to taste with the main array.','Ensemble miking',ARRAY['Center-fill microphone','Main microphone array','Spot microphone','Choir loft microphone','Acoustic-delay compensation','Cardioid microphone']::text[],ARRAY['Overusing the downfill so the front-center dominates and the overall perspective becomes unnatural.','Neglecting delay alignment, so the closer downfill precedes the main array and pulls the image forward.','UNSAFE: Suspending or booming a mic over performers without a safety cable and secured rigging; follow ANSI/ESTA E1 and OSHA rigging practice.']::text[],ARRAY['Reinforcing the front row of a large choir the overhead main array captures faintly.','Filling the center-front of a tiered ensemble on risers.','Adding presence to soloists standing ahead of a big ensemble.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='89745174-252b-5b78-a5ac-db057d1166f2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Center-downfill microphone'),'[^a-z0-9]','','g'));
