SELECT '89745174-252b-5b78-a5ac-db057d1166f2','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='89745174-252b-5b78-a5ac-db057d1166f2' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'a04d57af-7b90-5a33-8ffd-382204ddcaba','Center-fill microphone','A microphone placed at the center of a stereo array to reinforce the central image and fill the weak ''hole in the middle'' that a widely spaced pair leaves between the loudspeakers. The center microphone of a Decca Tree is the canonical example, strengthening the phantom center and stabilizing the localization of central sources.','Two widely spaced mics can leave a weak spot in the middle. This mic sits in the center to fix that gap. It makes sounds in the middle feel solid and clear.','It exists to solve the weak or unstable center image of spaced omnidirectional pairs, restoring a solid, well-localized middle without narrowing the overall stereo width.','An engineer adds a center microphone forward of and between the left and right mics, then blends it until center sources such as a soloist or conductor''s podium sound firmly anchored.','Stereo array',ARRAY['Decca Tree','Spaced pair','Phantom center','Bass outrigger','Hole in the middle','Interchannel time difference']::text[],ARRAY['Adding too much center so the stereo spread collapses toward mono.','Placing the center mic level with the pair instead of slightly forward, reducing its stabilizing effect.','Ignoring polarity and level match, causing the center to comb-filter against the outer pair.']::text[],ARRAY['The forward center mic of a Decca Tree on an orchestra.','Firming up the center of a widely spaced omni pair on a large ensemble.','Anchoring a central soloist within a spaced-pair main array.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='a04d57af-7b90-5a33-8ffd-382204ddcaba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Center-fill microphone'),'[^a-z0-9]','','g'));
