SELECT 'a04d57af-7b90-5a33-8ffd-382204ddcaba','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='a04d57af-7b90-5a33-8ffd-382204ddcaba' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '75d40263-d228-5b9c-90c0-df127b07dd30','Center-microphone delay reference','The practice of treating the center microphone of a main array (such as a Decca Tree) as the timing anchor to which spot and support microphones are delay-compensated, so all supporting mics are aligned relative to the arrival time at the center of the main pickup. Using one fixed reference keeps the whole session''s alignment consistent.','The center mic is used as the clock that all other mics match. Each extra mic is delayed to line up with it. This keeps every mic in time with one shared point.','It exists to give delay compensation a single, stable zero-point, preventing inconsistent alignment that would arise if each spot were referenced to a different microphone.','An engineer designates the tree''s center mic as time zero, measures each spot''s path-length difference to it, and applies the matching delay to every spot channel.','Time alignment',ARRAY['Acoustic-delay compensation','Correlation-based spot alignment','Alignment-induced flattening','Decca Tree','Spot microphone','Precedence effect']::text[],ARRAY['Switching the reference mic partway through a session, so previously set delays no longer match.','Referencing spots to a distant outrigger instead of the center, skewing the alignment.','Forgetting that repositioning the main tree changes every spot''s delay to the reference.']::text[],ARRAY['Setting all orchestral spot delays against the Decca Tree center mic.','Establishing a consistent alignment anchor before a multi-session recording.','Re-checking spot delays after the main array is moved between pieces.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='75d40263-d228-5b9c-90c0-df127b07dd30' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Center-microphone delay reference'),'[^a-z0-9]','','g'));
