WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='75d40263-d228-5b9c-90c0-df127b07dd30' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '996e1b28-f4a1-5deb-95ce-ac279aaac00b','Choir loft microphone','A microphone positioned to capture a choir situated in a choir loft, an elevated gallery often at the rear of a church or cathedral and frequently near or above the organ. It is placed to capture the choir''s blend together with the loft''s acoustic and the relationship between choir and organ.','A choir loft is a raised gallery where a choir stands. This mic is placed to catch that choir. It captures their blend and the space around them.','It exists to pick up a raised, often distant choir that a stage-level array cannot properly reach, preserving its blend, elevation, and the surrounding hall sound.','An engineer rigs a stereo pair or spot at the loft rail aimed at the choir, then balances and delays it against any main array covering the rest of the performance.','Ensemble miking',ARRAY['Balcony microphone','Antiphonal microphone group','Conductor-position microphone','Ambience microphone','Acoustic-delay compensation','Spaced pair']::text[],ARRAY['Placing the mic so close it captures a few front voices instead of the choir''s overall blend.','Ignoring the organ''s proximity and being overwhelmed by low-frequency wind noise from pipes.','UNSAFE: Rigging in an elevated loft without fall protection or safety-cabling flown microphones; follow OSHA 1926 Subpart M and ANSI/ESTA E1.']::text[],ARRAY['Recording a cathedral choir singing from the rear gallery.','Capturing a choir-and-organ work where both share the loft.','Adding a raised choir pickup to a main orchestral array on the chancel.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='996e1b28-f4a1-5deb-95ce-ac279aaac00b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Choir loft microphone'),'[^a-z0-9]','','g'));
