WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='996e1b28-f4a1-5deb-95ce-ac279aaac00b' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '7a7c07c7-4ac2-56a3-83cc-0fb9ddef092c','Conductor-position microphone','A microphone placed at or near the conductor''s location, roughly where the conductor stands and hears the ensemble''s internal balance, used as a main or reference pickup because that vantage represents the intended blend of the forces. Classic main arrays such as the Decca Tree are habitually rigged just above and behind this position for the same reason.','The conductor stands where the whole group sounds balanced. A mic placed there hears that same good balance. Engineers use it as a main or backup pickup.','It exists to capture the ensemble from the point of best musical balance, giving the engineer a natural reference perspective on the overall sound.','An engineer sets the main array on a tall stand just behind and above the podium, at the height and distance that reproduce the balance the conductor hears.','Ensemble miking',ARRAY['Decca Tree','Main microphone array','Center-fill microphone','Spaced pair','Balcony microphone','Acoustic-delay compensation']::text[],ARRAY['Placing the array so low it favors the front desks and loses the rear sections'' balance.','Setting it directly over the podium where the conductor''s movement and breathing intrude.','UNSAFE: Extending a heavy main array on a tall stand without adequate base weighting or safety ties, risking a tip-over onto players; follow stand-rigging and ANSI/ESTA E1 practice.']::text[],ARRAY['Rigging a Decca Tree just behind and above the conductor for an orchestral recording.','Establishing the main reference perspective for a large-ensemble session.','Capturing the intended internal balance of a choir and orchestra together.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='7a7c07c7-4ac2-56a3-83cc-0fb9ddef092c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Conductor-position microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '7a7c07c7-4ac2-56a3-83cc-0fb9ddef092c','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='7a7c07c7-4ac2-56a3-83cc-0fb9ddef092c' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '546581f5-6b2a-5d0e-94ee-36294a64bd9c','Correlation-based spot alignment','A method of time-aligning a spot microphone to the main array by computing the cross-correlation between the spot signal and a main-array signal; the lag at which the correlation peaks estimates the propagation-time difference, which is then applied as compensating delay. It automates what would otherwise be done by measuring path length or by ear.','Software compares a close mic to the main mics. It finds the delay where the two best match up. That delay is then used to sync the close mic.','It exists to derive an accurate delay value objectively from the audio itself, speeding up and improving the consistency of multi-microphone time alignment.','An engineer runs a correlation or delay-finder tool on the spot and main tracks, reads the peak lag, and sets that delay on the spot channel, then confirms by listening.','Time alignment',ARRAY['Acoustic-delay compensation','Center-microphone delay reference','Alignment-induced flattening','Cross-correlation','Comb filtering','Spot microphone']::text[],ARRAY['Trusting a correlation peak blindly when a false peak from strong reflections gives the wrong lag.','Aligning every spot to sample accuracy and flattening the natural depth of the recording.','Correlating against a poorly chosen main channel with little shared content, yielding an unreliable result.']::text[],ARRAY['Batch-aligning many orchestral spot mics to a Decca Tree in post.','Verifying a hand-measured delay value against the audio.','Setting delays for a large multi-mic session where manual measurement is impractical.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='546581f5-6b2a-5d0e-94ee-36294a64bd9c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Correlation-based spot alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
