WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='546581f5-6b2a-5d0e-94ee-36294a64bd9c' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6d65b134-984a-57fc-84c1-b48ad5a8d679','Decca Tree 3D','An immersive extension of the Decca Tree in which the classic three-microphone omnidirectional tree that forms the front layer is augmented with additional surround and overhead (height) microphones to capture a three-dimensional sound field for formats such as 5.1.4 Dolby Atmos or Auro-3D. The added layers extend the tree''s depth and width into full periphonic (with-height) reproduction.','A Decca Tree is three mics that capture wide stereo. The 3D version adds more mics for surround and overhead. Together they capture sound all around and above the listener.','It exists to carry the Decca Tree''s proven front imaging into immersive delivery, adding surround and height capture so the recording reproduces sound around and above the listener.','An engineer builds the standard tree, then adds surround and upward-facing height microphones on the same rig, routing each layer to the corresponding channels of the immersive format.','Immersive array',ARRAY['Decca Tree','Decca Tree height layer','Bass outrigger','Ambience microphone','Center-fill microphone','Surround microphone array']::text[],ARRAY['Treating the height and surround mics as an afterthought, so the immersive layers do not match the front image.','Letting too much direct floor-level sound into the height mics, muddying the overhead layer.','UNSAFE: Overloading a single stand with the added surround and height mics without rated support and safety cabling; follow ANSI/ESTA E1 and manufacturer load limits.']::text[],ARRAY['Recording an orchestra for a Dolby Atmos or Auro-3D release.','Capturing a film score in an immersive 5.1.4 layout.','Producing a spatial-audio classical album from a single main rig.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6d65b134-984a-57fc-84c1-b48ad5a8d679' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decca Tree 3D'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '6d65b134-984a-57fc-84c1-b48ad5a8d679','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6d65b134-984a-57fc-84c1-b48ad5a8d679' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5eaa7e4d-3f5d-5e84-bd87-18d63b32b683','Decca Tree height layer','The set of upward-oriented overhead microphones added above a main Decca Tree to capture the vertical component of the sound field, feeding the height channels of an immersive format. The layer is positioned and pattern-chosen to emphasize overhead ambience and hall reflections while suppressing direct sound from floor-level sources.','This is the set of mics placed high above the main tree. They catch sound and echo coming from overhead. That gives a recording a real sense of height.','It exists to supply the elevation and overhead-ambience cues that a horizontal array cannot capture, giving an immersive recording a convincing sense of height and enveloping space.','An engineer mounts height capsules above the tree, angled upward or outward, and routes them to the top channels, checking that direct floor sound is well rejected.','Immersive array',ARRAY['Decca Tree 3D','Decca Tree','Ambience microphone','Surround microphone array','Reverberation','Interchannel time difference']::text[],ARRAY['Aiming the height mics straight at the ensemble, capturing direct sound instead of overhead ambience.','Spacing the height layer inconsistently with the front tree, so elevation cues do not integrate.','UNSAFE: Rigging overhead mics above performers or on tall extensions without safety cables and rated hardware; follow ANSI/ESTA E1 and OSHA rigging practice.']::text[],ARRAY['Adding the top layer of a 5.1.4 Atmos orchestral recording.','Capturing cathedral height and reflections for an immersive choral album.','Providing overhead envelopment on a film-scoring stage.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5eaa7e4d-3f5d-5e84-bd87-18d63b32b683' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decca Tree height layer'),'[^a-z0-9]','','g'));
