WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5eaa7e4d-3f5d-5e84-bd87-18d63b32b683' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e98f1e62-372d-5bd0-97e5-cb0bb4e09576','Decca Tree outriggers','A pair of additional spaced omnidirectional microphones placed outboard (left and right) of the three-capsule Decca Tree, wider apart than the tree''s own left and right capsules. Panned hard left and right, they extend the width of the recorded stereo image and add coverage of the outer sections of a large orchestra, such as the first violins and cellos or basses.','Outriggers are two extra microphones set wide, outside the main three-mic Decca Tree. They are panned hard left and right. They make the orchestra sound wider. They also pick up the players at the far edges.','They exist to widen the stereo spread beyond what the compact main tree alone can produce, and to give more presence to the outer instrument sections of a large ensemble.','A classical engineer flies the Decca Tree over the conductor, places outrigger omnis a metre or two outside it above the violins and cellos, and pans them to the edges of the mix.','Orchestral Miking',ARRAY['Decca Tree wings','Far-flank microphone','Spaced omni pair (AB)','Spot microphone','Front–rear array spacing']::text[],ARRAY['Spacing the outriggers so wide that the centre of the orchestra develops a hole with no solid image between the loudspeakers.','Forgetting that the outriggers sit farther from the stage than the tree, so their later arrival can smear transients unless delay and phase are checked.','UNSAFE: Flying outrigger microphones over players or audience without a secondary safety (safety cable or bond) and without respecting the rated working load of the stand or rigging point.']::text[],ARRAY['Recording a large symphony orchestra where the main Decca Tree cannot capture the full width of the string sections.','Widening the stereo image of a film-score session tracked on a scoring stage.','Adding edge width and hall balance to a live concert recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e98f1e62-372d-5bd0-97e5-cb0bb4e09576' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decca Tree outriggers'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e98f1e62-372d-5bd0-97e5-cb0bb4e09576','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e98f1e62-372d-5bd0-97e5-cb0bb4e09576' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f471e625-a457-596a-b0de-0b7a8fe701fc','Decca Tree wings','Flanking microphones placed to the left and right of the main Decca Tree, outboard of its own left and right capsules, used to broaden the captured stereo width and cover the wide extremes of a large ensemble. The term is used much like "outriggers"; some engineers reserve "wings" for the outermost flanking pair that frames the whole width.','Wings are microphones added to the sides of the main Decca Tree. They reach out to the far left and far right of the group. This broadens the sound and captures players at the edges. Many engineers use the words wings and outriggers to mean the same thing.','They exist to extend the stereo image and coverage of the compact main array so that a very wide orchestra or choir fills the space between the loudspeakers.','On a wide platform an engineer adds a left and right wing omni beyond the tree to keep the outer desks of strings present and the image full.','Orchestral Miking',ARRAY['Decca Tree outriggers','Far-flank microphone','Spaced omni pair (AB)','Spot microphone','Stereo spread']::text[],ARRAY['Assuming "wings" and "outriggers" always mean two different things; usage varies between engineers and studios.','Placing wings so wide that the middle of the image weakens, leaving a gap between left and right.','UNSAFE: Rigging wing microphones overhead without a secondary safety cable and without checking the rated capacity of the mount or truss.']::text[],ARRAY['Miking a wide choir plus orchestra where the main tree alone leaves the outer voices thin.','Broadening the image on a large-scale film-scoring date.','Framing the full width of a big band or wind ensemble in a concert hall.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f471e625-a457-596a-b0de-0b7a8fe701fc' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Decca Tree wings'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f471e625-a457-596a-b0de-0b7a8fe701fc','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f471e625-a457-596a-b0de-0b7a8fe701fc' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8f0797b2-ab80-5071-8e6b-6b84968a82a7','Depth-plane mismatch','A spatial inconsistency in which a source is portrayed at conflicting apparent distances by different microphones in a multi-mic setup—typically a close spot microphone making an instrument sound near while the main array places it far back—so the instrument''s depth relative to the ensemble is unnatural or unstable.','Depth-plane mismatch is when one microphone makes an instrument sound close but another makes it sound far away. The two views of distance disagree. In the mix the instrument seems to jump forward or sit at the wrong depth.','Naming this problem helps engineers diagnose why a blended recording sounds unnatural, so they can fix depth with level, delay, and reverb rather than guessing.','When a spot mic on the woodwinds is too loud or undelayed, the winds leap to the front; the engineer trims level, adds delay, or matches reverb to seat them back with the ensemble.','Spatial Imaging',ARRAY['Depth-preserving delay','Spot microphone','Precedence effect','Distance-to-delay conversion','Reverberation balance']::text[],ARRAY['Raising a spot mic for clarity without delaying it, which drags the instrument unnaturally to the front of the depth image.','Adding close-mic reverb that does not match the main array, so the instrument sits in a different acoustic space.','Judging depth on headphones only, then finding the mismatch obvious on loudspeakers.']::text[],ARRAY['Blending woodwind spot mics into an orchestral main pair where the winds suddenly sound too close.','Mixing a live concert capture where a soloist''s spot mic breaks the sense of stage depth.','Balancing choir spot mics against a distant main array in a cathedral recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8f0797b2-ab80-5071-8e6b-6b84968a82a7' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Depth-plane mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '8f0797b2-ab80-5071-8e6b-6b84968a82a7','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8f0797b2-ab80-5071-8e6b-6b84968a82a7' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '26962664-8de1-508f-aa06-7e6bdc431065','Depth-preserving delay','A delay applied to a close or spot microphone equal to (or slightly greater than) the time sound takes to travel from the source to the main array, so that the main array remains the first arrival. By preserving the precedence relationship, the spot mic adds detail and level without pulling the instrument forward, keeping its natural depth within the ensemble.','This is a small delay added to a close microphone in a mix. It makes the close mic arrive just after the main pair, not before. The ear locks onto the first sound it hears. So the instrument keeps sitting at its real distance, with extra detail but no jump forward.','It exists to let engineers reinforce a section with spot mics while the main array still governs where and how far away each instrument sounds, protecting the recording''s depth and perspective.','An engineer measures the distance from a spot mic to the main tree, converts it to milliseconds, and dials that delay (often a touch more) into the spot channel before balancing its level.','Time Alignment',ARRAY['Distance-to-delay conversion','Precedence effect','Depth-plane mismatch','Spot microphone','Double-arrival artifact']::text[],ARRAY['Delaying by exactly the arrival time and no more; a small extra delay more reliably keeps the main array first.','Setting the delay by ear alone and getting the direction of the offset backwards, which worsens the smear.','Ignoring floor and other early reflections, which the effective first arrival at the main pair actually includes.']::text[],ARRAY['Reinforcing a distant brass section with a spot mic without losing orchestral depth.','Time-aligning choir spot mics behind a main pair in a live recording.','Blending accent mics into a Decca Tree on a film-score stage.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='26962664-8de1-508f-aa06-7e6bdc431065' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Depth-preserving delay'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '26962664-8de1-508f-aa06-7e6bdc431065','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='26962664-8de1-508f-aa06-7e6bdc431065' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '6136eff3-a71c-5efe-a5cb-59751806f1e6','Distance-to-delay conversion','The calculation that converts a physical distance—typically the extra path length between a spot microphone and the main array—into a time delay, using the speed of sound in air, about 343 m/s at 20 °C, or roughly 2.9 ms per metre (about 0.9 ms per foot). It yields the delay value needed to time-align distributed microphones.','This is the math that turns a distance into a delay time. Sound travels about 343 meters every second in warm air. So each extra meter adds about 2.9 milliseconds of travel time. You use this to match up microphones set at different distances.','It exists so engineers can set spot-mic delays from a simple tape-measure reading rather than trial and error, matching each microphone''s timing to the main array.','A technician measures 6 m from a spot mic to the main pair, multiplies by about 2.9 ms, and sets roughly 17 ms of delay on that channel.','Time Alignment',ARRAY['Depth-preserving delay','Precedence effect','Speed of sound','Double-arrival artifact','Sample delay']::text[],ARRAY['Forgetting that the speed of sound rises with temperature, so a fixed millisecond-per-metre figure drifts in a hot hall.','Measuring straight-line distance while ignoring that the relevant reference at the main pair includes early reflections.','Mixing up feet and metres and dialing a delay several times too long or too short.']::text[],ARRAY['Calculating spot-mic delays for an orchestral session from measured mic-to-tree distances.','Time-aligning a distant ambience mic to a close pair in post-production.','Setting delays for distributed mics across a large choir.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='6136eff3-a71c-5efe-a5cb-59751806f1e6' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Distance-to-delay conversion'),'[^a-z0-9]','','g'));
