SELECT '6136eff3-a71c-5efe-a5cb-59751806f1e6','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='6136eff3-a71c-5efe-a5cb-59751806f1e6' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '900d65f1-fb6c-5dee-a6cf-10d9cce1488e','Distant-brass microphone','A spot or accent microphone dedicated to the brass section, which in standard orchestral seating sits at the rear of the platform and therefore far from the main array. Being distant, it requires the largest time delay to align with the main pair, and it is usually set back enough to capture the brass with a degree of hall bloom rather than tight close detail.','This is a support microphone for the brass, like trumpets and trombones. Brass usually sits at the back of the orchestra. So this mic is far from the main microphones and needs the most delay. It is placed to catch the brass with a bit of room sound, not right in the bells.','It exists to add presence and control to a section seated far from the main array, giving the engineer level and balance over the brass without close, harsh bell tone.','An engineer hangs or stands a cardioid a metre or two in front of the brass, delays it to match the main tree, and rides it up in loud tuttis for definition.','Spot Miking',ARRAY['Spot microphone','Depth-preserving delay','Distance-to-delay conversion','Decca Tree outriggers','Accent microphone']::text[],ARRAY['Riding the brass spot too hot in tuttis, which shoves the section forward and flattens orchestral depth.','Leaving the distant brass mic undelayed, so it arrives before the main pair and smears the image.','UNSAFE: Working with your head close to loud brass bells while positioning the mic; peaks can exceed safe exposure limits, so use hearing protection.']::text[],ARRAY['Reinforcing brass in a film-score tutti without losing the orchestral perspective.','Adding weight to the horns in a live symphonic broadcast.','Balancing a brass-heavy passage where the main pair alone lacks impact.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='900d65f1-fb6c-5dee-a6cf-10d9cce1488e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Distant-brass microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '900d65f1-fb6c-5dee-a6cf-10d9cce1488e','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='900d65f1-fb6c-5dee-a6cf-10d9cce1488e' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4033c064-cbb4-53b3-b3d1-6550c36730b3','Double-arrival artifact','An audible defect that occurs when the same sound reaches two microphones (or travels two paths to one microphone) and the two time-offset copies are summed, producing comb-filter coloration and, at larger offsets, a perceptible doubling or slap. It is a core reason spot microphones are delayed and the 3:1 spacing guideline exists.','This happens when the same sound reaches two microphones at slightly different times. When you add the two signals, some frequencies cancel and others boost. That gives a hollow, colored tone, or even a faint echo. Delaying or spacing the mics helps avoid it.','Understanding this artifact tells engineers why blending mics can sound hollow or echoey, and drives the use of delay, spacing rules, and phase checks.','When a blended spot mic makes an instrument sound thin, the engineer flips polarity, nudges delay, or moves the mic to clear the comb-filter notches.','Phase & Alignment',ARRAY['Comb filtering','3:1 rule','Depth-preserving delay','Precedence effect','Polarity']::text[],ARRAY['Blaming an EQ problem for the hollow tone when the real cause is two time-offset arrivals combing.','Flipping polarity but leaving the time offset, so the comb filtering remains.','Assuming only multi-mic setups cause it, when a strong floor or wall reflection into one mic combs just as badly.']::text[],ARRAY['A spot mic summed with the main pair makes an instrument sound hollow.','A floor reflection combs with the direct sound into a single overhead mic.','Two drum overheads at unequal distances colour the snare when summed to mono.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4033c064-cbb4-53b3-b3d1-6550c36730b3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Double-arrival artifact'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '4033c064-cbb4-53b3-b3d1-6550c36730b3','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4033c064-cbb4-53b3-b3d1-6550c36730b3' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '948a3277-682b-5b2f-85e7-e17835d91f94','Far-flank microphone','The outermost flanking microphone of a stereo or surround array, positioned well to the side of the main pair to capture the far edge of an ensemble and extend stereo width. It functions like an outrigger, sitting beyond the inner mics and typically panned toward the corresponding side of the image.','This is the outer side microphone in an array, set well out to one side. It catches the players at the far edge of the group. Panned to that side, it stretches the stereo picture wider. It works much like a Decca Tree outrigger.','It exists to widen the captured image and hold the outer sections of a large ensemble in place, filling the extremes between the loudspeakers.','An engineer places a far-flank omni beyond the main pair, level with the edge of the strings, and pans it hard to that side to broaden the stage.','Orchestral Miking',ARRAY['Decca Tree outriggers','Decca Tree wings','Spaced omni pair (AB)','Front–rear array spacing','Stereo spread']::text[],ARRAY['Panning the far-flank mic short of the edge, wasting the width it was placed to provide.','Setting it so far out that the middle of the image thins and separates.','UNSAFE: Suspending a far-flank mic over people without a safety cable and a load-rated mount.']::text[],ARRAY['Widening a spaced array on a large orchestra to fill the loudspeaker stage.','Capturing the outer desks of a string section that the main pair misses.','Extending image width on a big-band recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='948a3277-682b-5b2f-85e7-e17835d91f94' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Far-flank microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '948a3277-682b-5b2f-85e7-e17835d91f94','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='948a3277-682b-5b2f-85e7-e17835d91f94' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '252bb764-56dc-5bc7-aed4-5876792f7389','Faulkner array null-axis control','The technique of orienting a Faulkner Phased Array—two forward-facing figure-of-eight microphones spaced about 20 cm (7.9 in) apart—so that the deep nulls of the bidirectional pattern, which lie at 90° to each side, reject unwanted lateral sound such as side-wall reflections, audience noise, or adjacent sections. Because both mics face straight ahead and rely on interchannel time differences (up to about 0.58 ms), aiming the shared null axis suppresses side energy while keeping the frontal image.','The Faulkner array uses two figure-eight microphones set 20 centimeters apart, both facing forward. A figure-eight mic hears the front and back but is nearly deaf to its sides. By turning the pair, you aim those deaf spots at what you want to reject. That cuts side reflections and noise while keeping the sound in front.','It exists to give clean recordings in difficult or reverberant rooms by using the figure-of-eight side nulls to reject problem reflections, without the level-difference steering of angled cardioid pairs.','In a boomy church an engineer points the Faulkner pair at the ensemble and rotates it slightly so the side nulls face a reflective wall, cutting the worst reflections.','Stereo Miking',ARRAY['Blumlein pair','Figure-of-eight (bidirectional)','ORTF','Mid-Side (M/S)','Interchannel time difference']::text[],ARRAY['Confusing the Faulkner array with a Blumlein pair; Faulkner spaces the figure-eights and faces them forward rather than crossing them at 90°.','Expecting a very wide stereo image; the small spacing fills only about half the loudspeaker stage.','Forgetting the figure-of-eight rear lobe, which still picks up sound and reflections from behind.']::text[],ARRAY['Recording a choir in a reverberant church while rejecting side-wall reflections.','Capturing an ensemble in a noisy hall by aiming the nulls toward the audience.','Miking a soloist where a nearby reflective surface must be nulled out.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='252bb764-56dc-5bc7-aed4-5876792f7389' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Faulkner array null-axis control'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '252bb764-56dc-5bc7-aed4-5876792f7389','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='252bb764-56dc-5bc7-aed4-5876792f7389' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bf74321f-f7c0-5737-b502-1794194dad19','Fly-rail microphone','A microphone suspended from a theatre''s overhead fly system—the battens, bars, or grid operated from the fly rail—positioned high above the stage to capture an ensemble or stage sound from above. It provides a distant, elevated pickup useful for overall balance, ambience, or coverage where floor stands are impractical.','This is a microphone hung from the bars high above a theatre stage. Those bars are raised and lowered from the fly rail at the side of the stage. From up there the mic captures the whole stage from above. It is used when a floor stand would be in the way.','It exists to get a microphone high over a stage for overall pickup or ambience without cluttering the floor, using the theatre''s existing rigging.','A theatre sound technician ties a mic to a flown batten, dresses and safeties the cable, and flies it in over the stage for a broad overhead capture.','Ambience Miking',ARRAY['Gallery microphone','Overhead microphone','Ambience microphone','Distance-to-delay conversion','Spot microphone']::text[],ARRAY['Placing a flown mic so high that it captures more roof and ventilation noise than useful stage sound.','Forgetting to delay a high, distant flown mic relative to closer mics, which smears the blend.','UNSAFE: Hanging a microphone or its cable over performers without an independent secondary safety (safety cable) and strain relief; a dropped mic or cable can injure people below.','UNSAFE: Rigging from a batten or point beyond its rated working load, or without following the venue''s rigging procedures and qualified-rigger requirements (ANSI E1.4-1, Manual Counterweight Rigging Systems).']::text[],ARRAY['Capturing a whole stage ensemble in a theatre where floor stands would block sightlines.','Adding an overhead ambience channel to a musical-theatre recording.','Miking a choir on stage from above during a live show.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bf74321f-f7c0-5737-b502-1794194dad19' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Fly-rail microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bf74321f-f7c0-5737-b502-1794194dad19','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bf74321f-f7c0-5737-b502-1794194dad19' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '0c50694f-c942-552d-91d4-30a65d13d845','Frequency-dependent alignment','Time or phase alignment between microphones or sources whose optimal value changes with frequency, because a fixed time delay corresponds to a different phase angle at each frequency and low and high content may radiate from different effective points. Correcting it can require all-pass or multiband phase adjustment rather than a single broadband delay.','A single delay lines up microphones at only some frequencies. A fixed delay shifts a low note and a high note by different parts of their wave cycles. So low and high sounds may not line up together. Fixing this needs tools that adjust timing by frequency, not one fixed delay.','Recognizing it explains why a simple delay never fully removes comb filtering across the whole spectrum, guiding engineers toward phase or multiband tools when needed.','When time-aligning a subwoofer to a main, or two mics on one source, an engineer uses an all-pass filter to match phase through the crossover region rather than only a delay.','Phase & Alignment',ARRAY['Comb filtering','All-pass filter','Phase','Distance-to-delay conversion','Double-arrival artifact']::text[],ARRAY['Assuming one delay value aligns two mics at every frequency; it only matches a limited band.','Confusing polarity inversion with phase alignment, when phase varies continuously with frequency.','Judging alignment from a single test tone instead of across the spectrum.']::text[],ARRAY['Aligning a subwoofer to full-range tops through the crossover region.','Blending a close mic and a room mic that never fully phase-align with one delay.','Time-aligning a microphone and DI on bass guitar.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='0c50694f-c942-552d-91d4-30a65d13d845' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Frequency-dependent alignment'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '0c50694f-c942-552d-91d4-30a65d13d845','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='0c50694f-c942-552d-91d4-30a65d13d845' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc065e71-8d6b-5f73-9229-e542283afaba','Front-fill recording microphone','A microphone added to reinforce the front-centre of a recorded stereo or surround image, filling in central sources or the near front row of an ensemble that a widely spaced main pair or outer array under-represents. It is the recording analogue of a front-fill loudspeaker, which covers the front rows a main PA misses.','A widely spaced pair of microphones can leave the middle of the sound weak. A front-fill microphone sits near the center to fill that gap. It firms up sounds coming from straight ahead. It works like the small front speakers that cover the first rows at a concert.','It exists to stabilize the centre of the image and support near, central sources so the recording does not develop a weak or hollow middle between the outer mics.','With a wide spaced pair leaving a soft centre, an engineer adds a central mic (or uses the tree''s centre capsule), delays it to match, and blends it up to firm the middle.','Stereo Miking',ARRAY['Decca Tree','Centre microphone','Spaced omni pair (AB)','Depth-preserving delay','Spot microphone']::text[],ARRAY['Turning the front-fill up too far, which collapses the stereo width into a mono-heavy centre.','Leaving it undelayed relative to the outer pair, causing comb filtering in the centre image.','Confusing a recording front-fill with a live front-fill loudspeaker; here it is a capture mic, not a speaker.']::text[],ARRAY['Filling the soft centre of a wide spaced-omni orchestral array.','Reinforcing a soloist positioned centre-front of an ensemble.','Solidifying the middle image on a large choir recorded with a wide pair.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc065e71-8d6b-5f73-9229-e542283afaba' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Front-fill recording microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'bc065e71-8d6b-5f73-9229-e542283afaba','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bc065e71-8d6b-5f73-9229-e542283afaba' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '317c0628-10c1-53b7-b07f-5fdd11e08dfd','Front–rear array spacing','The physical distance between the front (main) microphone array and the rear or surround array in a multichannel or immersive recording setup. It sets the time relationship between front and surround channels—larger spacing gives later rear arrivals and greater spaciousness, while excessive spacing can produce audible echo or a detached rear image. Typical practice places the rear pair on the order of 2–5 m behind the front array.','In surround recording you use a front group and a rear group of microphones. The gap between them is the front-to-rear spacing. A bigger gap makes the room sound more spacious. Too big a gap, though, turns the rear sound into an obvious echo.','It exists as a key control over spaciousness and envelopment in surround recording, trading a sense of the room against the risk of hearing the rear channels as a separate echo.','Recording surround in a hall, an engineer sets the rear pair a few metres behind the main array, then adjusts the distance and level until the room feels enveloping but not echoey.','Immersive Miking',ARRAY['Main microphone array','Ambience microphone','Hamasaki Square','Precedence effect','Gallery microphone']::text[],ARRAY['Spacing the rear array so far back that the surround channels are heard as a distinct echo instead of envelopment.','Placing the rear pair too close, giving little added sense of space.','Ignoring that the same spacing behaves differently in a dry room versus a reverberant hall.']::text[],ARRAY['Setting up a 5.1 orchestral recording in a concert hall.','Capturing immersive ambience for a film-score session.','Balancing front and rear arrays for a surround live album.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='317c0628-10c1-53b7-b07f-5fdd11e08dfd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Front–rear array spacing'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '317c0628-10c1-53b7-b07f-5fdd11e08dfd','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='317c0628-10c1-53b7-b07f-5fdd11e08dfd' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '59bf38c1-1a32-5e86-b23d-855caf34d079','Gallery microphone','A microphone placed in the gallery or balcony of a concert hall or theatre, well back and above the performers, to capture the reverberant field, sense of hall, and sometimes audience response. Set far from the stage, it is a distant ambience pickup that is blended in at a low level and usually delayed to sit behind the main array.','This is a microphone put up in the balcony seats of a hall. It sits far from the stage and high up. From there it captures the room''s echo and the feel of the space. Engineers mix it in quietly and delay it to sit behind the main microphones.','It exists to add hall ambience, depth, and a sense of the venue to a recording, and at times audience atmosphere, without cluttering the stage area.','For a live album an engineer rigs a pair of mics on the balcony rail, delays them to the main array, and rides them up between numbers for applause and room.','Ambience Miking',ARRAY['Ambience microphone','Fly-rail microphone','Front–rear array spacing','Distance-to-delay conversion','Reverberation']::text[],ARRAY['Mixing the gallery mic too loud, which washes the recording in reverb and dulls clarity.','Leaving it undelayed, so distant ambience arrives out of step with the main array.','UNSAFE: Rigging a mic on a balcony rail over the audience below without a safety cable and a secure, load-rated mount.']::text[],ARRAY['Capturing hall ambience and applause for a live concert album.','Adding depth and room to a dry main-array orchestral recording.','Recording audience atmosphere for a broadcast.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='59bf38c1-1a32-5e86-b23d-855caf34d079' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Gallery microphone'),'[^a-z0-9]','','g'));
