INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3a4d264b-2122-5849-a60f-9374aa46a020','Geometric spot delay','A method of setting the delay applied to a spot (accent) microphone by calculating it from the measured physical distance between that microphone and the main array, divided by the speed of sound (about 343 m/s at 20 degrees Celsius), rather than deriving it from an acoustic arrival measurement. Time-aligning the closer spot signal to the main array''s later arrival reduces comb filtering and preserves the instrument''s natural timbre when the two are summed.','A spot mic sits close to one instrument. The main mics stand farther back, so sound reaches them later. You measure the gap between the two mic spots. Then you divide that distance by the speed of sound. That gives a delay in milliseconds for the close mic. Adding it lines the two signals up in time.','It exists to time-align a close spot mic with the more distant main array using simple geometry, so that summing the two does not cause the phase cancellation and comb filtering that smears tone.','An engineer measures each spot mic''s distance to the main tree, divides by the speed of sound to get a delay in milliseconds, and enters that value in the console or DAW delay.','Spot-mic alignment',ARRAY['Spot microphone','Main array','Measured-arrival spot delay','Comb filtering','Delay compensation','Speed of sound']::text[],ARRAY['Measuring the distance carelessly, so the calculated delay is wrong and comb filtering remains.','Forgetting that real sound paths, via floor reflections and mic directivity, differ from a straight-line measurement, so a purely geometric figure may still need fine tuning.','Delaying the wrong microphone, the main array instead of the spot, which pushes the timing the wrong way.']::text[],ARRAY['Time-aligning a woodwind spot mic to a Decca Tree in an orchestral session.','Setting delays for section spot mics in a large ensemble recording.','Aligning a soloist accent mic to the main pair before mixing.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3a4d264b-2122-5849-a60f-9374aa46a020' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Geometric spot delay'),'[^a-z0-9]','','g'));
