INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'd36c412c-4755-563b-946e-d405590b1405','Haas-window integration','Setting a spot or supporting microphone''s delay so its signal arrives within the precedence (Haas) fusion window relative to the main array, broadly a few milliseconds up to a few tens of milliseconds for musical signals, so the ear fuses the two into a single event localized toward the main array. This lets the spot mic add detail and level without pulling the perceived image toward the closer source or creating an audible echo.','When two copies of a sound arrive close together, your ears blend them into one. They place that sound where the first copy arrives. This blending window is named after Helmut Haas. Engineers set a spot mic''s delay to stay inside it. Then the spot mic adds detail but does not shift where the sound seems to come from.','It exists to let spot mics reinforce clarity and level while the main array still defines the stereo image, by keeping the spot''s timing inside the range where the ear fuses the two arrivals.','An engineer nudges each spot mic''s delay so it lands just after the main array arrival, checking that the image stays anchored to the main pair and no echo appears.','Spot-mic alignment',ARRAY['Precedence effect','Haas effect','Spot microphone','Main array','Geometric spot delay','Comb filtering']::text[],ARRAY['Assuming any delay under about thirty milliseconds sounds identical, when timbre and image shift well before that.','Letting the delay grow past the fusion window, so the spot mic becomes an audible slap echo.','UNSAFE: Turning monitors up loud to judge subtle timing, risking hearing damage; keep levels moderate and follow NIOSH and OSHA exposure limits.']::text[],ARRAY['Blending a soloist accent mic into an orchestral main pair.','Tucking choir spot mics behind a main array without smearing the image.','Adding a section spot mic that reinforces detail but keeps the main array in control.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='d36c412c-4755-563b-946e-d405590b1405' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Haas-window integration'),'[^a-z0-9]','','g'));
