INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'cd779f02-2924-58b5-bec3-f88fb140b922','Hall-return microphone','A microphone, usually a pair, placed well out in the auditorium away from the performers to capture the hall''s diffuse reverberant field and late reflections, which are then returned into the mix to add depth and spaciousness. Because its signal is dominated by reverberation rather than direct sound, it is blended at a low level relative to the main array.','A concert hall adds its own echo and sense of space to music. A hall-return mic sits far out in the room to catch that. It picks up mostly reflected sound, not the direct notes. Engineers add a little of it to the mix. This makes the recording feel open and roomy.','It exists to capture the room''s reverberant tail so the mix gains a natural sense of depth and envelopment that close and main mics alone cannot provide.','An engineer sets a pair of mics far back in the hall, then blends a small amount under the main array to add air and space without blurring detail.','Ambience miking',ARRAY['Ambience microphone','Mid-hall microphone','Main array','Reverberation','Hamasaki ambience layer','Main-plus-ambience array']::text[],ARRAY['Adding too much hall return, which washes out clarity and pushes the ensemble far away.','Placing it where strong early reflections or audience noise dominate instead of smooth reverberation.','Ignoring the extra travel time, so the distant mic smears transients when summed with the main array.']::text[],ARRAY['Recording a symphony orchestra in a reverberant concert hall.','Capturing choir and organ in a cathedral for a sense of space.','Adding room depth to a live classical broadcast.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='cd779f02-2924-58b5-bec3-f88fb140b922' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hall-return microphone'),'[^a-z0-9]','','g'));
