SELECT 'cd779f02-2924-58b5-bec3-f88fb140b922','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='cd779f02-2924-58b5-bec3-f88fb140b922' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '673dae15-ffd2-5d6e-b5f9-ef87b9430df2','Hamasaki ambience layer','The diffuse ambience component captured by a Hamasaki Square, an array of four figure-of-eight microphones arranged in a square (roughly 1.8 to 4 metres per side) with their nulls facing the stage so they reject direct sound and pick up lateral reverberation. Developed by Kimio Hamasaki at NHK, this layer is routed to the surround, and sometimes front, channels to add enveloping room sound in stereo, surround, and immersive productions.','The Hamasaki Square is a set of four figure-eight mics placed in a square. Kimio Hamasaki designed it at the Japanese broadcaster NHK. The mics point their dead sides at the stage. So they reject direct sound and catch echoes coming from the sides. This side reverb is added to the mix to make it feel wrapped around you.','It exists to capture the sideways-arriving reverberation that creates a strong sense of envelopment, feeding surround and immersive mixes with diffuse ambience kept separate from the direct sound.','An engineer rigs four figure-of-eight mics in a square behind or above the main array, aims the nulls at the stage, and routes them to the surround channels at a level under the main pickup.','Ambience miking',ARRAY['Hamasaki Square','Ambience microphone','Figure-of-eight','Main array','Height-layer decorrelation','Hall-return microphone']::text[],ARRAY['Aiming the figure-of-eight faces toward the stage, so direct sound leaks into the ambience layer.','Confusing the Hamasaki Square with a coincident stereo pair; it is a spaced, diffuse-field array.','Spacing or level set so high that the ambience blurs the main image instead of supporting it.']::text[],ARRAY['Capturing surround ambience for a concert-hall orchestral recording.','Feeding an enveloping room layer into a Dolby Atmos or 5.1 classical mix.','Adding lateral reverberation to a broadcast of a live choral performance.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='673dae15-ffd2-5d6e-b5f9-ef87b9430df2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Hamasaki ambience layer'),'[^a-z0-9]','','g'));
