INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b958aea5-cc43-5756-821c-5f1db4559d91','Height-layer decorrelation','Reducing the correlation between the height-channel signals and the ear-level signals, and among the height channels themselves, in immersive recording, so the upper layer adds spaciousness and vertical envelopment without pulling the localized image upward. Because the precedence effect does not operate reliably in the vertical plane, decorrelation combined with a reduced height level is used to keep sources anchored at ear level while the height layer supplies diffuse reflections.','Immersive audio adds speakers above the listener. If the height signals copy the main signals too closely, sounds seem to float upward. To stop that, engineers make the height signals different from the main ones. This is called decorrelation. The height layer then adds a feeling of open space overhead without moving where sounds sit.','It exists to give an immersive mix a convincing sense of height and openness while keeping instruments localized at ear level, since the ear uses level and difference, not timing, to place vertical sound.','An engineer feeds the height layer from separate spaced or ambience mics rather than copies of the main array, and lowers its level so the vertical image adds air without lifting sources.','Immersive miking',ARRAY['Decorrelation','Hamasaki ambience layer','Immersive audio','Ambience microphone','Precedence effect','Main array']::text[],ARRAY['Feeding the height speakers with a delayed copy of the main mix, which lifts the image and sounds unnatural.','Assuming the precedence effect fixes vertical localization the way it does horizontally.','Setting the height layer too loud, so instruments appear to come from the ceiling.']::text[],ARRAY['Recording an orchestra for Dolby Atmos with a dedicated height array.','Building the upper layer of a 7.1.4 immersive classical mix.','Adding overhead ambience to a live concert capture for immersive playback.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b958aea5-cc43-5756-821c-5f1db4559d91' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Height-layer decorrelation'),'[^a-z0-9]','','g'));
