INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '13b4dc92-2af8-561c-a2ed-64ca8cba03ef','Image-width mismatch','A discrepancy in the perceived stereo width contributed by different microphone systems in a multi-mic setup, for example a main array capturing a wide image while spot or ambience mics present a narrower or differently panned image, so the combined result has inconsistent or unstable stereo imaging. It can also mean a mismatch between the width captured and the width intended for the target playback format.','In stereo, the sound spreads between the left and right speakers. Different mic setups can spread it by different amounts. If a main pair sounds wide but the spot mics sound narrow, they fight each other. The result is an uneven or shaky stereo picture. Matching the widths keeps the image steady.','Naming this fault helps engineers diagnose why a multi-mic image sounds smeared, lopsided, or unstable, so they can match panning, mic technique, and level between systems.','An engineer checks that spot-mic panning matches each source''s position in the main array, and that ambience width supports rather than fights the main image.','Stereo imaging',ARRAY['Stereo image width','Main array','Spot microphone','Interchannel level difference','Interchannel time difference','Panning']::text[],ARRAY['Panning spot mics to positions that disagree with where the source sits in the main array.','Mixing a very wide main technique with narrow spot mics and getting a hollow center.','Judging width only in mono or on one speaker set, missing the mismatch until playback.']::text[],ARRAY['Combining a wide AB main pair with center-panned solo spot mics.','Matching ambience width to the main image in a surround upmix.','Troubleshooting an unstable stereo image in an orchestral mix.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='13b4dc92-2af8-561c-a2ed-64ca8cba03ef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Image-width mismatch'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '13b4dc92-2af8-561c-a2ed-64ca8cba03ef','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='13b4dc92-2af8-561c-a2ed-64ca8cba03ef' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9614ce99-d3d0-5100-b341-e42fb5a82aa0','Main-array arrival reference','Using the time at which sound reaches the main microphone array as the fixed timing reference to which all spot, support, and ambience microphones are aligned. Because the main array defines the stereo image, delays are added to closer mics so their arrivals match this reference, preserving natural timbre and avoiding comb filtering.','The main mics set the stereo picture for a recording. So their timing is treated as the fixed timing reference. Every closer mic captures its sound earlier. Engineers delay those mics to match the main mics. The main array''s arrival time is what everything lines up to.','It exists to give a multi-mic setup one consistent timing anchor, so spot and ambience mics reinforce the main image instead of fighting it with phase errors.','An engineer notes the main array position, then computes or measures each other mic''s delay relative to when the main array hears the same source.','Spot-mic alignment',ARRAY['Main array','Spot microphone','Geometric spot delay','Measured-arrival spot delay','Delay compensation','Comb filtering']::text[],ARRAY['Aligning spot mics to each other instead of to the single main-array reference.','Forgetting that a moving or repositioned main array changes the reference for every spot mic.','Treating a close mic as the reference, which forces the wrong direction of delay.']::text[],ARRAY['Planning delay compensation around a Decca Tree in an orchestral session.','Aligning choir and soloist mics to the main pair.','Setting up a session template where all spots reference the main array.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9614ce99-d3d0-5100-b341-e42fb5a82aa0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Main-array arrival reference'),'[^a-z0-9]','','g'));
