SELECT '9614ce99-d3d0-5100-b341-e42fb5a82aa0','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9614ce99-d3d0-5100-b341-e42fb5a82aa0' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'de2bfffe-f460-5fa6-85fb-890b1e34d0b8','Main-array lag','The time delay by which sound arrives at the more distant main array after it reaches a closer spot microphone, arising from the extra path length divided by the speed of sound (about 2.9 milliseconds per metre, roughly 0.9 milliseconds per foot). This lag is what spot-mic delay compensation is designed to offset so the two signals sum coherently.','The main mics stand farther from the players than the spot mics. Sound travels at a fixed speed, so it reaches the main mics later. That extra time is the main-array lag. It is about three milliseconds for every metre of extra distance. Engineers delay the spot mics by this amount to match.','Understanding this lag tells the engineer exactly how much to delay each spot mic so its signal lines up with the main array and avoids comb filtering.','An engineer estimates the lag from the distance between a spot mic and the main array, then applies that delay to the spot channel.','Spot-mic alignment',ARRAY['Main array','Spot microphone','Geometric spot delay','Speed of sound','Delay compensation','Comb filtering']::text[],ARRAY['Assuming the lag is negligible, so summed mics comb-filter and sound hollow.','Using the wrong speed of sound, for instance ignoring room temperature, in a precise calculation.','Confusing the direction: the main array lags the spot mic, not the other way around.']::text[],ARRAY['Calculating how much to delay a spot mic in an orchestral recording.','Explaining why distant and close mics sound phasey when summed.','Teaching delay compensation on a large ensemble session.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='de2bfffe-f460-5fa6-85fb-890b1e34d0b8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Main-array lag'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'de2bfffe-f460-5fa6-85fb-890b1e34d0b8','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='de2bfffe-f460-5fa6-85fb-890b1e34d0b8' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1874baf8-029e-556a-a153-26738b1149e5','Main-led orchestral mix','An orchestral mixing approach in which the main microphone array, such as a Decca Tree or main pair, forms the foundation of the sound and defines the stereo image, with spot and ambience microphones added only in support at lower levels. The result prioritizes the natural balance, depth, and timbre captured by the main array over close-mic detail.','In this approach, the main mics carry the whole orchestra. They set the balance and the stereo picture. Spot mics are added only a little, to help weak or buried parts. The room mics add space. The main array leads, and everything else supports it.','It exists to keep an orchestral recording sounding natural and cohesive by letting the main array do most of the work, using spots only to correct balance rather than to rebuild the sound.','An engineer builds the mix by first setting the main array, then adding just enough spot-mic level to lift inner detail without taking over.','Orchestral balancing',ARRAY['Main array','Decca Tree','Spot microphone','Main-to-spot ratio','Ambience microphone','Natural-arrival preservation']::text[],ARRAY['Pushing spot mics so hard that the natural main-array balance is lost.','Neglecting main-array placement, then trying to fix everything with spot mics.','Adding spots without delay compensation, which muddies the main-led foundation.']::text[],ARRAY['Mixing a classical symphony recording for a natural concert-hall sound.','Balancing a film-score orchestral session around the Decca Tree.','Teaching students to start an orchestral mix from the main pair.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1874baf8-029e-556a-a153-26738b1149e5' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Main-led orchestral mix'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '1874baf8-029e-556a-a153-26738b1149e5','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1874baf8-029e-556a-a153-26738b1149e5' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '93befd82-be5c-5b61-ad91-5ae2ab55000e','Main-plus-ambience array','A microphone configuration that pairs a main array, which captures the direct sound and stereo image, with a separate set of ambience microphones placed farther out to capture the room''s diffuse reverberation. Blending the two yields a recording with both clear imaging and natural spaciousness, and it is the basis of many surround and immersive pickups.','This setup uses two groups of mics. The main group sits close enough to catch clear, direct sound. The ambience group sits farther out to catch the room''s echo. Mixing them gives you both a sharp picture and a sense of space. It is a common way to record in a good-sounding hall.','It exists to separate direct sound from room sound so the engineer can control clarity and spaciousness independently in the mix.','An engineer sets a main array for the image and an ambience array, such as a Hamasaki Square or spaced room pair, for depth, then balances the two.','Ambience miking',ARRAY['Main array','Ambience microphone','Hamasaki ambience layer','Hall-return microphone','Mid-hall microphone','Decca Tree']::text[],ARRAY['Placing the ambience mics so close that they duplicate the main array instead of adding real room sound.','Letting the ambience level rise until the image loses focus.','Ignoring the ambience array''s longer travel time, causing smeared transients when summed.']::text[],ARRAY['Recording an orchestra for both stereo and surround release.','Capturing a choir with clear imaging plus cathedral ambience.','Building an immersive classical pickup with main and room layers.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='93befd82-be5c-5b61-ad91-5ae2ab55000e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Main-plus-ambience array'),'[^a-z0-9]','','g'));
