INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'b85a3f37-8fc6-5088-8e30-8dcb039f5fea','Main-to-spot ratio','The level balance between the main array and the spot (accent) microphones in a mix, usually expressed as how much quieter the spot mics sit beneath the main array. It governs how natural versus close and detailed the ensemble sounds, with the main array typically dominant and spots added only for support.','This is the balance between the main mics and the close spot mics. The main mics usually stay loudest. The spot mics are added underneath, just enough to add detail. Turn spots up and the sound gets close and detailed. Turn them down and it sounds more natural and roomy.','It exists as the key balance control for shaping how close, detailed, or natural a main-led ensemble recording sounds.','An engineer rides spot-mic faders under the main array, adding a few decibels only where a section or soloist needs help.','Orchestral balancing',ARRAY['Main array','Spot microphone','Main-led orchestral mix','Ambience microphone','Delay compensation','Natural-arrival preservation']::text[],ARRAY['Over-relying on spot mics, giving an unnatural, over-close sound.','Adding spot level without delay compensation, causing comb filtering.','Setting the ratio in solo instead of in the full context of the main array.']::text[],ARRAY['Balancing woodwind spot mics under a Decca Tree.','Deciding how present a concerto soloist should sit against the orchestra.','Adjusting section detail in an orchestral mix.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='b85a3f37-8fc6-5088-8e30-8dcb039f5fea' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Main-to-spot ratio'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'b85a3f37-8fc6-5088-8e30-8dcb039f5fea','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='b85a3f37-8fc6-5088-8e30-8dcb039f5fea' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e05c7fb6-b823-5e6f-a3d2-f944b3c01f5f','Measured-arrival spot delay','Setting a spot microphone''s delay from the acoustically measured arrival-time difference between that mic and the main array, captured with a test impulse, clap, or cross-correlation, rather than from a straight-line distance calculation. Because it accounts for the real propagation path, mic directivity, and reflections, it can align the signals more accurately than a purely geometric estimate.','Here you measure the real time gap between a spot mic and the main mics. You might clap or send a test sound and see how long it takes to reach each. Then you delay the spot mic by that measured amount. This can be more exact than just measuring distance, because it uses the actual sound.','It exists to time-align spot mics using the true measured arrival time, giving tighter phase coherence than a geometric distance calculation when the sound path is complex.','An engineer records a clap or test tone, finds the delay between the spot and main captures in the DAW, and applies that offset to the spot channel.','Spot-mic alignment',ARRAY['Spot microphone','Main array','Geometric spot delay','Delay compensation','Comb filtering','Cross-correlation']::text[],ARRAY['Measuring with a source not at the instrument''s real position, giving the wrong delay.','Trusting a single noisy measurement instead of averaging or checking it.','Aligning to a reflection instead of the direct arrival in the measurement.']::text[],ARRAY['Time-aligning spot mics in a complex hall where geometry alone is unreliable.','Using a clap test to set delays on a large orchestral rig.','Fine-tuning spot delays in post using visual waveform alignment.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e05c7fb6-b823-5e6f-a3d2-f944b3c01f5f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Measured-arrival spot delay'),'[^a-z0-9]','','g'));
