SELECT 'e05c7fb6-b823-5e6f-a3d2-f944b3c01f5f','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e05c7fb6-b823-5e6f-a3d2-f944b3c01f5f' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f15c60fe-cec4-59e1-9f18-7a944a6c3806','Mid-hall microphone','An ambience microphone, or pair, placed around the middle of the auditorium, between the main array near the stage and the rear of the hall, to capture a blend of direct sound and developing reverberation. It provides a room perspective that is more reverberant than the main array but less diffuse than microphones at the very back.','This mic sits partway back in the hall, not up front and not at the rear. It catches some direct sound plus the room''s growing echo. That gives a middle-distance view of the performance. Engineers blend it in to add depth without losing all clarity.','It exists to offer an intermediate room perspective, filling the gap between the close, detailed main array and the very diffuse rear ambience mics.','An engineer places a mic pair mid-auditorium and blends it under the main array to add hall depth while keeping some definition.','Ambience miking',ARRAY['Ambience microphone','Hall-return microphone','Main array','Main-plus-ambience array','Reverberation','Hamasaki ambience layer']::text[],ARRAY['Placing it at a spot dominated by a single strong reflection, giving a colored sound.','Adding too much level, so the mid-hall blur overtakes the main image.','Ignoring its travel-time delay when summing with the main array.']::text[],ARRAY['Capturing an orchestra where a mid-hall pair adds depth.','Blending room perspectives for a live classical recording.','Giving a mix a choice of near, mid, and far ambience layers.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f15c60fe-cec4-59e1-9f18-7a944a6c3806' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Mid-hall microphone'),'[^a-z0-9]','','g'));
