WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f15c60fe-cec4-59e1-9f18-7a944a6c3806' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8eddd164-bc82-5861-951c-d4ed75afd1ff','Natural-arrival preservation','An approach to multi-mic recording that keeps the natural time-of-arrival relationships between microphones intact, either by delaying spot mics to match the main array or by choosing placements that avoid destructive phase differences, so the summed result retains the ensemble''s true timbre and depth without comb filtering. It treats the main array''s timing as the natural reference and aligns supporting mics to it.','Sound reaches each mic at a slightly different time. If you ignore that, mixing the mics can dull the tone. Preserving natural arrival means keeping those timings sensible. Usually you delay the close mics to match the main mics. This keeps the true tone and depth of the ensemble.','It exists to protect timbre and depth in a multi-mic mix by respecting the real arrival times of sound at each microphone rather than summing them blindly.','An engineer applies delay compensation to spot mics and checks summed timbre, making sure the blend sounds as natural as the main array alone.','Spot-mic alignment',ARRAY['Main array','Spot microphone','Delay compensation','Comb filtering','Main-array arrival reference','Geometric spot delay']::text[],ARRAY['Summing close and distant mics with no delay, causing hollow comb-filtered tone.','Over-delaying spots past the fusion window, creating audible echo.','Assuming soloed mics that sound fine will also sum cleanly without alignment.']::text[],ARRAY['Preserving timbre when adding spot mics to an orchestral main pair.','Setting up delay compensation on a session to avoid phase coloring.','Teaching why blind multi-miking dulls an ensemble''s sound.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8eddd164-bc82-5861-951c-d4ed75afd1ff' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Natural-arrival preservation'),'[^a-z0-9]','','g'));
