SELECT '8eddd164-bc82-5861-951c-d4ed75afd1ff','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8eddd164-bc82-5861-951c-d4ed75afd1ff' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '8c260290-1673-5d1d-b36f-029059ea208d','Natural-reverb return','A mix channel or bus that carries the natural reverberation of the recording space itself—captured by the main array, dedicated room/ambience microphones, or the diffuse-field portion of an ensemble pickup—rather than reverb produced by an artificial processor. It is blended back with the direct sound to restore the venue''s own acoustic signature, depth, and sense of distance.','A concert hall adds its own echo to the sound. Room mics catch that natural echo. The return is the mixer channel that brings it back into the mix. It makes a recording feel like a real space, not a fake effect.','It exists to reintroduce the venue''s own acoustic tail and spaciousness into a mix, preserving a realistic sense of room and distance without resorting to synthetic reverberation.','An engineer routes room or ambience microphones to a dedicated return and rides its level against the close and main mics to set how distant and reverberant the ensemble sounds.','Ambience miking',ARRAY['Room microphone','Main microphone array','Ambience microphone','Orchestra outrigger','Decca Tree']::text[],ARRAY['Confusing the natural-reverb return with an artificial reverb send and stacking a plug-in on top until the space sounds unnatural.','Setting the room mics too high in the mix, which pushes the ensemble far away and blurs detail.','Ignoring the time/delay relationship between room mics and the main array, causing comb filtering.']::text[],ARRAY['Mixing an orchestral session and blending hall ambience under the main pair.','Recording a choir in a church and using the natural reverb return for depth.','Balancing room tone against close mics on a live ensemble recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='8c260290-1673-5d1d-b36f-029059ea208d' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Natural-reverb return'),'[^a-z0-9]','','g'));
