WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='8c260290-1673-5d1d-b36f-029059ea208d' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bff2e1d0-cbff-5727-a3ef-5a1dff125912','Near-flank microphone','A flanking (outrigger-type) microphone placed relatively close to the main stereo array or to the inner edge of an ensemble''s flank, rather than at the wide extremes of the stage. It widens and fills the image between the main pair and the far sides while keeping time-of-arrival differences with the main array modest.','Flank mics sit out to the sides of an ensemble to widen the sound. A near-flank mic sits closer in, not way out at the edges. It fills the gap between the center mics and the far sides. This keeps the stereo image even, with no hole in the middle.','It exists to bridge the image between a central main array and wide outrigger mics, reducing a hole-in-the-middle effect while adding controlled width.','An engineer adds a near-flank mic a short distance to the side of the main array, trimming its level and delay so it supports width without smearing the center image.','Flank miking',ARRAY['Orchestra flank microphone','Orchestra outrigger','Main microphone array','Decca Tree','Spot microphone']::text[],ARRAY['Spacing the near-flank mic too far from the main array, creating a gap and an unstable center image.','Forgetting to time-align or delay it, which introduces comb filtering with the main pair.','Treating it as a close spot mic and pushing it too loud, collapsing the natural perspective.']::text[],ARRAY['Filling the image between a Decca Tree and wide outriggers on a large orchestra.','Widening a chamber-ensemble recording without losing the center.','Supporting the sides of a choir seated behind an orchestra.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bff2e1d0-cbff-5727-a3ef-5a1dff125912' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Near-flank microphone'),'[^a-z0-9]','','g'));
