SELECT 'bff2e1d0-cbff-5727-a3ef-5a1dff125912','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bff2e1d0-cbff-5727-a3ef-5a1dff125912' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1047a9fd-d04d-5207-bdc3-32856ec6bdcd','Nearest-main delay reference','The practice of choosing the closest main-array microphone as the timing reference to which a spot or support microphone is delayed, so the spot mic''s signal arrives no earlier than the main pickup. Aligning to the nearest main channel keeps the spot mic behind the main array in time, preserving the precedence-based localization the main pair establishes.','In a big recording, close spot mics hear the sound first. That can pull the image toward the spot mic. Engineers delay each spot mic to the nearest main mic. Now the main mics arrive first and set where the sound seems to come from.','It exists to keep support mics from arriving ahead of the main array, so the ear still localizes to the main pickup under the precedence effect and the stereo image stays coherent.','An engineer measures or calculates the delay from each spot mic to the nearest main mic and applies it in the console or DAW so spot mics fall slightly behind the mains.','Time alignment',ARRAY['Spot microphone','Precedence effect','Main microphone array','Perceptual spot delay','Decca Tree']::text[],ARRAY['Delaying spot mics to the wrong reference, so they still lead the main array and pull the image.','Aligning to exact geometric distance and ignoring the perceptual precedence window.','Skipping delay entirely, letting close mics dominate localization and cause comb filtering.']::text[],ARRAY['Time-aligning woodwind spot mics to the main tree in an orchestral session.','Setting delay on a soloist mic relative to the nearest main-pair channel.','Aligning section mics behind an AB main array in a live classical broadcast.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1047a9fd-d04d-5207-bdc3-32856ec6bdcd' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Nearest-main delay reference'),'[^a-z0-9]','','g'));
