WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1047a9fd-d04d-5207-bdc3-32856ec6bdcd' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '344c846a-da0a-5734-998e-49c6739560d9','OCT','The Optimized Cardioid Triangle, a front-array microphone technique for L/C/R developed by Günther Theile, using a forward-facing cardioid for the center channel placed about 8 cm ahead of two outward-pointing supercardioids for left and right; the left-right spacing (roughly 40 to 90 cm) sets the recording angle. It gives strong channel separation and stable localization with low crosstalk and forms the front layer of OCT Surround and OCT-3D arrays.','OCT stands for Optimized Cardioid Triangle. It is a way to set up front microphones for surround sound. One cardioid mic faces forward for the center. Two side mics point outward for left and right. The layout gives clear, well-separated channels with little overlap.','It exists to capture a stable, well-separated front L/C/R image for surround and immersive recordings while minimizing crosstalk between channels.','An engineer mounts the center cardioid about 8 cm ahead of two supercardioids on a bar, sets the left-right spacing for the desired width, and uses it as the front layer of a surround setup.','Surround miking',ARRAY['OCT-3D','ORTF-2plus2','Decca Tree','Orchestra outrigger','Main microphone array']::text[],ARRAY['Using cardioids instead of supercardioids on the sides, which raises crosstalk and blurs separation.','Setting the left-right spacing without regard to the recording angle, so the ensemble ends up too wide or too narrow.','Omitting the optional low-frequency omni mics, leaving the recording thin because the directional capsules lose bass.']::text[],ARRAY['Recording an orchestra front image for a 5.1 surround release.','Building the front layer of an OCT-3D immersive array.','Capturing a stable L/C/R image in a concert hall.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='344c846a-da0a-5734-998e-49c6739560d9' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('OCT'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '344c846a-da0a-5734-998e-49c6739560d9','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='344c846a-da0a-5734-998e-49c6739560d9' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '3ac9d5df-9888-5ff2-915e-7920acf5cbbb','OCT-3D','An immersive extension of the OCT Surround array by Theile/Schoeps that adds a height layer of four upward-tilted supercardioid microphones above the OCT Surround base (the OCT front plus two surround cardioids), producing recordings for 3D formats such as 5.1.4, 7.1.4, 9.1 and 22.2. The base layer provides the horizontal L/C/R and surround image while the height mics capture overhead spatial information.','OCT-3D adds height to the OCT surround setup. It stacks four extra mics that tilt upward. These catch sound from above, like reflections off a high ceiling. The result works for 3D audio formats that use height speakers.','It exists to add a vertical, overhead dimension to OCT surround recordings so they can be played back on immersive systems that include height channels.','An engineer mounts four upward-facing supercardioids above an OCT Surround array and routes them to the height channels of a 3D mix.','Surround miking',ARRAY['OCT','ORTF-2plus2','Main microphone array','Orchestra outrigger','Decca Tree']::text[],ARRAY['Aiming the height mics at the ensemble instead of upward, capturing direct sound twice and causing comb filtering.','Mismatching capsule types between layers, which makes the height image sound disconnected.','Routing the height layer too loud, exaggerating the ceiling and destabilizing the front image.']::text[],ARRAY['Recording a symphony for a Dolby Atmos or Auro-3D release.','Capturing hall height reflections above an OCT surround base.','Producing immersive 7.1.4 content of a live concert.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='3ac9d5df-9888-5ff2-915e-7920acf5cbbb' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('OCT-3D'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '3ac9d5df-9888-5ff2-915e-7920acf5cbbb','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='3ac9d5df-9888-5ff2-915e-7920acf5cbbb' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '86f30cff-5f0f-52f4-b9bf-0e687a07590e','ORTF-2plus2','A four-channel immersive microphone technique from Schoeps using two lower supercardioids and two upward-angled supercardioids in an ORTF-derived arrangement, routed to two adjacent main channels plus their height channels (for example L, R and Lh, Rh). It works as an immersive spot or atmosphere pickup, capturing a source with both horizontal and vertical extension.','ORTF-2plus2 is a four-mic setup for 3D sound. Two mics sit low and two tilt upward. They feed a left and right pair plus matching height speakers. It captures both the width and the height of a scene, like crowd noise at a stadium.','It exists to capture atmosphere or a sound source with both width and height in one compact array, feeding the front and height channels of an immersive mix.','A location engineer deploys the four-capsule array to record ambience—such as stadium crowd or nature atmos—and routes the lower and upper pairs to the L/R and height channels.','Surround miking',ARRAY['OCT-3D','OCT','Ambience microphone','Main microphone array','Natural-reverb return']::text[],ARRAY['Routing all four capsules to the same stereo pair, throwing away the height information.','Confusing it with a flat ORTF stereo pair and ignoring the vertical layer.','Placing it as a close spot on a soloist, where its wide atmos pickup adds unwanted room.']::text[],ARRAY['Recording crowd atmosphere at a stadium sporting event for a 3D broadcast.','Capturing immersive nature or city ambience for film.','Adding a height-aware atmos layer to a concert recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='86f30cff-5f0f-52f4-b9bf-0e687a07590e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('ORTF-2plus2'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '86f30cff-5f0f-52f4-b9bf-0e687a07590e','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='86f30cff-5f0f-52f4-b9bf-0e687a07590e' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'efd6469e-3764-55d9-bfb0-a248f907fa5c','Offstage ensemble microphone','A microphone or small array dedicated to an ensemble or group of players positioned offstage or otherwise remote from the main array—such as an offstage brass group, chorus, or banda called for in a score—so that its part is captured at usable level and with a distance perspective that matches the music. It supports the main pickup for sources the primary array cannot balance because of their remote location.','Some music calls for players placed offstage, like a hidden brass group. The main mics are too far to catch them well. An offstage mic is placed near that group. It brings their part into the mix at the right level and distance.','It exists to capture ensembles deliberately placed away from the stage so their contribution reaches the mix with a controlled level and a sense of distance that matches the score.','An engineer runs a mic or small pair to an offstage choir or brass group and blends it with reverb or delay so it sits behind the on-stage ensemble.','Ensemble miking',ARRAY['Spot microphone','Natural-reverb return','Main microphone array','Ambience microphone','Orchestra flank microphone']::text[],ARRAY['Mixing the offstage mic too close and loud, breaking the illusion that the players are distant.','Forgetting time or delay alignment, so the offstage part fights the main array.','UNSAFE: Running long mic cables across dark backstage walkways and stairs without taping or matting them down, creating a trip-and-fall hazard in the wings.']::text[],ARRAY['Capturing an offstage brass fanfare in a Mahler or Respighi work.','Miking an offstage chorus in an opera production.','Recording a distant banda for a live concert broadcast.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='efd6469e-3764-55d9-bfb0-a248f907fa5c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Offstage ensemble microphone'),'[^a-z0-9]','','g'));
