INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'daf219ed-2441-5dde-af41-8bef3e878c16','Optimized Stereo Signal technique','A near-coincident stereo technique developed by Jürg Jecklin (Optimum Stereo Signal, OSS) using two omnidirectional microphones spaced about 16.5 cm apart with a sound-absorbing baffle—the Jecklin disk, roughly 30 cm in diameter—placed between them. The disk introduces frequency-dependent acoustic separation and shading so the pair combines interchannel time and level differences for a natural stereo image on loudspeakers.','OSS stands for Optimized Stereo Signal, a stereo recording method. Two microphones that pick up sound from all sides sit about 16 centimeters apart. A padded disk stands between them like a small wall. The disk shades the sound, giving a natural, spacious stereo image.','It exists to give spaced omnidirectional microphones some of the channel separation of a baffled, head-like system, producing a natural, spacious stereo image suited to loudspeaker playback.','An engineer mounts two omnis on either side of a Jecklin disk about 16.5 cm apart and uses the array as a main pickup for solo instruments, chamber groups, or room ambience.','Stereo miking',ARRAY['Main microphone array','Near-flank microphone','Ambience microphone','Decca Tree','Perspective mismatch']::text[],ARRAY['Using directional mics instead of the required omnidirectional capsules, which defeats the technique.','Changing the 16.5 cm spacing or disk size, which alters the intended stereo balance.','Expecting coincident-pair mono compatibility; the spacing causes phase differences that can comb-filter in mono.']::text[],ARRAY['Recording a solo piano or guitar with a natural stereo spread.','Capturing a string quartet with a single main pair.','Recording room ambience with a spacious image.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='daf219ed-2441-5dde-af41-8bef3e878c16' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Optimized Stereo Signal technique'),'[^a-z0-9]','','g'));
