SELECT 'daf219ed-2441-5dde-af41-8bef3e878c16','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='daf219ed-2441-5dde-af41-8bef3e878c16' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e8e06234-0d07-523d-a4fe-14d04986fbc8','Orchestra flank microphone','A microphone placed to one flank (side) of an orchestra to capture the outer sections and extend the recorded image beyond the main array. Functionally similar to an outrigger, it reinforces the left or right extreme of the ensemble and improves coverage of players the central main array captures weakly.','The flanks are the far left and right sides of an orchestra. A flank mic sits out at one of those sides. It picks up the outer players and widens the sound. It fills in parts the center mics catch too faintly.','It exists to extend stereo width and reinforce the outer sections of a large ensemble that a central main array cannot fully balance.','An engineer places flank mics to the left and right of the orchestra, trims and delays them to the main array, and blends them for width and section support.','Flank miking',ARRAY['Orchestra outrigger','Near-flank microphone','Main microphone array','Decca Tree','Spot microphone']::text[],ARRAY['Placing flank mics so wide that the center of the image develops a hole.','Not delaying them to the main array, causing comb filtering and a pulled image.','Using them as loud close spots, which flattens the natural front-to-back perspective.']::text[],ARRAY['Widening a symphony recording beyond a Decca Tree.','Reinforcing first and second violins on opposite flanks.','Supporting the outer edges of a large choir-and-orchestra setup.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e8e06234-0d07-523d-a4fe-14d04986fbc8' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestra flank microphone'),'[^a-z0-9]','','g'));
