SELECT 'e8e06234-0d07-523d-a4fe-14d04986fbc8','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e8e06234-0d07-523d-a4fe-14d04986fbc8' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '86d8bf78-2c27-5dc9-a5f9-56bb5935d258','Orchestra outrigger','One of a pair of flanking microphones—classically omnidirectional Neumann M50s in the Decca system—placed wide to the left and right of a main array such as a Decca Tree, to broaden the stereo image and add spaciousness. Outriggers are typically positioned from the edges of the orchestra to about one-third of the hall width in.','Outriggers are two mics set wide to the sides of the main mic array. They stretch the stereo image out to the edges. They also add a sense of the room''s space. Engineers often use them with a Decca Tree on big orchestras.','It exists to increase the width and spaciousness of an orchestral recording, extending the image captured by the central main array out toward the sides of the ensemble.','An engineer flies two omnis wide of the Decca Tree, roughly over the edges of the orchestra, and blends them under the tree for width and hall sound.','Flank miking',ARRAY['Decca Tree','Orchestra flank microphone','Near-flank microphone','Main microphone array','Natural-reverb return']::text[],ARRAY['Spreading outriggers too far apart, leaving a weak or hollow center image.','Skipping time or delay alignment with the main tree, producing comb filtering.','Setting them too loud, so hall ambience and width overwhelm the direct sound.']::text[],ARRAY['Recording a full symphony orchestra with a Decca Tree plus outriggers.','Adding width to a film-score session on a scoring stage.','Broadening the image of a large choral-orchestral work.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='86d8bf78-2c27-5dc9-a5f9-56bb5935d258' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestra outrigger'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '86d8bf78-2c27-5dc9-a5f9-56bb5935d258','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='86d8bf78-2c27-5dc9-a5f9-56bb5935d258' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'ebd4a33e-1e43-57ea-8869-6a4bfb9d0a8c','Orchestral precedence shift','A shift in the perceived location or width of orchestral sources caused by the precedence (Haas) effect when support or spot microphones arrive earlier than, or at similar level to, the main array. Because the ear localizes toward the first-arriving sound within roughly the first 40 ms, an unaligned early spot mic can pull an instrument''s image away from its true position in the main pickup.','The ear points toward whichever sound reaches it first. This is the precedence effect. If a close spot mic arrives before the main mics, the sound seems to move toward that spot mic. That unwanted move is an orchestral precedence shift. Engineers add delay to stop it.','Understanding it lets engineers place and delay support mics so the main array keeps control of localization and instruments stay in their correct stereo positions.','When an instrument drifts off-center after a spot mic is added, an engineer recognizes a precedence shift and delays the spot mic behind the nearest main channel.','Psychoacoustics',ARRAY['Precedence effect','Nearest-main delay reference','Perceptual spot delay','Spot microphone','Main microphone array']::text[],ARRAY['Assuming only level, not timing, moves an image, and ignoring early spot-mic arrivals.','Adding spot-mic level without delay, so instruments jump toward the close mic.','Over-delaying past about 40 ms, turning support into an audible echo instead of fused reinforcement.']::text[],ARRAY['A soloist''s image pulling toward a close mic until delay is added.','Woodwinds shifting left or right when section mics are raised.','Correcting localization after adding spot mics to a main array.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='ebd4a33e-1e43-57ea-8869-6a4bfb9d0a8c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Orchestral precedence shift'),'[^a-z0-9]','','g'));
