INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c3249e0c-11e2-56c7-9e79-8c5a4a6f812c','Podium microphone','A microphone—usually a gooseneck condenser fixed to a lectern or rostrum—positioned to pick up a single person speaking at a podium. It is aimed at the talker''s mouth region to capture clear speech for reinforcement or recording while a directional pattern rejects off-axis room sound and helps control feedback.','A podium is the stand a speaker stands behind to give a talk. A podium mic is a small mic on a bendy neck fixed to it. It points at the speaker''s mouth. It picks up their voice clearly.','It gives clear, consistent pickup of a stationary speaker for sound reinforcement or recording, with a fixed position and directional pattern that resist feedback.','At a conference or ceremony, a tech mounts a gooseneck mic on the lectern, sets it near mouth height, and rings out the system to find a safe level before feedback.','Speech miking',ARRAY['Gooseneck microphone','Cardioid','Feedback','Speech reinforcement','Boundary microphone']::text[],ARRAY['Setting the gooseneck too low or too far, so quiet speakers are barely picked up and gain is pushed toward feedback.','Expecting one fixed podium mic to follow a presenter who steps away from the lectern.','UNSAFE: Pushing gain right to the feedback threshold, which can trigger a sudden loud howl-round that risks hearing and drivers; keep a safe gain-before-feedback margin.']::text[],ARRAY['A conference keynote delivered from a lectern.','A wedding or graduation ceremony with a fixed speaking stand.','A house-of-worship pulpit or a panel moderator''s podium.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c3249e0c-11e2-56c7-9e79-8c5a4a6f812c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Podium microphone'),'[^a-z0-9]','','g'));
