INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e07f7292-2d99-5bd4-9cd3-a49044610616','Propagation-delay insertion','Deliberately adding electronic delay to a microphone or group of mics to compensate for the acoustic propagation (travel) time of sound to more distant mics, so a closer spot/accent mic aligns in time with a distant main array. Because sound travels roughly 343 metres per second—about 2.9 milliseconds per metre in typical air—a spot mic captures its source earlier than the main array, and matching delay realigns the two arrivals.','Sound travels through air at a set speed. A close mic hears a player before a faraway main mic does. Adding a small delay to the close mic lines the two up in time. This keeps the sound clear and correctly placed.','It time-aligns mics at different distances so their combined signals reinforce rather than smear or comb-filter, preserving clarity and a stable stereo image.','In a console or DAW, an engineer measures the distance from a spot mic to the main array and dials that many milliseconds of delay onto the spot channel.','Delay technique',ARRAY['Spot microphone','Sectional-delay grouping','Precedence effect','Comb filtering','Time alignment']::text[],ARRAY['Ignoring propagation delay, so spot mics arrive early, smear transients, and pull the image toward the spot.','Guessing the delay instead of basing it on measured distance and the speed of sound.','Delaying the wrong signal—delaying the main array instead of the closer spot—which worsens the misalignment.']::text[],ARRAY['Aligning accent mics to a Decca Tree in an orchestral recording.','Time-aligning distant ambience mics with a close ensemble pickup.','Matching pit spot mics to a main array in a live broadcast.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e07f7292-2d99-5bd4-9cd3-a49044610616' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Propagation-delay insertion'),'[^a-z0-9]','','g'));
