SELECT 'e07f7292-2d99-5bd4-9cd3-a49044610616','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='e07f7292-2d99-5bd4-9cd3-a49044610616' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '77db9be8-ce1a-512f-b030-6077cfa39f72','Proscenium microphone','A microphone placed at the proscenium—the arch or front frame separating a stage from the auditorium—to capture performers on stage, often as one of several spaced across the proscenium opening. It provides a broad front-of-stage pickup that supplements or backs up individual wireless body mics.','The proscenium is the big frame around the front of a stage. A mic here sits at the edge between the stage and the seats. It catches the actors and singers on stage. It backs up their body mics.','It gives a broad front-of-stage pickup of the ensemble for reinforcement, recording, or as a safety backup when an individual radio mic drops out.','A theatre tech hangs or floor-mounts mics across the proscenium line, sometimes as left-centre-right, to fill in stage sound and cover failed body mics.','Stage miking',ARRAY['Boundary microphone','Rear-facing stage microphone','Spaced pair','Ensemble miking','Feedback']::text[],ARRAY['Pushing proscenium-mic level up for reach, which invites feedback from the nearby front-of-house speakers.','Relying on them for solo clarity when they mainly capture a distant, roomy blend.','UNSAFE: Hanging mics or cables over the stage or audience without rated hardware and safeties; secure all overhead mounts per rigging practice.']::text[],ARRAY['Adding front-fill and stage blend in a musical-theatre production.','Capturing a stage chorus that individual mics cannot cover.','Providing a backup pickup if wireless body mics fail mid-show.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='77db9be8-ce1a-512f-b030-6077cfa39f72' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Proscenium microphone'),'[^a-z0-9]','','g'));
