INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '95ff1809-93ce-5f8a-a3c3-84c8a46aa9d1','Rear-facing stage microphone','A microphone on stage deliberately oriented to face upstage (toward the back of the stage) rather than out toward the audience. Facing rearward lets it capture upstage performers or sections while placing a directional pattern''s rear rejection toward the front-of-house loudspeakers to improve gain before feedback.','Most stage mics point out at the crowd. A rear-facing mic points the other way, toward the back of the stage. It catches performers standing behind it. Its dead side faces the loud speakers, which helps stop feedback.','It captures upstage performers or ambience and aims a directional mic''s rejection null at the main PA, raising how much level the system can reach before feedback.','An engineer turns a cardioid, supercardioid, or hypercardioid mic to face upstage to pick up a back-row section or a performer who has turned away, while keeping feedback down.','Stage miking',ARRAY['Cardioid','Bidirectional microphone','Gain before feedback','Rear-hall microphone','Off-axis rejection']::text[],ARRAY['Forgetting that a rear-facing directional mic still picks up strong reflections and can go unstable if aimed at a hard back wall.','Assuming that facing rearward alone stops feedback, when pattern and placement matter more than orientation.','UNSAFE: Chasing more level near the feedback threshold, which can cause a sudden loud howl that risks hearing and speakers; hold a safe gain margin.']::text[],ARRAY['Picking up an upstage choir riser behind the main performers.','Capturing a soloist who turns upstage during a number.','Adding pickup of a rear section while keeping a null toward the PA.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='95ff1809-93ce-5f8a-a3c3-84c8a46aa9d1' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rear-facing stage microphone'),'[^a-z0-9]','','g'));
