WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='95ff1809-93ce-5f8a-a3c3-84c8a46aa9d1' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '9aa12af1-434b-5b3a-be31-9a78de1c63c3','Rear-hall microphone','A microphone placed toward the rear of a concert hall or auditorium, well back from the ensemble, to capture the room''s reverberation, ambience, and audience response rather than direct sound. Its signal is mixed in at a low level under the main pickup to add depth, hall reverberation, and a sense of space.','A concert hall adds echo and a sense of space to music. A rear-hall mic sits far back near the seats. It catches that room echo and the crowd, not the direct sound. Engineers mix it in low to add depth.','It captures the diffuse reverberant field and audience ambience that, blended under the main mics, add depth, width, and a natural sense of the venue.','For a live recording, an engineer sets ambience mics at the back of the hall or a balcony and rides their level low, to taste, under the main array.','Ambience miking',ARRAY['Ambience microphone','Reverberation','Spaced pair','Room microphone','Propagation-delay insertion']::text[],ARRAY['Bringing rear-hall mics up too far, washing the mix in reverb and losing clarity.','Ignoring the travel-time delay between the stage and the far mics, which can smear the blend.','Placing them where air-handling or audience noise dominates the wanted reverberation.']::text[],ARRAY['Adding hall depth to a close-miked orchestra on a live recording.','Capturing applause and room tone for a concert broadcast.','Blending natural reverberation into a dry ensemble pickup.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='9aa12af1-434b-5b3a-be31-9a78de1c63c3' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Rear-hall microphone'),'[^a-z0-9]','','g'));
