WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='9aa12af1-434b-5b3a-be31-9a78de1c63c3' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '693f558f-3903-5ff1-816e-83436a75a8f0','Sectional-delay grouping','Grouping an ensemble''s microphones by instrumental section—strings, brass, woodwinds, and so on—and applying a common delay to each group so every section aligns in time with the main array or a chosen reference. It extends propagation-delay compensation from single spot mics to whole sections, keeping each section''s spots coherent with the overall stereo image.','An orchestra is split into groups called sections, like strings or brass. Each section may have its own close mics. This method delays each section''s mics together as one group. It lines every section up in time with the main mics.','It manages time alignment efficiently across many mics by treating each section as a unit, preserving coherent imaging and avoiding comb filtering between the section spots and the main array.','On a large session, an engineer buses each section''s spot mics to a group and applies the delay that matches that section''s distance to the main array.','Delay technique',ARRAY['Propagation-delay insertion','Spot microphone','Time alignment','Comb filtering','Subgroup']::text[],ARRAY['Applying one blanket delay to a section whose mics sit at very different distances, leaving some spots misaligned.','Delaying groups without a consistent reference point, so sections align to each other but not to the main array.','Forgetting to update the delays when seating or mic positions change between takes.']::text[],ARRAY['Aligning section spots to the main tree on a film-score orchestral date.','Managing time alignment on a large choral-orchestral recording.','Aligning a divided string section''s spot mics as a group.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='693f558f-3903-5ff1-816e-83436a75a8f0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Sectional-delay grouping'),'[^a-z0-9]','','g'));
