INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '05fd92e4-a768-514b-8499-0823d6bc977b','Spot anchoring','Using a spot (accent) microphone at a low, supportive level to anchor the perceived position and presence of a specific instrument or soloist within the main stereo image, adding definition without dominating the natural balance of the main array. The spot is panned to match the source''s position in the main pickup and delayed to preserve time-of-arrival localization.','A main stereo pair captures the whole group but can leave one player vague. A spot mic sits close to that player. Mixed in low, it locks that player''s place and clarity in the image. It supports the sound without taking over.','It reinforces the clarity and stable placement of one source within an otherwise natural ensemble pickup, without shifting the overall balance the main array captured.','An engineer adds a delayed, low-level spot on a soloist, panned to the soloist''s position in the main image, so that part stays clear and anchored in place.','Spot miking',ARRAY['Spot microphone','Spot localization pull','Propagation-delay insertion','Precedence effect','Panning']::text[],ARRAY['Raising the spot too high, so it stops anchoring and starts dominating, flattening the depth.','Panning the spot away from the source''s natural position, splitting the image.','Skipping delay, so the early spot pulls localization toward itself instead of anchoring it.']::text[],ARRAY['Anchoring a concerto soloist within an orchestral pickup.','Keeping a lead vocalist clear and placed in an ensemble mix.','Defining a woodwind solo passage under a main array.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='05fd92e4-a768-514b-8499-0823d6bc977b' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot anchoring'),'[^a-z0-9]','','g'));
