SELECT '05fd92e4-a768-514b-8499-0823d6bc977b','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='05fd92e4-a768-514b-8499-0823d6bc977b' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '33522795-ac11-5337-bbe1-fdf5fc748147','Spot bloom','The unnatural swelling or enlargement of a source''s presence in a mix when its spot microphone is raised too far or is poorly time-aligned, so the instrument sounds closer, larger, or more diffuse than its natural place in the ensemble. It arises when the spot''s level and early arrival overweight that source against the main array.','A spot mic sits close to one player. Push it up too much and that player seems to swell up. The instrument sounds too big, too close, or smeared. That unnatural swelling is called bloom.','As a named artifact, it helps engineers recognize when a spot mic is over-contributing, so they can pull it back or re-align it; it marks a fault to avoid, not a tool to use.','When an engineer hears a soloist balloon in size as the spot fader comes up, they identify bloom and reduce the spot''s level or fix its delay.','Spot miking',ARRAY['Spot microphone','Spot anchoring','Spot exposure','Propagation-delay insertion','Proximity effect']::text[],ARRAY['Adding spot level for clarity and mistaking the resulting bloom for a bigger, better sound.','Blaming EQ for the swelling when the real cause is spot level and timing.','Trying to tame bloom with compression instead of pulling the spot back or delaying it.']::text[],ARRAY['A solo violin ballooning when its spot mic is pushed up.','A piano feeling too close and large as its lid spot rises.','Over-hot brass spots swelling the section out of proportion.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='33522795-ac11-5337-bbe1-fdf5fc748147' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot bloom'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '33522795-ac11-5337-bbe1-fdf5fc748147','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
