INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'e715830d-b6d3-5257-8e0a-930859b51dc0','Spot exposure','The degree to which a spot microphone reveals a source''s close-up detail—articulation, mechanical noise, and imperfections—within the overall mix, set by the spot''s level relative to the main array. Higher exposure brings out intimacy and definition but also breath, key, and intonation flaws that the distant main pickup would otherwise soften.','A close spot mic hears every detail of one player. How much of that detail you let into the mix is its exposure. More exposure means more clarity, but also more squeaks, breaths, and slips. Less exposure keeps the player smooth and blended.','It describes and controls how much of a source''s close-up character reaches the mix, letting engineers trade intimacy and detail against blend and forgiveness.','An engineer sets each spot''s fader to expose just enough detail for clarity while keeping player noise and intonation issues at an acceptable level.','Spot miking',ARRAY['Spot microphone','Spot anchoring','Spot bloom','Spot masking','Signal-to-noise ratio']::text[],ARRAY['Over-exposing a spot so key clicks, breaths, or bow noise become distracting.','Under-exposing every spot, leaving the mix distant and undefined.','Judging exposure with the spot soloed rather than in the full mix, where masking changes what is heard.']::text[],ARRAY['Deciding how present a woodwind spot should sit in the balance.','Exposing a soloist for detail on a studio recording.','Trading detail against polish on a live ensemble capture.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='e715830d-b6d3-5257-8e0a-930859b51dc0' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot exposure'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'e715830d-b6d3-5257-8e0a-930859b51dc0','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
