INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f1fe7a3c-1523-52fc-9784-4f9aa731cc3f','Spot localization pull','The tendency of a spot microphone to shift a source''s perceived stereo position away from where the main array places it, because the spot''s earlier arrival and higher level dominate localization through the precedence effect and summing localization. Without compensating delay and careful level, the source is pulled toward the spot mic''s pan location.','Your ears place a sound using which mic''s signal arrives first and loudest. A close spot mic often wins that race. So the player seems to move toward where the spot is panned. That shift is the localization pull.','Naming this effect helps engineers predict and control how spot mics move a source in the image, so they can keep placement natural using delay and level.','When a soloist drifts off their natural spot as the spot mic comes up, the engineer adds delay and trims level to pull the image back into place.','Spot miking',ARRAY['Precedence effect','Spot microphone','Propagation-delay insertion','Summing localization','Panning']::text[],ARRAY['Re-panning a spot to fix a pull instead of delaying it, which fights the main array''s cues.','Assuming level alone sets position and ignoring the stronger effect of arrival time.','Missing the pull because spots are auditioned soloed rather than against the main array.']::text[],ARRAY['A soloist appearing to jump toward one side as a spot mic is raised.','Keeping a section anchored in place under a Decca Tree.','Correcting an image shift in a live orchestral mix.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f1fe7a3c-1523-52fc-9784-4f9aa731cc3f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot localization pull'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'f1fe7a3c-1523-52fc-9784-4f9aa731cc3f','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f1fe7a3c-1523-52fc-9784-4f9aa731cc3f' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'c23bf085-9463-583f-9bbb-c4bfa6158bb2','Spot masking','The masking of quieter sources or of the main array''s detail and ambience when a spot microphone''s signal is raised, so louder or spectrally overlapping spot content psychoacoustically hides softer sounds. It applies auditory masking to the spot-versus-main balance: an over-prominent spot can bury inner voices, room sound, or neighbouring sections.','A louder sound can hide a softer one from your ears. This is called masking. Push a spot mic up and it can cover quieter players or the room sound. Details you wanted then get buried.','Naming this effect helps engineers recognize when a hot spot is hiding wanted detail, so they can rebalance level and EQ to keep inner parts audible.','When inner harmonies vanish as a spot comes up, the engineer lowers or EQs the spot so the masked parts return.','Spot miking',ARRAY['Auditory masking','Spot microphone','Spot exposure','Spot bloom','Frequency masking']::text[],ARRAY['Raising a spot to hear one part while unknowingly masking several others.','Fixing masked detail by boosting other spots, starting a loudness war within the mix.','Ignoring frequency overlap, where a spot masks parts sharing its range even at modest levels.']::text[],ARRAY['A brass spot burying inner strings in a tutti passage.','A piano spot masking hall reverberation in the blend.','Balancing a dense ensemble so every section stays audible.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='c23bf085-9463-583f-9bbb-c4bfa6158bb2' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot masking'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT 'c23bf085-9463-583f-9bbb-c4bfa6158bb2','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
