INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'f4ed6c9f-f5cc-5441-b80c-e67db3d8803e','Spot pre-arrival','The condition in ensemble recording where a spot (accent) microphone, being much closer to its instrument than the distant main array, captures that instrument''s direct sound earlier in time than the main array does. Because sound travels at roughly 343 metres per second, a spot placed several metres nearer receives the wavefront several milliseconds ahead, so if the spot is not delayed its earlier arrival triggers the precedence effect and comb filtering against the mains.','A spot mic sits close to one instrument. The far main mics are much farther away. So the spot mic hears that instrument first, a few thousandths of a second early. This head start can pull the sound off to one side and blur its tone.','Naming the early arrival explains why spot mics must often be time-delayed: their head start over the main array otherwise steals localization and colors the tone through phase interference.','An engineer measures or estimates the extra distance from instrument to main array, then delays the spot so its once-early signal lines up with the later main pickup.','Spot miking',ARRAY['Spot-microphone delay','Precedence effect','Comb filtering','Main array','Spot-to-main balance','Transient-reference alignment']::text[],ARRAY['Ignoring the early arrival entirely, so the spotted instrument localizes to the spot mic instead of its true stage position.','Assuming pre-arrival matters only for level, when its timing also causes comb-filter coloration against the mains.','Delaying purely by measured distance without checking by ear, which can worsen phase when players move.']::text[],ARRAY['Explaining to a student why a close cello mic must be delayed to the main tree.','Diagnosing why a spotted soloist pulls hard toward one speaker before delay is applied.','Planning delay compensation before a large orchestral session.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='f4ed6c9f-f5cc-5441-b80c-e67db3d8803e' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot pre-arrival'),'[^a-z0-9]','','g'));
