WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='f4ed6c9f-f5cc-5441-b80c-e67db3d8803e' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '580963ca-1b6e-58f3-a5e3-f2f823437e0f','Spot prominence','The degree to which a spot (accent) microphone makes its instrument stand forward in level and clarity relative to the main array and the rest of the ensemble. Prominence is set mainly by the spot-to-main balance and by any delay, equalization, or reverb applied to the spot channel.','Prominence means how much a spot mic makes its instrument stand out. Turn the spot mic up and that instrument jumps forward. Turn it down and it blends back into the group. Engineers set this level to fit the music.','It exists as the control an engineer uses to feature or restrain an instrument, shaping which lines lead the ensemble without re-balancing the players themselves.','During a mix an engineer rides a soloist''s spot fader up for a feature passage, then eases it back so the instrument settles into the orchestral blend.','Spot miking',ARRAY['Spot-to-main balance','Spot microphone','Main array','Spot-led orchestral mix','Spotty orchestral image','Spot-microphone delay']::text[],ARRAY['Pushing a spot mic so high that the instrument sounds detached and unnaturally close against the room.','Judging prominence from the soloed spot mic rather than from its blend with the main array.','UNSAFE: Cranking monitor level to hear a soloed close mic on loud brass or percussion; sustained exposure above about 85 dBA risks hearing damage, so keep levels moderate and use hearing protection.']::text[],ARRAY['Bringing a concerto soloist forward over the orchestra during their entrance.','Restoring a woodwind line that is buried under the main array.','Deciding how far to feature a harp accent in a film score cue.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='580963ca-1b6e-58f3-a5e3-f2f823437e0f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot prominence'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '580963ca-1b6e-58f3-a5e3-f2f823437e0f','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
