INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '772b411f-22da-5700-b06e-ae412bd1dcef','Spot spread','The panning of an ensemble''s spot (accent) microphones across the stereo field so each spotted instrument sits at the same left-to-right position it occupies in the main array''s image. Correct spot spread keeps close mics aligned with the stereo picture built by the main pickup rather than clustering instruments at the center or the wrong side.','Instruments sit in different places on stage, left to right. Spot spread means panning each spot mic to match that place. A left-side violin is panned left. This keeps the close mics lined up with the main stereo picture.','It exists to make spot mics reinforce the main array''s stereo image instead of fighting it, preserving a believable stage layout.','An engineer pans each spot to match the instrument''s seat as heard in the mains, checking that a spotted section does not jump to a different location when its fader comes up.','Spot miking',ARRAY['Panning','Main array','Spot-to-main balance','Stereo image','Spotty orchestral image','Spot-induced image collapse']::text[],ARRAY['Panning all spot mics to center, which drags instruments out of their true stage positions.','Panning a spot to the opposite side from where the instrument sits in the mains, smearing its image.','Spreading spots so wide that the ensemble sounds pulled apart rather than coherent.']::text[],ARRAY['Placing string-section spots to match the tree image in an orchestral mix.','Setting up a template so spot pans follow a standard seating plan.','Correcting a spotted brass section that localizes to the wrong side.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='772b411f-22da-5700-b06e-ae412bd1dcef' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot spread'),'[^a-z0-9]','','g'));
