SELECT '772b411f-22da-5700-b06e-ae412bd1dcef','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='772b411f-22da-5700-b06e-ae412bd1dcef' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '4184130c-e294-55ad-abc6-83836ef9c2fa','Spot-induced image collapse','The narrowing or destabilizing of the main array''s stereo image caused by spot (accent) microphones that are too loud or not time-aligned. Because their earlier, often near-mono signals invoke the precedence effect and comb-filter against the mains, instruments snap toward the spot mic''s pan position and the natural width and depth of the picture collapse.','The main mics create a wide, natural stereo picture. A spot mic that is too loud or too early can wreck it. The sound snaps toward the spot mic and the width shrinks. Delaying and easing back the spot mic fixes this.','Naming this failure warns engineers that adding spot level or leaving spots undelayed can undo the imaging the main array was chosen to provide.','When width suddenly shrinks as spots come up, an engineer lowers the spot level, applies delay, and re-checks panning until the main image reopens.','Spot miking',ARRAY['Precedence effect','Comb filtering','Spot-microphone delay','Spot-to-main balance','Stereo image','Main array']::text[],ARRAY['Adding spot level to ''improve clarity'' without noticing the stereo image has narrowed.','Blaming the main array for a collapsed image that is actually caused by hot, undelayed spots.','Fixing collapse with panning alone while ignoring the missing spot delay that caused it.']::text[],ARRAY['Troubleshooting an orchestral mix that goes narrow whenever the spots are raised.','Teaching why undelayed close mics ruin a Decca tree''s width.','Recovering depth in a choir recording after spot mics flattened the image.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='4184130c-e294-55ad-abc6-83836ef9c2fa' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot-induced image collapse'),'[^a-z0-9]','','g'));
