SELECT '4184130c-e294-55ad-abc6-83836ef9c2fa','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='4184130c-e294-55ad-abc6-83836ef9c2fa' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '70d456ed-ce82-51be-87fb-5582104e2816','Spot-led orchestral mix','An orchestral mixing approach in which the spot (accent) microphones carry the primary balance and detail, while the main array and ambience mics are used mainly to add blend, depth, and hall sound. It contrasts with a main-array-led approach, trading some natural spatial realism for greater control over individual sections and soloists.','There are two ways to build an orchestra mix. A spot-led mix leans on the close mics for the main balance. The far room mics just add glue and space. This gives more control but can sound less natural.','It exists to give the mixer detailed control over every section, which suits film, television, and pop-orchestral work where clarity and edit flexibility outweigh purist realism.','A scoring engineer builds the balance from spot mics, then folds the tree and ambience mics underneath for cohesion and reverberant tail.','Orchestral mixing',ARRAY['Spot-to-main balance','Main array','Spot prominence','Ambience microphone','Spot-microphone delay','Decca tree']::text[],ARRAY['Leaning so hard on spots that the mix loses the hall and sounds dry and artificial.','Forgetting to delay the spots, so the heavy close-mic balance combs against the mains.','Treating a spot-led method as always superior, when many classical productions favor a main-array-led balance.']::text[],ARRAY['Mixing an orchestral film score that needs each section clearly controllable.','Producing a pop record with a live string section that must sit tightly in the track.','Choosing a mixing strategy before a hybrid orchestral session.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='70d456ed-ce82-51be-87fb-5582104e2816' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot-led orchestral mix'),'[^a-z0-9]','','g'));
