SELECT '70d456ed-ce82-51be-87fb-5582104e2816','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='70d456ed-ce82-51be-87fb-5582104e2816' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT 'bc4cf56b-fd1e-54c8-b5ba-9218211dcb84','Spot-microphone delay','The deliberate time-delaying of spot (accent) microphone signals so they align with the later-arriving main array, compensating for the spot''s shorter path to the instrument. Aligning the arrivals preserves the main array''s stereo imaging, reduces comb filtering, and keeps the precedence effect anchored to the mains rather than to the close mics.','A spot mic is closer, so its sound arrives early. Delaying it makes it line up with the far main mics. This keeps the stereo picture solid and clean. Without it the tone can sound hollow and thin.','It exists to stop a closer spot mic from arriving first and hijacking localization or comb-filtering the mains, so added detail does not damage the overall image.','An engineer estimates the distance from instrument to main array, sets a starting delay, then fine-tunes by ear or by lining up transients until the spot blends without hollowness.','Spot miking',ARRAY['Spot pre-arrival','Precedence effect','Comb filtering','Transient-reference alignment','Main array','Spot-to-main balance']::text[],ARRAY['Skipping delay entirely, leaving spots early enough to pull image and comb-filter the mains.','Delaying every spot strictly by measured distance, which can cause phasing when musicians shift position.','UNSAFE: Hot-patching a condenser spot microphone with phantom power live, which can send a loud thump through the system; mute or pull the fader and let phantom power settle before connecting.']::text[],ARRAY['Time-aligning woodwind and brass spots to a Decca tree in post.','Setting delays on section mics for a large choir and orchestra recording.','Cleaning up a hollow, phasey blend traced to undelayed close mics.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='bc4cf56b-fd1e-54c8-b5ba-9218211dcb84' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot-microphone delay'),'[^a-z0-9]','','g'));
