SELECT 'bc4cf56b-fd1e-54c8-b5ba-9218211dcb84','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='bc4cf56b-fd1e-54c8-b5ba-9218211dcb84' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '443af6fe-f684-575e-b614-81d5350f7d83','Spot-to-hall mismatch','A timbral and spatial disconnect that occurs when the close, dry, direct sound of a spot (accent) microphone fails to blend with the reverberant hall sound captured by the main array and ambience mics. The spotted instrument then sounds too near, dry, and forward against the ambient orchestra, breaking the sense of a single shared space.','A spot mic hears dry, close, direct sound. The main mics hear the full room echo, or hall sound. If the two do not match, the spotted instrument sounds too close and dry. Adding a little delay and reverb helps them blend.','Naming this problem guides engineers to reconcile the dry spot with the wet main picture so a featured instrument still lives in the same hall as the ensemble.','An engineer delays the spot, adds a matching reverb or ambience send, and trims its level so the spotted instrument sits in the hall rather than in front of it.','Spot miking',ARRAY['Spot-microphone delay','Ambience microphone','Spot-to-main balance','Main array','Stage-rear ambience microphone','Spot-induced image collapse']::text[],ARRAY['Raising a dry spot without any delay or reverb, so it floats unnaturally in front of the hall.','Adding so much reverb to a spot that it becomes washy and loses the clarity it was added for.','Trying to fix the mismatch with equalization alone while ignoring the missing time and space cues.']::text[],ARRAY['Blending a dry soloist spot into a reverberant cathedral recording.','Matching a close harp mic to the ambience of a concert hall.','Seating a featured trumpet believably within an orchestral hall sound.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='443af6fe-f684-575e-b614-81d5350f7d83' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot-to-hall mismatch'),'[^a-z0-9]','','g'));
