SELECT '443af6fe-f684-575e-b614-81d5350f7d83','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='443af6fe-f684-575e-b614-81d5350f7d83' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '79bf0a04-551a-5079-8ef0-a35e67b87873','Spot-to-main balance','The relative level balance set between the spot (accent) microphones and the main stereo array in an ensemble recording. It governs how much close detail is added to the natural, blended sound of the mains, and is the primary control over clarity versus spaciousness in the final image.','This is the level balance between the close spot mics and the far main mics. More spot mic means more clear detail. More main mic means more natural room sound. Engineers ride this balance to taste.','It exists as the core blend control in ensemble recording, letting an engineer add just enough spot detail without overwhelming the imaging and ambience the main array provides.','An engineer starts from the main array alone, then brings spots up only until sections gain clarity, backing off before the natural blend is lost.','Spot miking',ARRAY['Main array','Spot prominence','Spot-microphone delay','Spot-led orchestral mix','Ambience microphone','Decca tree']::text[],ARRAY['Building the balance from the spots first, then never letting the main array establish the natural picture.','Adding spot level for clarity while ignoring the resulting narrowing of the stereo image.','Setting the balance while spots are undelayed, so raising them combs the sound instead of adding detail.']::text[],ARRAY['Dialing in how much close-mic detail to add over a Decca tree.','Balancing accent mics against room mics in a live orchestral broadcast.','Teaching students to build a blend up from the mains rather than down from the spots.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='79bf0a04-551a-5079-8ef0-a35e67b87873' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spot-to-main balance'),'[^a-z0-9]','','g'));
