SELECT '79bf0a04-551a-5079-8ef0-a35e67b87873','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='79bf0a04-551a-5079-8ef0-a35e67b87873' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '5cd0c229-0d0b-5ad2-b2b8-91e443dc7e0f','Spotty orchestral image','An uneven, patchy stereo image in an orchestral recording where over-reliance on, or poor integration of, spot (accent) microphones makes some instruments jump out unnaturally close and loud while others sit too far back. The result lacks the coherent, continuous stage picture that a well-balanced main array provides, leaving lumps and holes across the field.','A good orchestra recording sounds like one connected group. A spotty image is patchy and uneven. Some instruments jump out too close and loud. Others sit too far back, leaving holes in the picture.','Naming this fault helps engineers recognize when spot mics have fragmented the ensemble instead of supporting a unified image.','An engineer hearing a lumpy stage picture reduces the most exposed spots, checks their panning and delay, and leans more on the main array to restore continuity.','Stereo imaging',ARRAY['Spot-to-main balance','Spot prominence','Main array','Stereo image','Spot spread','Spot-induced image collapse']::text[],ARRAY['Adding a spot to every section ''for safety'' and ending up with a disjointed, patchy stage.','Fixing loud, isolated instruments with equalization instead of rebalancing the spots against the mains.','Confusing a spotty image with a poor main-array position, when the spots are the real cause.']::text[],ARRAY['Critiquing a student mix where instruments pop out at random depths.','Repairing an orchestral recording that sounds like separate close-miked tracks.','Explaining why less spot level often yields a more natural stage picture.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='5cd0c229-0d0b-5ad2-b2b8-91e443dc7e0f' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Spotty orchestral image'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '5cd0c229-0d0b-5ad2-b2b8-91e443dc7e0f','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='5cd0c229-0d0b-5ad2-b2b8-91e443dc7e0f' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '1979d92e-ac96-5e01-bfb9-504853ea2b9c','Stage-rear ambience microphone','A microphone positioned toward the rear of the stage, behind or above the ensemble and facing into the room, to capture reverberant hall sound from a perspective behind the players. Its largely diffuse, reflected signal is blended in to add depth, space, and envelopment, and in surround work can feed rear channels.','This mic sits behind or above the orchestra, facing the room. It captures the hall echo from behind the players. Engineers blend it in to add depth and space. It is not used for close detail.','It exists to gather reverberant energy and a sense of the room from behind the ensemble, giving a mix depth and surround width that close and main mics cannot supply.','An engineer hangs or stands a mic behind the orchestra, blends it low under the mains for depth, and may route it to rear channels in a surround or immersive mix.','Ambience miking',ARRAY['Ambience microphone','Main array','Spot-to-hall mismatch','Reverberation','Spot-to-main balance','Decca tree']::text[],ARRAY['Placing the rear mic too close to loud brass or percussion, so it captures direct blare instead of diffuse hall sound.','Blending it in too loud, which muddies the mix and pushes the ensemble unnaturally far away.','UNSAFE: Working directly behind loud brass or percussion to set the mic without hearing protection; sustained levels above about 85 dBA risk hearing damage, so wear earplugs and limit exposure.']::text[],ARRAY['Adding hall depth to an orchestral recording in a good-sounding room.','Feeding rear channels for a surround or immersive classical release.','Capturing envelopment behind a choir in a reverberant church.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='1979d92e-ac96-5e01-bfb9-504853ea2b9c' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Stage-rear ambience microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
