WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='1979d92e-ac96-5e01-bfb9-504853ea2b9c' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '27dfc3ef-15c4-5874-80f7-c6b5ad5f4047','String outrigger','A widely spaced omnidirectional microphone, one of a flanking pair placed outside the main array and toward the string sections, used in orchestral recording to add width and a fuller, richer string sound. Outriggers extend the stereo image beyond the main tree and reinforce the body and low end of the strings on the outer edges of the stage.','Outriggers are a wide, spaced pair of mics outside the main array. Placed near the strings, they capture a full, rich string sound. They also widen the stereo picture. Many orchestral recordings add them for size.','They exist to broaden the stereo image and strengthen the strings, filling out the sides of a picture that the closer-spaced main tree alone can leave narrow.','An engineer sets a spaced pair of omnis wide and slightly forward, favoring the front strings, then blends them under the main tree for width and string body.','Array miking',ARRAY['Decca tree','Main array','Spaced pair','Ambience microphone','Stereo image','Spot-to-main balance']::text[],ARRAY['Spacing outriggers so wide that the center of the image sags and the orchestra sounds split into two sides.','Placing them so far back that they add mostly reverberation instead of the intended string body.','UNSAFE: Hot-patching a phantom-powered condenser outrigger with the channel live, risking a loud thump through the system; mute or pull the fader and let phantom power settle before connecting.']::text[],ARRAY['Widening a Decca-tree orchestral recording with a flanking omni pair.','Adding string weight to a film-score session on a large stage.','Filling out the sides of a narrow main-array image on a symphony date.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='27dfc3ef-15c4-5874-80f7-c6b5ad5f4047' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('String outrigger'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
