WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='27dfc3ef-15c4-5874-80f7-c6b5ad5f4047' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '72a2de3a-8cb0-5399-b1b7-cf07d0fe9823','Transient-reference alignment','Time-aligning several microphone signals by using a shared, sharp transient event, such as a percussive attack or plucked note, as the timing reference and lining up its leading edge across the tracks. It is a practical way to find and correct inter-microphone delay, for example between spot mics and the main array, so their combined sound stays clean rather than comb-filtered.','A transient is a sharp attack, like a drum hit or a plucked note. It shows up as a clear spike in the recording. Engineers line these spikes up across different mics. This times the mics together so they do not smear the sound.','It exists to give engineers a visible, repeatable way to align mics in time, replacing pure distance math with the actual recorded arrival of a common event.','In an editor an engineer zooms in on a shared transient, nudges each spot track so its attack lines up with the main array, and confirms the blend sounds fuller and clearer.','Time alignment',ARRAY['Spot-microphone delay','Comb filtering','Spot pre-arrival','Main array','Phase','Spot-to-main balance']::text[],ARRAY['Aligning to the wrong transient, such as a reflection instead of the direct attack, and worsening the phase.','Nudging tracks by eye only and never confirming the result by ear.','Assuming one alignment holds for a whole take when players move and change the true arrival times.']::text[],ARRAY['Lining up spot mics to the main tree using an orchestral downbeat.','Aligning close and room mics on a percussion section by their attacks.','Tightening multi-mic blends during editing of a live ensemble recording.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='72a2de3a-8cb0-5399-b1b7-cf07d0fe9823' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Transient-reference alignment'),'[^a-z0-9]','','g'));
