WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='72a2de3a-8cb0-5399-b1b7-cf07d0fe9823' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,achievement_id)
SELECT '77e2a44f-e919-5833-91d4-d3232811cfe4','Under-balcony microphone','A microphone placed beneath a hall''s balcony overhang, where the projecting structure shadows sound from the upper room volume and yields a drier, more direct signal with reduced high-frequency reverberation. In ensemble recording it is used as an ambience or coverage mic offering a closer, less reverberant perspective than mics out in the open hall.','Many concert halls have a balcony that hangs over the seats below. Under that overhang the sound is drier with less echo. A mic placed there captures that closer, shadowed sound. Engineers use it for extra coverage or a different room flavor.','It exists to capture a distinct, drier acoustic perspective from the shadowed under-balcony zone, useful when the open-hall ambience is too reverberant or a closer room sound is wanted.','An engineer sets a mic under the balcony overhang, then blends its drier, more direct signal against the wetter main and hall mics to tune the overall sense of distance.','Ambience miking',ARRAY['Ambience microphone','Reverberation','Stage-rear ambience microphone','Main array','Spot-to-hall mismatch','Room acoustics']::text[],ARRAY['Expecting a full, reverberant hall sound from a spot the overhang deliberately shadows and darkens.','Blending it too loud, which flattens the depth the open-hall mics provide.','Ignoring that the overhang rolls off highs, then blaming the microphone for a dull tone.']::text[],ARRAY['Capturing a drier ambience option in an overly reverberant hall.','Covering a choir or ensemble seated near a balcony overhang.','Blending a closer room perspective into an orchestral mix.']::text[],'92eda6e7-32ec-432c-9bd3-18bfe726233f'
WHERE NOT EXISTS (SELECT 1 FROM glossary g WHERE g.id='77e2a44f-e919-5833-91d4-d3232811cfe4' OR regexp_replace(lower(g.term),'[^a-z0-9]','','g')=regexp_replace(lower('Under-balcony microphone'),'[^a-z0-9]','','g'));
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary)
SELECT '77e2a44f-e919-5833-91d4-d3232811cfe4','92eda6e7-32ec-432c-9bd3-18bfe726233f',true
WHERE NOT EXISTS (SELECT 1 FROM glossary_topics gt WHERE gt.glossary_id='77e2a44f-e919-5833-91d4-d3232811cfe4' AND gt.achievement_id='92eda6e7-32ec-432c-9bd3-18bfe726233f');
COMMIT;
